def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected structure
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object must define '_keys' and '_values' attributes")

    # Build a fast lookup for name to index
    if isinstance(self._keys, dict):
        name_to_index = self._keys
    else:
        try:
            name_to_index = {name: idx for idx, name in enumerate(self._keys)}
        except Exception as e:
            raise RuntimeError(f"Failed to build key index mapping: {e}")

    all_values = self._values
    all_names = self._keys
    total = len(all_names)

    # Helper to get value by index with bounds checking
    def _value_at(idx):
        if idx < 0 or idx >= total:
            raise IndexError(f"Index {idx} out of bounds (valid range 0-{total - 1})")
        return all_values[idx]

    # If no keys specified, return the entire record
    if not keys:
        result = {}
        for name in all_names:
            idx = name_to_index.get(name)
            if idx is None:
                # This should not happen if data integrity is maintained
                result[name] = None
            else:
                result[name] = _value_at(idx)
        return result

    # Build result for requested keys
    result = {}
    for key in keys:
        if isinstance(key, int):
            name = _value_at(key)  # will raise IndexError if out of bounds
            name = all_names[key]
            result[name] = _value_at(key)
        elif isinstance(key, str):
            if key in name_to_index:
                idx = name_to_index[key]
                result[key] = _value_at(idx)
            else:
                result[key] = None
        else:
            raise TypeError(f"Unsupported key type {type(key).__name__}; must be int or str")

    return result<|return|>

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian 16‑bit unsigned integer."""
    try:
        # Identify the internal buffer. Adjust attribute name if different.
        if hasattr(self, "_buffer"):
            buffer = self._buffer
        elif hasattr(self, "data"):
            buffer = self.data
        else:
            raise AttributeError("No suitable buffer attribute found for pop_u16.")

        if len(buffer) < 2:
            raise ValueError("Not enough data to pop 2 bytes.")

        # Extract and remove the last two bytes
        last_two = buffer[-2:]
        if isinstance(buffer, bytearray):
            del buffer[-2:]
        else:
            # For immutable bytes objects, create a new slice without the last two bytes
            buffer = buffer[:-2]
            setattr(self, "_buffer" if hasattr(self, "_buffer") else "data", buffer)

        # Convert to an unsigned integer (big‑endian)
        return int.from_bytes(last_two, byteorder="big")
    except Exception as ex:
        raise ex from None<|return|>

