def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass with specified fields and SRID mapping. """
    if not isinstance(name, str):
        raise TypeError(f"The class name must be a string, got {type(name).__name__}")
    # Ensure fields is iterable of strings
    try:
        iter(fields)
    except TypeError:
        raise TypeError("fields must be an iterable of strings")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary mapping field names to SRIDs")
    # Validate field names
    seen = set()
    for field in fields:
        if not isinstance(field, str):
            raise TypeError(f"Field name must be a string: {field!r}")
        if not field.isidentifier():
            raise TypeError(f"Field names must be valid identifiers: {field!r}")
        if keyword.iskeyword(field):
            raise TypeError(f"Field names must not be keywords: {field!r}")
        if field in seen:
            raise TypeError(f"Duplicate field name: {field!r}")
        seen.add(field)
    # Validate SRID mapping
    for key in srid_map:
        if key not in seen:
            raise ValueError(f"SRID map contains unknown field: {key!r}")
    # Build namespace for new class
    namespace = {
        "__slots__": tuple(fields),
        "SRID_MAP": dict(srid_map),
    }
    # Dynamically create class inheriting from Point
    try:
        cls = types.new_class(name, (Point,), {}, lambda ns: ns.update(namespace))
    except Exception as exc:
        raise TypeError(f"Failed to create point subclass '{name}': {exc}") from exc
    return cls<|return|>

