    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")

    def decorator(func):
        def wrapper(*args, **kwargs):
            # Emit a DeprecationWarning each time the function is called
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        # Preserve the wrapped function's attributes
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__dict__.update(func.__dict__)

        # Optionally add a deprecation note to the docstring
        deprecation_note = f"\n\nDeprecated: {message}"
        if wrapper.__doc__:
            wrapper.__doc__ += deprecation_note
        else:
            wrapper.__doc__ = deprecation_note

        return wrapper

    return decorator<|return|>

