@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback
        import os

        try:
            if e is None:
                return "None"

            # Determine exception type and message
            exc_type = type(e).__name__
            exc_msg = str(e)

            # Build the trace string
            tb = getattr(e, "__traceback__", None)
            if tb is None:
                return f"{exc_type}: {exc_msg}"

            # Extract traceback frames
            frames = traceback.extract_tb(tb)
            if not frames:
                return f"{exc_type}: {exc_msg}"

            # Helper to shorten file paths
            def _short_path(path, max_parts):
                try:
                    if not path:
                        return path
                    parts = path.split(os.sep)
                    if len(parts) > max_parts:
                        return os.sep.join(parts[-max_parts:])
                    return path
                except Exception:
                    return path

            trace_lines = []
            for i, frame in enumerate(frames[:max_level]):
                short_path = _short_path(frame.filename, max_path_level)
                line_content = (
                    f'  File "{short_path}", line {frame.lineno}, in {frame.name}'
                )
                trace_lines.append(line_content)
                if frame.line:
                    trace_lines.append(f'    {frame.line.strip()}')

            trace_str = "\n".join(trace_lines)
            return f"{exc_type}: {exc_msg}\n{trace_str}"
        except Exception:
            # Fallback: return a simple representation if anything goes wrong
            return f"{type(e).__name__}: {str(e)}"<|return|>

