    def _reset_logging(cls):
        """Reset logging configuration to a clean default state."""
        try:
            root = logging.getLogger()
            # Remove all handlers from the root logger
            for h in root.handlers[:]:
                try:
                    h.close()
                except Exception:
                    pass
                root.removeHandler(h)
            root.setLevel(logging.WARNING)

            # Remove handlers from any other existing loggers
            for logger in list(logging.Logger.manager.loggerDict.values()):
                if isinstance(logger, logging.Logger):
                    for h in logger.handlers[:]:
                        try:
                            h.close()
                        except Exception:
                            pass
                        logger.removeHandler(h)
                    logger.setLevel(logging.WARNING)

            # Clear the internal logger cache if available
            acquire = getattr(logging, "_acquireLock", None)
            release = getattr(logging, "_releaseLock", None)
            if acquire and release:
                acquire()
                try:
                    logging.root.manager.loggerDict.clear()
                finally:
                    release()
        except Exception:
            # Suppress all exceptions to avoid interfering with caller
            pass<|return|>

