            # If import fails, fall back to the implementation class itself
            return impl_cls
        # Retrieve the target class from the module
        module = globals().get("__import__")("sys").modules[module_name]
        try:
            return getattr(module, base_name)
        except AttributeError:
            # If the base class is not found, return the original class
            return impl_cls
