def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ...     ['x', 'y', 'z'],
    ...     ['q', 'z'],
    ...     [1, 3, 5],
    ...     ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list of lists")
    # adjacency list and indegree count
    adjacency = {}
    indegree = {}
    appearance = {}
    seen = set()
    order_counter = 0

    for ordering in orderings:
        if not isinstance(ordering, (list, tuple)):
            raise TypeError("Each ordering must be a list or tuple")
        for i, item in enumerate(ordering):
            if item not in seen:
                appearance[item] = order_counter
                order_counter += 1
                seen.add(item)
            if item not in adjacency:
                adjacency[item] = set()
            if item not in indegree:
                indegree[item] = 0
            # add edges to all following items in this ordering
            for j in range(i + 1, len(ordering)):
                child = ordering[j]
                # ensure child entry
                if child not in adjacency:
                    adjacency[child] = set()
                if child not in indegree:
                    indegree[child] = 0
                # avoid duplicate edges
                if child not in adjacency[item]:
                    adjacency[item].add(child)
                    indegree[child] += 1

    # Kahn's algorithm with stable ordering based on first appearance
    zero = [node for node, deg in indegree.items() if deg == 0]
    zero.sort(key=lambda n: appearance.get(n, float('inf')))
    result = []

    while zero:
        node = zero.pop(0)
        result.append(node)
        for nei in adjacency.get(node, []):
            indegree[nei] -= 1
            if indegree[nei] == 0:
                zero.append(nei)
                zero.sort(key=lambda n: appearance.get(n, float('inf')))

    if len(result) != len(indegree):
        # cycle detected
        raise ValueError("orderings contain a cycle, cannot merge")
    return result
<|return|>

