def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    result = []
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"'{c!r}' is not a class")
        # Skip if already covered by a previous base
        if any(issubclass(c, r) or c == r for r in result):
            continue
        # Remove any bases that are subclasses of the new candidate
        result = [r for r in result if not issubclass(r, c)]
        result.append(c)
    return tuple(result)<|return|>

