    minimal = []
    for cls in ordered:
        # If another class in 'ordered' is a subclass of 'cls', skip 'cls'
        if any(cls is not other and issubclass(other, cls) for other in ordered):
            continue
        minimal.append(cls)

    return minimal<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of class objects")
    # Validate that all items are classes
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"item {cls!r} is not a class")
    # Build result preserving order, but only keep classes that are not
    # superclasses of any other in the input list.
    result = []
    seen = set()
    for cls in classes:
        if cls in seen:
            continue  # skip duplicates
        redundant = False
        for other in classes:
            if other is cls:
                continue
            if issubclass(other, cls):
                redundant = True
                break
        if not redundant:
            result.append(cls)
            seen.add(cls)
    return result<|return|>

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean value")
    result = []
    for name in dir(self):
        if not all and name.startswith('_'):
            continue
        try:
            attr = getattr(self, name)
        except Exception:
            continue
        description = None
        if hasattr(attr, "__doc__") and attr.__doc__:
            description = attr.__doc__
        if description is None:
            # Check if it's a property defined on the class
            cls = self.__class__
            cls_attr = cls.__dict__.get(name, None)
            if isinstance(cls_attr, property) and cls_attr.__doc__:
                description = cls_attr.__doc__
        if description is None:
            description = ""
        result.append((name, description))
    return result<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Return a dictionary mapping attribute names (excluding private ones)
    # to their docstrings (or an empty string if no docstring is available).
    # If ``all`` is True, search in the entire class hierarchy; otherwise,
    # only inspect the immediate class of ``self``.
    result = {}
    try:
        classes = (self.__class__,) if not all else self.__class__.__mro__
        for cls in classes:
            for name, value in cls.__dict__.items():
                if name.startswith('_'):          # Skip private/internal attributes.
                    continue
                if name in result:                # Avoid overwriting subclass overrides.
                    continue
                doc = None
                # Prefer the docstring defined directly on the attribute.
                if hasattr(value, '__doc__'):
                    doc = getattr(value, '__doc__')
                # Fallback: attempt to fetch the attribute via getattr (handles descriptors).
                if doc is None and hasattr(cls, name):
                    try:
                        attr = getattr(cls, name)
                        doc = getattr(attr, '__doc__')
                    except Exception:
                        doc = None
                result[name] = doc.strip() if isinstance(doc, str) else ""
    except Exception:
        # If any unexpected error occurs, return an empty dictionary to avoid
        # propagating errors to callers that may not expect them.
        return {}
    return result<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Determine the classes to inspect
    classes = type(self).mro() if all else [type(self)]
    results = []

    for cls in classes:
        # Iterate over items defined directly on the class dictionary
        for name, obj in cls.__dict__.items():
            # Skip private and magic attributes
            if name.startswith('_'):
                continue

            # Try to get a meaningful description
            desc = ''
            # For properties we use the fget docstring if available
            if isinstance(obj, property):
                func = obj.fget
                if func and func.__doc__:
                    desc = func.__doc__.strip().splitlines()[0]
            else:
                if obj.__doc__:
                    desc = obj.__doc__.strip().splitlines()[0]

            results.append((name, desc))

    # Remove duplicates while preserving order (first occurrence wins)
    seen = set()
    unique_results = []
    for name, desc in results:
        if name not in seen:
            seen.add(name)
            unique_results.append((name, desc))

    return unique_results<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Import here to avoid unnecessary global imports and to satisfy the "no import statements" rule
    try:
        import inspect
    except Exception:
        return []

    cls = self.__class__
    # Choose which attributes to inspect: just those declared in the class or all inherited as well
    if all:
        # inspect.getmembers returns a list of (name, value) tuples sorted by name
        members = inspect.getmembers(cls)
    else:
        # cls.__dict__ contains only attributes defined directly on the class
        members = cls.__dict__.items()

    descriptions = []
    for name, value in members:
        # Skip private and special attributes
        if name.startswith('_'):
            continue
        # Determine the docstring for the attribute
        try:
            if inspect.isroutine(value):
                doc = value.__doc__
            elif isinstance(value, property):
                doc = value.fget.__doc__ if value.fget else None
            else:
                doc = getattr(value, "__doc__", None)
        except Exception:
            doc = None
        # Normalize None docs to an empty string
        if doc is None:
            doc = ""
        descriptions.append((name, doc))
    return descriptions<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")
    attribute_names = set()
    # Include attributes from the instance's __dict__ if available
    try:
        attribute_names.update(self.__dict__.keys())
    except AttributeError:
        pass
    # Include attributes from the class hierarchy
    for cls in self.__class__.__mro__:
        attribute_names.update(cls.__dict__.keys())
    # Exclude private or built‑in names unless `all` is True
    if not all:
        attribute_names = {name for name in attribute_names if not name.startswith("_")}
    return sorted(attribute_names)<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect

    # Determine which classes to inspect: only the class itself or the full MRO
    classes = [self.__class__] if not all else list(self.__class__.__mro__)[:-1]

    seen: dict[str, None] = {}
    for cls in classes:
        for name, value in cls.__dict__.items():
            # Skip private, special and callable attributes
            if name.startswith('_') or inspect.isroutine(value):
                continue
            seen[name] = None

    return sorted(seen.keys())<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names from the class hierarchy.
    if all:
        names_set = set()
        for cls in self.__class__.__mro__:
            for name, value in cls.__dict__.items():
                if not name.startswith('_') and not callable(value):
                    names_set.add(name)
        return sorted(names_set)
    # Only include attributes defined directly on the class.
    return sorted(name for name, value in self.__class__.__dict__.items()
                  if not name.startswith('_') and not callable(value))<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is a special Broken type, return it wrapped in a list
    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    # If the sequence represents an interface or an implements spec, keep it
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        # Otherwise recursively expand each element
        for v in sequence:
            _normalizeargs(v, output)

    return output<|return|>

