def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Guard against non-iterable or string inputs
    try:
        # If sequence is an iterable but not a string/bytes, iterate over its items
        if hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes)):
            # Special case: avoid descending into class objects that have __bases__
            if hasattr(sequence, "__bases__") and isinstance(sequence.__bases__, tuple):
                # Treat classes / interfaces as atomic declarations
                output.append(sequence)
            else:
                for item in sequence:
                    _normalizeargs(item, output)
        else:
            # Non-iterable or atomic declaration
            output.append(sequence)
    except Exception:
        # In case of any unexpected error during iteration, treat it as atomic
        output.append(sequence)

    return output<|return|>

