    # Reset internal state
    self.context = {}

    # Reinitialize bins
    try:
        if getattr(self, "initial_value", None) is not None:
            # Preserve bin count if bins already exist
            bin_count = len(self.bins) if hasattr(self, "bins") else 0
            self.bins = [self.initial_value] * bin_count
        else:
            # Use factory method to construct the bins
            self.bins = self.make_bins()
    except Exception:
        # Fallback: clear bins if anything goes wrong
        if hasattr(self, "bins"):
            self.bins = []

    # Reset the total count if it is tracked
    if hasattr(self, "total_count"):
        self.total_count = 0<|return|>

def reset(self):
