        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context
        self.context = {}

        # Reinitialize bins
        if hasattr(self, 'initial_value'):
            try:
                for i in range(len(self.bins)):
                    self.bins[i] = self.initial_value
            except (AttributeError, TypeError):
                # Fallback: if bins is not indexable or missing, re-create from scratch
                self.bins = self.make_bins()
        else:
            try:
                self.bins = self.make_bins()
            except Exception as e:
                # If make_bins fails, raise a more descriptive error
                raise RuntimeError("Failed to reinitialize bins: {}".format(e))

        # Reset any additional state if present
        if hasattr(self, 'total_count'):
            self.total_count = 0
