def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset internal context
        try:
            self.context = {}
        except Exception as exc:
            raise RuntimeError("Failed to reset histogram context.") from exc

        # Reinitialize bins
        try:
            # If an explicit initial value was provided on construction,
            # use it to reset each bin. Otherwise generate fresh bins.
            if hasattr(self, "initial_value") and self.initial_value is not None:
                if hasattr(self, "bins"):
                    if isinstance(self.bins, list):
                        self.bins = [self.initial_value for _ in self.bins]
                    elif isinstance(self.bins, dict):
                        self.bins = {k: self.initial_value for k in self.bins}
                    else:
                        # Unsupported container type – replace entirely
                        self.bins = self.initial_value
                else:
                    # No existing bins, just set to the value
                    self.bins = self.initial_value
            else:
                # Use the factory method to create a fresh bin set
                factory = getattr(self, "make_bins", None)
                if factory is None or not callable(factory):
                    raise AttributeError("make_bins method is not defined or not callable.")
                self.bins = factory()
        except Exception as exc:
            raise RuntimeError("Failed to reinitialize histogram bins.") from exc<|return|>

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset any context dictionary to empty
    if hasattr(self, "context"):
        try:
            self.context = {}
        except Exception:
            # If the attribute cannot be set, ignore
            pass

    # Reinitialize bins
    bins = None
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # Preserve existing number of bins if possible
        if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
            count = len(self.bins)
            bins = [self.initial_value] * count
        else:
            bins = [self.initial_value]
    else:
        # Fallback to using the make_bins method
        if hasattr(self, "make_bins") and callable(self.make_bins):
            try:
                bins = self.make_bins()
            except Exception:
                # If make_bins fails, keep bins as empty list
                bins = []

    if bins is not None:
        # Assign the new bins
        try:
            self.bins = bins
        except Exception:
            pass

    # Optionally reset other metrics if they exist
    if hasattr(self, "total_count"):
        try:
            self.total_count = 0
        except Exception:
            pass
    if hasattr(self, "min_value"):
        try:
            self.min_value = None
        except Exception:
            pass
    if hasattr(self, "max_value"):
        try:
            self.max_value = None
        except Exception:
            pass

    return None<|return|>

def to_csv(self, separator=",", header=None):
    """
    .. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
    Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Determine an iterator over the graph's points
    try:
        iterator = iter(self)
    except TypeError:
        if hasattr(self, "points"):
            iterator = iter(self.points())
        else:
            raise TypeError("Object is not iterable and has no .points() method for CSV conversion")

    if header is not None:
        yield str(header)

    for point in iterator:
        # Try to unpack a point as (coordinate, value)
        try:
            if isinstance(point, (list, tuple)) and len(point) == 2:
                coord, value = point
            else:
                # Fallback: treat the first two elements as coordinate/value
                coord, value = point[0], point[1]
        except Exception:
            # Skip malformed points
            continue

        parts = []

        # Column(s) for the coordinate(s)
        if isinstance(coord, (list, tuple)):
            parts.extend(str(c) for c in coord)
        else:
            parts.append(str(coord))

        # Column(s) for the value(s)
        if isinstance(value, (list, tuple)):
            parts.extend(str(v) for v in value)
        else:
            parts.append(str(value))

        yield separator.join(parts)<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Attempt to retrieve pre‑constructed mapping of coordinate names to error indices
    for attr in ("_err_indices", "err_indices"):
        mapping = getattr(self, attr, None)
        if isinstance(mapping, dict):
            return list(mapping.get(coord_name, []))

    # Inspect a generic `errors` attribute that may contain error containers
    errors_container = getattr(self, "errors", None)
    if isinstance(errors_container, (list, tuple)):
        for err in errors_container:
            try:
                # Common patterns: an attribute with the coordinate name
                if getattr(err, "coord_name", None) == coord_name:
                    if hasattr(err, "indices"):
                        return list(err.indices)
                    # Fallback to length of the container if it is sequence‑like
                    if hasattr(err, "__len__"):
                        return list(range(len(err)))
                    return [0]
                # Some implementations store the coordinate name in a property called `name`
                if getattr(err, "name", None) == coord_name:
                    if hasattr(err, "indices"):
                        return list(err.indices)
                    if hasattr(err, "__len__"):
                        return list(range(len(err)))
                    return [0]
            except Exception:
                continue

    # If nothing matched, return an empty list
    return []<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np
    try:
        # Prefer a dedicated dictionary of error indices if it exists
        if hasattr(self, "_error_indices") and isinstance(self._error_indices, dict):
            return np.array(self._error_indices.get(coord_name, []))

        # Attempt to fetch from the Data dictionary if it holds coordinate entries
        if hasattr(self, "Data") and isinstance(self.Data, dict):
            entry = self.Data.get(coord_name, None)
            if isinstance(entry, dict) and "error_indices" in entry:
                return np.array(entry["error_indices"])
            # Some implementations might store the attribute directly on the entry object
            if hasattr(entry, "error_indices"):
                return np.array(entry.error_indices)

        # Fallback: the coordinate might not store errors explicitly
        return np.array([])
    except Exception:
        # In case of any unexpected issue, return an empty array instead of raising
        return np.array([])<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, (str,)):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the coordinate exists in the object
    coords = getattr(self, "coords", {})
    if not isinstance(coords, (dict,)):
        raise AttributeError("Object does not have a 'coords' dictionary")

    if coord_name not in coords:
        raise KeyError(f"Coordinate '{coord_name}' not found in self.coords")

    # Attempt to retrieve error indices from various possible locations
    # 1. Direct mapping in an `errors` attribute
    errors = getattr(self, "errors", {})
    if isinstance(errors, dict) and coord_name in errors:
        err_idx = errors[coord_name]
        if isinstance(err_idx, (list, tuple, np.ndarray)):
            return list(err_idx)

    # 2. Attribute on the coordinate object itself
    coord_obj = coords[coord_name]
    for attr in ("error_indices", "err_indices", "err", "error"):
        err_idx = getattr(coord_obj, attr, None)
        if err_idx is not None:
            if isinstance(err_idx, (list, tuple, np.ndarray)):
                return list(err_idx)

    # 3. Common naming conventions (e.g., `{coord_name}_err`)
    for suffix in ("_err", "_error", "_err_indices", "_err_idx"):
        key = f"{coord_name}{suffix}"
        if isinstance(errors, dict) and key in errors:
            err_idx = errors[key]
            if isinstance(err_idx, (list, tuple, np.ndarray)):
                return list(err_idx)

    # 4. Fallback: look for an attribute on the object that references error indices
    for candidate in (coord_name, f"{coord_name}_err", f"{coord_name}_error"):
        try:
            err_idx = getattr(self, candidate)
            if isinstance(err_idx, (list, tuple, np.ndarray)):
                return list(err_idx)
        except AttributeError:
            continue

    # No error indices found; return an empty list
    return []<|return|>

def _get_err_indices(self, coord_name):
