def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Validate the input
        if not isinstance(coord_name, str):
            raise TypeError("coord_name must be a string.")
        # Try to retrieve the error indices mapping, if it exists
        try:
            error_indices_map = getattr(self, "_error_indices")
        except AttributeError:
            # No error index mapping defined
            raise AttributeError("The object has no '_error_indices' attribute.")
        # Retrieve indices for the specified coordinate
