        # key exists in both
        val2 = d2[key]

        # if both values are dictionaries and we can recurse
        if isinstance(val, dict) and isinstance(val2, dict):
            # determine next recursion depth
            if recursion_depth is None or recursion_depth > 0:
                next_depth = None if recursion_depth is None else recursion_depth - 1
                sub_diff = difference(val, val2, next_depth if next_depth is not None else -1)
