def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        import numpy as np
    except Exception:
        raise RuntimeError("numpy is required for histogram operations")

    if not hasattr(self, "edges") or not hasattr(self, "values"):
        raise AttributeError("The histogram object must have 'edges' and 'values' attributes")

    edges = np.asarray(self.edges)
    values = np.asarray(self.values)

    if np.isscalar(coord):
        # 1D scalar coordinate
        idx = np.searchsorted(edges, coord, side="right") - 1
        if 0 <= idx < values.size:
            if np.isscalar(weight):
                values[idx] += weight
            else:
                values[idx] += np.asarray(weight)
        # else: out of bounds – ignore
        return

    coord_arr = np.asarray(coord)
    if coord_arr.ndim != 1:
        raise ValueError("coord must be 1‑dimensional array or scalar")

    idx = np.searchsorted(edges, coord_arr, side="right") - 1
    valid = (idx >= 0) & (idx < values.size)
    if not np.any(valid):
        return  # all coordinates out of bounds

    bins = idx[valid]
    # Broadcast weight if necessary
    if np.isscalar(weight):
        np.add.at(values, bins, weight)
    else:
        w_arr = np.asarray(weight)
        if w_arr.shape != coord_arr.shape:
            try:
                w_arr = np.broadcast_to(w_arr, coord_arr.shape)
            except Exception:
                raise ValueError("weight must be scalar or broadcastable to coord")
        np.add.at(values, bins, w_arr[valid])<|return|>

