    import re
    from django.core.exceptions import ValidationError

    # Default regex patterns – these can be overridden by the caller or
    # application configuration if needed.
    KEY_REGEX = r'^[A-Za-z_][A-Za-z0-9_]*$'
    VALUE_REGEX = r'^[A-Za-z0-9_]+$'

    errors = []

    for k, v in labels.items():
        # Validate key type
        if not isinstance(k, (str, bytes)):
            errors.append({repr(k): 'expected string or bytes-like object'})
        else:
            # Validate key format
            if not re.match(KEY_REGEX, k):
                errors.append(
                    {k: f"Label key '{k}' does not match the regex [{KEY_REGEX}]"})
        # Validate value type
        if isinstance(v, (list, tuple)):
            # If value is a sequence, validate each element
            for idx, item in enumerate(v):
                if not isinstance(item, (str, bytes)):
                    errors.append(
                        {repr(item): 'expected string or bytes-like object'})
                else:
                    if not re.match(VALUE_REGEX, item):
                        errors.append(
                            {item: f"Label value '{item}' does not match the regex [{VALUE_REGEX}]"})
        else:
            if not isinstance(v, (str, bytes)):
                errors.append({repr(v): 'expected string or bytes-like object'})
            else:
                if not re.match(VALUE_REGEX, v):
                    errors.append(
                        {v: f"Label value '{v}' does not match the regex [{VALUE_REGEX}]"})
    if errors:
        raise ValidationError(errors)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re

    errors = []

    if not isinstance(labels, dict):
        errors.append({'Labels': 'Labels must be a dictionary'})
        raise ValidationError(errors)

    # Define simple regex patterns for keys and values
    key_pattern = r'^[A-Za-z_][A-Za-z0-9_]*$'
    value_pattern = r'^[A-Za-z0-9_\- ]+$'  # allow letters, digits, underscore, hyphen, space

    key_regex = re.compile(key_pattern)
    value_regex = re.compile(value_pattern)

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            # Even if key type invalid, skip regex matching for this key
        else:
            if not key_regex.match(key):
                errors.append({
                    key: f"Label key '{key}' does not match the regex {key_pattern}"
                })

        # Validate value
        if isinstance(value, (str, bytes)):
            if not value_regex.match(value):
                errors.append({
                    value: f"Label value '{value}' does not match the regex {value_pattern}"
                })
        elif isinstance(value, list):
            # Validate each element in the list
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    errors.append({str(elem): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(elem):
                        errors.append({
                            str(elem): f"Label value '{elem}' does not match the regex {value_pattern}"
                        })
        else:
            # Unsupported value type
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
