                if isinstance(item, (dict, list)):
                    new_list.append(_recurse(item))
                else:
                    new_list.append(None)
            return new_list
        else:
            return None

    result = _recurse(manifest_dict)

    if first_level:
        # Preserve identifying fields from the manifest
        for key in ("apiVersion", "kind"):
            if key in manifest_dict:
                result[key] = manifest_dict[key]
