                value = response[field]
            else:
                # Search list for matching dict
                value = None
                for item in response:
                    if isinstance(item, dict) and item.get("name") == field:
                        value = item
                        break
        except Exception:
            value = None

        if value is None:
            # No value available in the response; skip
            continue

        # If the value is a dict, we may need to initialize nested fields
        if isinstance(value, dict):
            # Ensure last_applied_manifest has a dict entry for this field
            # We look for a dict in last_applied_manifest with name==field
            existing = None
            for i, item in enumerate(last_applied_manifest):
