                    existing = item
                    break
            if existing is None:
                # Create a new dict placeholder
                existing = {"name": field}
                last_applied_manifest.append(existing)
            # Recursively update the nested dict
            try:
                # assume update_last_applied_manifest_dict_from_resp exists
                update_last_applied_manifest_dict_from_resp(
                    existing, list(value.keys()), value
