        # If we receive a list, convert it to a dict with integer keys so we can
        # safely insert missing items. This is a defensive measure; the caller
        # is expected to provide a dict-like structure.
        try:
            last_applied_manifest = dict(enumerate(last_applied_manifest))
        except Exception:
            # If conversion fails, abort silently – nothing can be done
            return

    if not isinstance(response, dict):
        # If response is not a dict, we cannot copy any values; exit.
        return

    # Helper to process a single field
    def _process_field(field, schema, resp, manifest):
        if isinstance(field, str):
            # Simple scalar field
            if field not in manifest and field in resp:
                manifest[field] = resp[field]
        elif isinstance(field, dict):
            # Nested field specified as {key: sub_schema}
            for key, sub_schema in field.items():
                if key not in manifest:
                    # Create placeholder based on sub_schema type
                    if isinstance(sub_schema, dict):
                        manifest[key] = {}
                    elif isinstance(sub_schema, list):
                        manifest[key] = []
                    else:
                        # Scalar or unknown type; default to resp value if present
                        if key in resp:
                            manifest[key] = resp[key]
                        continue
                # Recurse into the nested structure
                sub_resp = resp.get(key, {})
                _process_schema(sub_schema, sub_resp, manifest[key])
        else:
            # Unsupported field descriptor; ignore
            return

    def _process_schema(schema, resp, manifest):
        if isinstance(schema, dict):
            for key, sub_schema in schema.items():
                _process_field(key, sub_schema, resp, manifest)
        elif isinstance(schema, list):
            # List schema can be a list of field descriptors
            for item in schema:
                _process_field(item, item, resp, manifest)
        else:
            # Schema is a scalar; nothing to do
            return

    try:
        _process_schema(observer_schema, response, last_applied_manifest)
    except Exception as exc:
        # Log the error silently to avoid breaking callers; the function is
        # tolerant of malformed input.
        import logging
        logging.getLogger(__name__).debug(
            "update_last_applied_manifest_list_from_resp failed: %s", exc
        )
