                        init_container = []
                        if isinstance(last_applied_manifest, list):
                            last_applied_manifest.append({"name": name, "value": init_container})
                        else:
                            last_applied_manifest = [{"name": name, "value": init_container}]
                        manifest_item = _find_by_name(last_applied_manifest, name)
                    else:
                        init_container = {}
                        if isinstance(last_applied_manifest, list):
                            last_applied_manifest.append({"name": name, "value": init_container})
                        else:
                            last_applied_manifest = [{"name": name, "value": init_container}]
                        manifest_item = _find_by_name(last_applied_manifest, name)

                # Recurse into nested lists or dicts
                child_response = resp_item.get("value") if isinstance(resp_item, dict) else resp_item
                child_manifest = manifest_item.get("value") if isinstance(manifest_item, dict) else manifest_item
                if isinstance(sub_schema, list):
