                        # Recursive call
                        update_last_applied_manifest_list_from_resp(
                            child_manifest_item.get("value", []),
                            child_schema_item.get("children") or child_schema_item.get("schema") or child_schema_item.get("items") or [],
                            child_resp_item.get("value") if isinstance(child_resp_item, dict) else child_resp_item,
