                        child_manifest = {}
                    if not isinstance(child_response, dict):
                        child_response = {}
                    # Simple assignment if leaf
                    if child_schema is None:
                        # leaf, assign value if exists
                        if resp_item and isinstance(resp_item, dict) and "value" in resp_item:
                            manifest_item["value"] = resp_item["value"]
                    else:
