                if manifest_item is None:
                    # add placeholder
                    new_item = {"name": name, "value": None}
                    last_applied_manifest.append(new_item)
                    manifest_item = new_item

                if "value" not in manifest_item:
                    if resp_item and isinstance(resp_item, dict) and "value" in resp_item:
                        manifest_item["value"] = resp_item["value"]
                    else:
                        # unknown field, set to None
