def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Helper to locate the observer schema container in the app spec
    def _find_schema_container(spec):
        for attr in ("observer_schema", "observer_schema_map", "observers",
                     "observer_schemas", "observer_definitions"):
            if hasattr(spec, attr):
                container = getattr(spec, attr)
                if isinstance(container, dict):
                    return container
        # If not found, create a new dict container
        return {}

    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("The application instance has no 'spec' attribute")

        # Resources listed in the manifest
        manifest = getattr(spec, "manifest", None)
        if manifest is None or not isinstance(manifest, list):
            raise AttributeError("The application spec has no 'manifest' list")

        observer_container = _find_schema_container(spec)

        # Default observer schema placeholder
        default_schema = {"type": "object"}

        for resource in manifest:
            if not isinstance(resource, dict):
                continue

            metadata = resource.get("metadata", {})
            name = metadata.get("name")
            if not name:
                continue

            # Skip if a custom observer schema is already defined for this resource
            if name in observer_container:
                continue

            observer_container[name] = default_schema

        # Attach the populated container back to the spec
        # Prefer the original attribute name if possible
        for attr in ("observer_schema", "observer_schema_map", "observers",
                     "observer_schemas", "observer_definitions"):
            if hasattr(spec, attr):
                setattr(spec, attr, observer_container)
                break
        else:
            # If none of the expected attributes existed, set a default one
            setattr(spec, "observer_schemas", observer_container)

        return observer_container

    except Exception as exc:
        raise ValueError(
            f"Failed to generate default observer schemas for application '{getattr(app, 'name', 'unknown')}': {exc}"
        ) from exc<|return|>

