    try:
        manifests = getattr(app.spec, "manifest", None)
        if not isinstance(manifests, (list, tuple)):
            # If manifest is a dict, treat its values as the resource list
            manifests = list(getattr(app.spec, "manifest", {}).values())
        if not manifests:
