        custom_schemas = getattr(custom_schemas, "schemas", {}) or {}
    except AttributeError:
        # If any part missing just fall back to empty dict
        custom_schemas = {}

    for resource in manifests:
        # Try to extract a useful name/key for the resource
        try:
            res_name = resource.get("metadata", {}).get("name")
            if not res_name:
                # Fallback to kind if name is absent
                res_name = resource.get("kind")
        except AttributeError:
            # If not a dict, skip
            continue

        if not res_name:
            # Cannot determine key – skip
            continue

        # Skip if a custom schema already defined
        if res_name in custom_schemas:
            continue

        # Basic default schema – an empty object
        try:
            default_schema = {"type": "object"}
            default_schemas[res_name] = default_schema
        except Exception:
            # In case of any unforeseen error, skip this resource
            continue

    return default_schemas<|return|>

