def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be str or bytes")
    if params is None:
        return sql, None

    # Determine the type of params
    if isinstance(params, dict):
        param_source = dict(params)
        param_is_mapping = True
    elif isinstance(params, (list, tuple)):
        param_source = list(params)
        param_is_mapping = False
    else:
        raise TypeError("params must be a mapping or a sequence")

    # Determine in-style
    try:
        in_style = getattr(self.SQLParams, "in_style")
    except AttributeError:
        raise AttributeError("SQLParams instance must have an 'in_style' attribute")

    # Helper for bytes support
    def _replace_pattern(pattern, repl, string):
        if isinstance(string, bytes):
            return re.sub(pattern.encode("utf-8"), repl.encode("utf-8"), string)
        return re.sub(pattern, repl, string)

    # Named parameter style (e.g. %(name)s)
    if isinstance(in_style, str) and in_style.startswith("%(") and in_style.endswith(")s"):
        if not param_is_mapping:
            raise TypeError("Expected a mapping for named parameter style")
        # Find all placeholder names
        name_pattern = r"%\(([^)]+)\)s"
        if isinstance(sql, bytes):
            compiled = re.compile(name_pattern.encode("utf-8"))
            names = [m.group(1).decode("utf-8") for m in compiled.finditer(sql)]
        else:
            compiled = re.compile(name_pattern)
            names = compiled.findall(sql)

        out_values = []
        for name in names:
            if name not in param_source:
                raise KeyError(f"Parameter name '{name}' not found in params")
            out_values.append(param_source[name])

        out_sql = _replace_pattern(name_pattern, "?", sql)
        out_params = out_values
        return out_sql, out_params

    # Ordinal parameter style (e.g. ? or %s)
    if isinstance(in_style, str) and in_style in ("?", "%s"):
        if param_is_mapping:
            raise TypeError("Expected a sequence for ordinal parameter style")
        # Count placeholders in the original sql
        if isinstance(sql, bytes):
            placeholder_count = sql.count(b"?") if in_style == "?" else sql.count(b"%s")
        else:
            placeholder_count = sql.count("?") if in_style == "?" else sql.count("%s")

        if placeholder_count != len(param_source):
            raise ValueError(
                f"Number of parameters ({len(param_source)}) does not match "
                f"placeholder count ({placeholder_count})"
            )

        # Replace placeholders with a generic '?', maintaining original style
        if in_style == "?":
            out_sql = _replace_pattern(r"\?", "?", sql)
        else:  # %s
            out_sql = _replace_pattern(r"%s", "%s", sql)  # no change needed
        out_params = param_source
        return out_sql, out_params

    raise NotImplementedError(f"Unsupported SQL in_style: {in_style}")<|return|>

