                    # Keep the previous spec_version; log the mismatch if desired
                    pass
            else:
                # Unexpected type for the 'type' field
                raise ArgumentError(
                    "inventory.type",
                    f"Expected string for 'type'; got {type(type_value).__name__}",
                )

        # Validate required keys based on the (current or extracted) spec_version
        required_keys = {"type", "content"}
        if self.spec_version == 2:
            required_keys.add("items")
        elif self.spec_version == 1:
            required_keys.add("entries")

        missing_keys = required_keys - inventory.keys()
        if missing_keys:
            raise ArgumentError(
                "inventory",
                f"Missing required keys for spec_version {self.spec_version}: {', '.join(sorted(missing_keys))}",
            )

        # Example of further structural validation: ensure certain fields are lists
        if self.spec_version == 2:
            if not isinstance(inventory.get("items", []), list):
                raise ArgumentError(
                    "inventory.items",
                    f"Expected list for 'items'; got {type(inventory.get('items')).__name__}",
                )
        elif self.spec_version == 1:
            if not isinstance(inventory.get("entries", []), list):
                raise ArgumentError(
                    "inventory.entries",
                    f"Expected list for 'entries'; got {type(inventory.get('entries')).__name__}",
                )

        # All checks passed; return the validated inventory
        return inventory<|return|>

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Ensure inventory is a dictionary
        if not isinstance(inventory, dict):
            raise ValueError(f"inventory must be a dict, got {type(inventory).__name__}")

        # Required keys
        required_keys = ['name', 'type']
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"inventory missing required key '{key}'")

        name = inventory['name']
        if not isinstance(name, str) or not name.strip():
            raise ValueError("inventory 'name' must be a non-empty string")

        itype = inventory['type']
        if not isinstance(itype, str):
            raise ValueError("inventory 'type' must be a string")

        # Default spec version
        spec_version = self.spec_version

        # Attempt to extract spec version from the type value
        if extract_spec_version:
            extracted = None
            try:
                # Simple heuristic: look for a colon followed by a version or a trailing number
                if ':' in itype:
                    extracted = itype.split(':', 1)[1]
                else:
                    import re
                    m = re.search(r'(\d+(?:\.\d+)?)$', itype)
                    if m:
                        extracted = m.group(1)
            except Exception:
                extracted = None

            if extracted:
                try:
                    spec_version = float(extracted)
                except ValueError:
                    spec_version = self.spec_version

        # Basic validation based on spec version
        # The validation logic can be expanded as needed
        if spec_version in (2, '2'):
            sv = inventory.get('spec_version')
            if sv is None or str(sv) != '2':
                raise ValueError("For spec_version 2, inventory must contain 'spec_version' equal to '2'")
        elif spec_version in (1, '1'):
            # Example check for version 1 (no-op here)
            pass
        else:
            # Unknown specification; proceed but log a warning if desired
            pass

        # All checks passed
        return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure inputs are iterable
    if manifest_files is None:
        raise ValueError("manifest_files must not be None")
    if digests_used is None:
        raise ValueError("digests_used must not be None")

    # Normalize digests_used to a set for fast lookups
    digests_used_set = set(digests_used)

    missing_required = []
    unused_in_manifest = []

    for entry in manifest_files:
        try:
            # Accept dictionaries with keys 'digest' and 'required'
            if isinstance(entry, dict):
                digest = entry.get('digest')
                required = entry.get('required', False)
            # Accept tuples/lists where first element is digest and second is required flag
            elif isinstance(entry, (list, tuple)):
                digest = entry[0]
                required = entry[1] if len(entry) > 1 else False
            else:
                # Assume entry is the digest itself; consider it required
                digest = entry
                required = True
        except Exception as exc:
            raise ValueError(f"Invalid manifest entry format: {entry}") from exc

        if digest is None:
            continue  # skip malformed entries

        if required and digest not in digests_used_set:
            missing_required.append(digest)

        if digest not in digests_used_set and entry in digests_used_set:
            # skip; handled by later check
            pass

    # Now check for digests that are used but not listed as present in the manifest
    for used_digest in digests_used_set:
        # search the manifest for this digest
        found = False
        for entry in manifest_files:
            try:
                d = entry.get('digest') if isinstance(entry, dict) else (entry[0] if isinstance(entry, (list, tuple)) else entry)
            except Exception:
                continue
            if d == used_digest:
                found = True
                break
        if not found:
            unused_in_manifest.append(used_digest)

    if missing_required:
        raise ValueError(f"The following required digests are missing from used digests: {', '.join(missing_required)}")

    if unused_in_manifest:
        raise ValueError(f"The following digests are used but not found in the manifest: {', '.join(unused_in_manifest)}")

    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalise the digests that are required by the manifest
        if isinstance(manifest_files, dict):
            required = set(manifest_files.values())
        elif isinstance(manifest_files, (list, tuple)):
            required = set()
            for item in manifest_files:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    required.add(item[1])
                elif isinstance(item, str):
                    # If a string is given, assume it is a digest
                    required.add(item)
        else:
            raise TypeError(
                f"manifest_files must be dict, list or tuple, got {type(manifest_files).__name__}"
            )

        # Normalise the digests that were used at runtime
        try:
            used = set(digests_used)
        except Exception:
            raise TypeError(
                f"digests_used must be an iterable of digests, got {type(digests_used).__name__}"
            )

        # Verify that every required digest was used
        missing = required - used
        if missing:
            raise ValueError(
                f"Missing digests that were required by the manifest: {', '.join(sorted(missing))}"
            )

        # Optionally, warn about digests that were used but not required
        unused = used - required
        if unused:
            self.logger.warning(
                f"Digests were used but not present in the manifest: {', '.join(sorted(unused))}"
            )<|return|>

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, "
                        f"not {type(prior).__name__}")

    # Ensure the inventories provide the expected attributes
    required_attrs = ("version", "items")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"Current inventory object is missing expected attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior inventory object is missing expected attribute '{attr}'")

    # Validate version ordering
    try:
        if prior.version >= self.version:
            raise ValueError(f"Prior version ({prior.version}) must be less than current "
                             f"version ({self.version})")
    except Exception as e:
        raise ValueError(f"Could not compare versions: {e}")

    # Ensure the prior's items are a subset of the current inventory's items
    # Items are expected to be a mapping of key -> definition/subobject
    try:
        current_keys = set(self.items.keys())
        prior_keys = set(prior.items.keys())
    except Exception as e:
        raise ValueError(f"Could not retrieve items dictionaries: {e}")

    if not prior_keys.issubset(current_keys):
        missing = prior_keys - current_keys
        raise ValueError(f"The following items from the prior inventory are missing in "
                         f"the current inventory: {missing}")

    # Optional: Check that definitions of common items match
    # This is context dependent; we perform a simple equality check if possible
    mismatched = []
    for key in prior_keys:
        try:
            if prior.items[key] != self.items[key]:
                mismatched.append(key)
        except Exception:
            # If items aren't directly comparable, ignore mismatch
            pass
    if mismatched:
        raise ValueError(f"Definitions of items {mismatched} differ between the "
                         f"prior and current inventories")

    # All checks passed
    return True<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and None checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Check species and parameters are identical
    try:
        if set(self.species) != set(prior.species):
            raise ValueError("Species sets differ between current inventory and prior")
        if set(self.parameters) != set(prior.parameters):
            raise ValueError("Parameter sets differ between current inventory and prior")
    except AttributeError as e:
        raise ValueError("Both inventories must have 'species' and 'parameters' attributes") from e

    # Verify stoichiometry matrix compatibility
    try:
        if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
            raise ValueError("Stoichiometry matrix shapes differ")
    except AttributeError as e:
        raise ValueError("Both inventories must have 'stoichiometry_matrix' attributes") from e

    # Verify propensities matrix compatibility
    try:
        if (self.propensities.rows, self.propensities.cols) != (prior.propensities.rows, prior.propensities.cols):
            raise ValueError("Propensities matrix dimensions differ")
    except AttributeError as e:
        raise ValueError("Both inventories must have 'propensities' attributes") from e

    # Optional: check that prior's constraints are a subset of current constraints
    if hasattr(self, "constraints") and hasattr(prior, "constraints"):
        if not set(prior.constraints).issubset(set(self.constraints)):
            raise ValueError("Prior constraints are not a subset of current constraints")

    # If all checks pass, return True indicating valid prior
    return True<|return|>

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    errors = []

    # Basic type check
    if not isinstance(prior, type(self)):
        errors.append(f"Prior must be an instance of {type(self).__name__}")
        return errors

    # Compare version if present
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if prior.version >= self.version:
                errors.append(
                    f"Prior version {prior.version!r} must be older than "
                    f"current version {self.version!r}"
                )
        except TypeError:
            # Fallback to string comparison when versions are not directly comparable
            if str(prior.version) >= str(self.version):
                errors.append(
                    f"Prior version {prior.version!r} must be older than "
                    f"current version {self.version!r}"
                )

    # Helper to decide if an object is a collection of items
    def _is_collection(obj):
        return isinstance(obj, (list, set, tuple, dict))

    # Gather attribute names that are collections in the current inventory
    current_attrs = [
        name
        for name in dir(self)
        if not name.startswith("_")
        and getattr(self, name, None) is not None
        and _is_collection(getattr(self, name))
    ]

    # For each such attribute, ensure the prior has it and is a subset
    for attr in current_attrs:
        current_val = getattr(self, attr)
        prior_val = getattr(prior, attr, None)

        if prior_val is None:
            errors.append(f"Prior missing expected attribute '{attr}'")
            continue

        try:
            if isinstance(current_val, dict) and isinstance(prior_val, dict):
                # Compare keys for dictionaries as sets
                current_keys = set(current_val.keys())
                prior_keys = set(prior_val.keys())
                missing = prior_keys - current_keys
            else:
                current_set = set(current_val)
                prior_set = set(prior_val)
                missing = prior_set - current_set
        except Exception:
            # If converting to set fails, skip this check
            missing = set()

        if missing:
            errors.append(
                f"Prior attribute '{attr}' contains items not present in current "
                f"inventory: {missing}"
            )

    return errors<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        raise ValueError("Prior inventory cannot be None")

    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected prior to be an {type(self).__name__} instance, got {type(prior).__name__}"
        )

    errors = []

    # Check species are identical
    self_species_set = set(self.species)
    prior_species_set = set(prior.species)
    if self_species_set != prior_species_set:
        missing_in_prior = sorted(self_species_set - prior_species_set)
        missing_in_self = sorted(prior_species_set - self_species_set)
        if missing_in_prior:
            errors.append(f"Species missing in prior: {missing_in_prior}")
        if missing_in_self:
            errors.append(f"Species missing in self: {missing_in_self}")

    # Check parameters are identical
    self_params_set = set(self.parameters)
    prior_params_set = set(prior.parameters)
    if self_params_set != prior_params_set:
        missing_in_prior = sorted(self_params_set - prior_params_set)
        missing_in_self = sorted(prior_params_set - self_params_set)
        if missing_in_prior:
            errors.append(f"Parameters missing in prior: {missing_in_prior}")
        if missing_in_self:
            errors.append(f"Parameters missing in self: {missing_in_self}")

    # Check reactions are identical in name (fallback to repr if no name)
    try:
        self_reaction_names = set(r.name for r in self.reactions)
        prior_reaction_names = set(r.name for r in prior.reactions)
    except AttributeError:
        self_reaction_names = set(repr(r) for r in self.reactions)
        prior_reaction_names = set(repr(r) for r in prior.reactions)

    if self_reaction_names != prior_reaction_names:
        missing_in_prior = sorted(self_reaction_names - prior_reaction_names)
        missing_in_self = sorted(prior_reaction_names - self_reaction_names)
        if missing_in_prior:
            errors.append(f"Reactions missing in prior: {missing_in_prior}")
        if missing_in_self:
            errors.append(f"Reactions missing in self: {missing_in_self}")

    if errors:
        raise ValueError("Prior inventory validation failed: " + "; ".join(errors))
<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")
    # Ensure all keys are strings for consistent sorting
    try:
        sorted_versions = sorted(str(v) for v in inventory.keys())
    except Exception as e:
        raise ValueError(f"Cannot sort inventory keys: {e}") from e
    if str(version) not in sorted_versions:
        raise ValueError(f"Version {version!r} not found in inventory")
    # Find index of requested version
    start_idx = sorted_versions.index(str(version))
    # Aggregate mappings from requested version onwards
    logical_map = {}
    for v in sorted_versions[start_idx:]:
        entries = inventory.get(v, {})
        if not isinstance(entries, dict):
            continue
        for logical_path, content_files in entries.items():
            if logical_path not in logical_map:
                logical_map[logical_path] = set()
            if isinstance(content_files, (list, set, tuple)):
                logical_map[logical_path].update(content_files)
            else:
                logical_map[logical_path].add(content_files)
    return logical_map<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping logical paths to versioned data")

    def _compare_versions(v1, v2):
        """
        Compare two version strings.
        Return True if v1 >= v2, False otherwise.
        If comparison fails, fall back to string lexicographic order.
        """
        try:
            # Try numeric comparison by splitting on non-digits
            def _key(v):
                parts = []
                for part in v.split('.'):
                    if part.isdigit():
                        parts.append(int(part))
                    else:
                        parts.append(part)
                return parts
            return _key(v1) >= _key(v2)
        except Exception:
            return str(v1) >= str(v2)

    result = {}
    for logical_path, data in inventory.items():
        files_set = set()
        try:
            # Expect data to be a dict of version -> list/set/tuple of file paths
            for ver, content in data.items():
                if not isinstance(ver, str):
                    continue  # skip non-string keys
                if version is None or _compare_versions(ver, version):
                    if isinstance(content, (list, set, tuple)):
                        files_set.update(content)
                    else:
                        files_set.add(content)
        except Exception:
            # If data not in expected format, skip this logical path
            continue
        if files_set:
            result[logical_path] = files_set
    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    result = {}
    for logical_path, versions in inventory.items():
        if not isinstance(versions, dict):
            continue
        files = set()
        for ver, content_files in versions.items():
            try:
                if ver == version or ver > version:
                    # content_files could be any iterable of file names
                    files.update(content_files)
            except Exception:
                # Skip problematic entries
                continue
        if files:
            result[logical_path] = files
    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")

    # Attempt to retrieve the state corresponding to `version`
    state = None

    # Case 1: inventory is a mapping of version -> state
    if isinstance(inventory, dict):
        if version in inventory:
            state = inventory[version]
        else:
            # Try string conversion (some inventories use string keys)
            state = inventory.get(str(version))
    # Case 2: inventory provides a method to fetch the relevant state
    elif hasattr(inventory, "get_state"):
        try:
            state = inventory.get_state(version)
        except Exception:
            pass
    else:
        raise TypeError("Unsupported inventory type; expected a dict or an object with `get_state`")

    if state is None:
        raise KeyError(f"Could not find state for version {version!r}")

    # Retrieve the mapping from logical paths to content files
    # The state object may expose the mapping under several common names
    mapping = None
    for attr_name in ("logical_path_map", "paths", "logical_paths", "path_map"):
        if hasattr(state, attr_name):
            mapping = getattr(state, attr_name)
            break

    if mapping is None:
        # Try to infer from the state's attributes
        if hasattr(state, "__dict__"):
            mapping = {
                key: val
                for key, val in state.__dict__.items()
                if isinstance(val, (set, list, tuple))
            }
        else:
            raise AttributeError("State object does not expose a path mapping")

    # Convert any non-set collections to sets for consistency
    final_map = {}
    for logical_path, files in mapping.items():
        if isinstance(files, set):
            final_map[logical_path] = set(files)
        elif isinstance(files, (list, tuple)):
            final_map[logical_path] = set(files)
        else:
            final_map[logical_path] = {files}

    return final_map<|return|>

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """

        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        if "files" not in fixity:
            raise ValueError("Fixity block missing 'files' key")

        files_block = fixity["files"]
        if not isinstance(files_block, list):
            raise ValueError("'files' in fixity block must be a list")

        manifest_set = set(manifest_files)
        referenced = set()

        for entry in files_block:
            if not isinstance(entry, dict):
                raise ValueError("Each file entry in fixity must be a dict")

            if "name" not in entry or "hashes" not in entry:
                raise ValueError("File entry must contain 'name' and 'hashes'")

            name = entry["name"]
            hashes = entry["hashes"]

            if not isinstance(name, str):
                raise ValueError("File 'name' must be a string")
            if not isinstance(hashes, dict):
                raise ValueError("File 'hashes' must be a dictionary")

            if name not in manifest_set:
                raise ValueError(f"Fixity references file '{name}' not present in the manifest")

            referenced.add(name)

            for algo, digest in hashes.items():
                if not isinstance(algo, str) or not isinstance(digest, str):
                    raise ValueError("Hash algorithm and digest must be strings")

        # Ensure no files from the manifest are missing in the fixity block
        missing = manifest_set - referenced
        if missing:
            raise ValueError(f"Fixity block missing entries for files: {', '.join(sorted(missing))}")

        # All checks passed
        return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError(f"manifest_files must be an iterable of file names, got {type(manifest_files).__name__}")

    # Expected keys in a typical fixity block
    required_keys = {"algorithm", "checksum", "files"}
    missing = required_keys - fixity.keys()
    if missing:
        raise ValueError(f"Fixity block missing required keys: {', '.join(sorted(missing))}")

    algorithm = fixity["algorithm"]
    checksum = fixity["checksum"]
    files = fixity["files"]

    # Validate individual fields
    if not isinstance(algorithm, str) or not algorithm:
        raise ValueError("Algorithm must be a non-empty string")
    if not isinstance(checksum, str) or not checksum:
        raise ValueError("Checksum must be a non-empty string")
    if not isinstance(files, list):
        raise ValueError("Files entry must be a list")
    if not files:
        raise ValueError("Files list in the fixity block cannot be empty")

    # Ensure every file referenced is present in the manifest
    manifest_set = set(manifest_files)
    for f in files:
        if not isinstance(f, str) or not f:
            raise ValueError(f"Each file name in the fixity block must be a non-empty string, got {f!r}")
        if f not in manifest_set:
            raise ValueError(f"File '{f}' referenced in fixity block is not present in the manifest")
    # If we reach here, the fixity block is considered valid. Return None.<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type check
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Required keys for a valid fixity block
    required_keys = {"algorithm", "value", "files"}
    missing_keys = required_keys - fixity.keys()
    if missing_keys:
        raise ValueError(f"Fixity block missing required keys: {missing_keys}")

    # Reject any unexpected keys that could indicate a malformed block
    extra_keys = fixity.keys() - required_keys
    if extra_keys:
        raise ValueError(f"Unexpected keys in fixity block: {extra_keys}")

    # Validate algorithm
    allowed_algos = {"md5", "sha1", "sha256", "sha512"}
    algo = str(fixity["algorithm"]).lower()
    if algo not in allowed_algos:
        raise ValueError(f"Unsupported algorithm '{fixity['algorithm']}'. "
                         f"Allowed values are: {', '.join(allowed_algos)}")

    # Validate hash value is a non‑empty string
    if not isinstance(fixity["value"], str) or not fixity["value"].strip():
        raise ValueError("Fixity 'value' must be a non‑empty string")

    # Validate that 'files' is a sequence of file identifiers
    files_seq = fixity["files"]
    if not isinstance(files_seq, (list, tuple, set)):
        raise TypeError("Fixity 'files' must be a list, tuple, or set")

    # Build a set of allowed file names (whatever is contained in manifest_files)
    # If the manifest contains objects, we assume a name attribute; otherwise the item itself is the name.
    try:
        manifest_set = {file.name for file in manifest_files}
    except AttributeError:
        manifest_set = set(map(str, manifest_files))

    # Ensure each referenced file exists in the manifest
    for file_ref in files_seq:
        if file_ref not in manifest_set:
            raise ValueError(f"Fixity references unknown file: {file_ref}")
    # If all checks pass, validation succeeds silently (return None)<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dict
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    # Expect a sub-dict under key 'files' mapping filenames to checksums
    if 'files' not in fixity:
        raise ValueError("Missing 'files' key in fixity block")
    files_block = fixity['files']
    if not isinstance(files_block, dict):
        raise ValueError("'files' entry must be a dictionary")
    # Make sure manifest_files is iterable (list/set of filenames)
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("manifest_files must be a list or set of filenames")
    # Check referenced files are in the manifest
    for fname in files_block:
        if fname not in manifest_set:
            raise ValueError(f"File '{fname}' referenced in fixity but not present in the manifest")
    # Optional: Ensure every manifest file has a fixity entry
    missing_in_fixity = manifest_set - set(files_block)
    if missing_in_fixity:
        raise ValueError(f"Missing fixity entries for files: {sorted(missing_in_fixity)}")
    # If all checks pass, return True or None
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")
    if not isinstance(manifest_files, (list, set, tuple, frozenset)):
        raise ValueError("Manifest files must be a list or set")
    manifest_set = set(manifest_files)

    for fname, entry in fixity.items():
        if fname not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{fname}' not in manifest")
        if not isinstance(entry, dict):
            raise ValueError(f"Entry for file '{fname}' must be a dictionary")
        # required keys
        required_keys = {"algorithm", "checksum"}
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(f"Entry for file '{fname}' missing required keys: {', '.join(sorted(missing))}")
        algorithm = entry["algorithm"]
        checksum = entry["checksum"]
        if not isinstance(algorithm, str) or not algorithm.strip():
            raise ValueError(f"Invalid algorithm for file '{fname}': must be a non-empty string")
        if not isinstance(checksum, str) or not checksum.strip():
            raise ValueError(f"Invalid checksum for file '{fname}': must be a non-empty string")
        # simple hex check for checksum; allow uppercase/lowercase
        if not all(c in "0123456789abcdefABCDEF" for c in checksum):
            raise ValueError(f"Checksum for file '{fname}' is not a valid hexadecimal string")

    # Ensure that all manifest files are referenced in fixity
    missing_in_fixity = manifest_set - set(fixity.keys())
    if missing_in_fixity:
        raise ValueError(f"Manifest files not referenced in fixity: {', '.join(sorted(missing_in_fixity))}")

    return True<|return|>

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        import os
        from os.path import exists, isfile, isdir, abspath, join
    except Exception:
        # Fallback: if imports fail, return empty list
        return []
    if not exists(path):
        raise FileNotFoundError(path)
    if isfile(path):
        return [abspath(path)]
    if isdir(path):
        result = []
        for root, dirs, files in os.walk(path):
            for f in files:
                try:
                    result.append(abspath(join(root, f)))
                except Exception:
                    continue
        return result
    return []<|return|>

