def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xmls : list
        List of XML file paths (strings).
    files : list
        List of file paths in the folder or zipfile.

    Returns
    -------
    dict
        key: basename of the XML files (without extension)
        value: list of files that share the same basename
    """
    def _basename(path):
        """Return the basename of a path without using os module."""
        for sep in ('/', '\\'):
            if sep in path:
                return path.rsplit(sep, 1)[-1]
        return path

    def _splitext(path):
        """Return (root, ext) split of a path without using os module."""
        parts = path.rsplit('.', 1)
        if len(parts) == 2:
            return parts[0], parts[1]
        return path, ''

    result = {}
    if not isinstance(xmls, list) or not isinstance(files, list):
        raise TypeError("Both 'xmls' and 'files' must be lists")

    for xml_path in xmls:
        try:
            base = _splitext(_basename(xml_path))[0]
        except Exception:
            # Skip invalid xml paths
            continue

        matched_files = []
        for f in files:
            try:
                f_base = _splitext(_basename(f))[0]
            except Exception:
                continue
            if f_base == base:
                matched_files.append(f)

        if matched_files:
            result[base] = matched_files

    return result<|return|>

def match_file_by_prefix(prefix, file_path):
    """
    Identify if a `file_path` belongs to a document package by a given `prefix`

    Retorna `True` para documentos pertencentes a um pacote.

    Parameters
    ----------
    prefix : str
        Filename prefix
    file_path : str
        File path
    Returns
    -------
    bool
        True - file belongs to the package
    """
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if prefix == "":
        return False
    try:
        # Extract the basename without importing os
        if "/" in file_path:
            base = file_path.rsplit("/", 1)[-1]
        elif "\\" in file_path:
            base = file_path.rsplit("\\", 1)[-1]
        else:
            base = file_path
        return base.startswith(prefix)
    except Exception:
        return False<|return|>

