def add_rendition(self, lang, file_path):
        """Add a language rendition to the internal mapping.

        Args:
            lang (str): Language code identifier, e.g., 'en', 'ar'.
            file_path (dict): Dictionary that maps language codes and
                'original' to the corresponding file paths.  Example:
