        try:
            if not isinstance(file_path, dict):
                raise ValueError("file_path must be a dictionary")

            original = file_path.get("original")
            if not original:
                raise ValueError("file_path must contain an 'original' key")

            rendition = file_path.get(lang)
            if not rendition:
                raise ValueError(f"file_path missing rendition for language '{lang}'")

            # Ensure the rendition's file exists (optional)
            if not os.path.exists(rendition):
                raise FileNotFoundError(f"Rendition file not found: {rendition}")

            # Store the mapping
            if not hasattr(self, "_renditions"):
                self._renditions = {}
            self._renditions[original] = self._renditions.get(original, {})
            self._renditions[original][lang] = rendition

            return True
        except Exception as e:
            # In a real implementation you might log the exception
            # for debugging purposes, e.g. logger.exception(...)
            return False<|return|>

def add_asset(self, basename, file_path):
    """
    Adds an asset by searching for files with the given basename in the specified directory
    and returns a mapping of filenames to their absolute paths.

    The method looks for files with extensions .tiff, .jpg, .png that start with
    the provided ``basename``.  It builds a dictionary where each key is the
    filename and each value is the full path to that file.

    Raises:
        ValueError: If ``basename`` or ``file_path`` are invalid, if the
            directory does not exist, or if no matching files are found.
        IOError: If an error occurs while accessing the filesystem.
    """
    import os
    if not isinstance(basename, str) or not basename:
        raise ValueError("basename must be a non-empty string")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non-empty string")
    if not os.path.isdir(file_path):
        raise ValueError(f"Directory does not exist: {file_path}")

    # Search for matching files
    try:
        entries = os.listdir(file_path)
    except OSError as exc:
        raise IOError(f"Error accessing directory {file_path}: {exc}") from exc

    suffixes = ('.tiff', '.jpg', '.png', '.jpeg')
    asset_map = {}
    for entry in entries:
        # Only consider files (skip directories)
        full_path = os.path.join(file_path, entry)
        if not os.path.isfile(full_path):
            continue
        name, ext = os.path.splitext(entry)
        if name == basename and ext.lower() in suffixes:
            asset_map[entry] = os.path.abspath(full_path)

    if not asset_map:
        raise ValueError(
            f"No asset files found for basename '{basename}' in '{file_path}'"
        )

    # Optionally store the mapping for later use (if the class has an attribute)
    if hasattr(self, "_assets_registry"):
        self._assets_registry[basename] = asset_map
    else:
        # If no registry, create one
        self._assets_registry = {basename: asset_map}

    return asset_map<|return|>

