def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    groups = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                # Skip directories
                if zinfo.is_dir():
                    continue
                # Process only XML files
                if not zinfo.filename.lower().endswith('.xml'):
                    continue
                basename = os.path.splitext(os.path.basename(zinfo.filename))[0]
                try:
                    content_bytes = zin.read(zinfo)
                except KeyError:
                    continue
                try:
                    content = content_bytes.decode('utf-8')
                except Exception:
                    content = content_bytes.decode('utf-8', errors='replace')
                groups.setdefault(basename, []).append((zinfo.filename, content))
    except Exception:
        # Return an empty dict if anything goes wrong
        return {}
    return groups<|return|>

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the XML basename (without
        extension) and the value is another dictionary mapping the
        original filename inside the zip to its content (bytes).
    """
    import zipfile
    from pathlib import Path

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    try:
        zf = zipfile.ZipFile(zip_path, 'r')
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"File not found: {zip_path}") from exc
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc

    try:
        packages = {}
        for entry in zf.infolist():
            # Skip directories
            if entry.is_dir():
                continue

            file_name = entry.filename
            path_obj = Path(file_name)
            if path_obj.suffix.lower() == '.xml':
                # Use stem (basename without extension) as key
                key = path_obj.stem
                # Initialize nested dict for this package
                if key not in packages:
                    packages[key] = {}
                # Read XML content as text (utf-8)
                try:
                    content = zf.read(entry).decode('utf-8')
                except Exception:
                    # Fallback to bytes if decoding fails
                    content = zf.read(entry)
                packages[key][file_name] = content
            else:
                # For non-xml files, try to associate them with an xml basename
                # if the file resides in a folder that matches an existing xml key
                # or a basename part of the filename
                possible_keys = set()
                # Add directory names in the path
                for part in path_obj.parts:
                    if part.lower().endswith('.xml'):
                        possible_keys.add(part.lower().replace('.xml', ''))
                # Add stem part
                possible_keys.add(path_obj.stem)

                matched_key = None
                for k in possible_keys:
                    if k in packages:
                        matched_key = k
                        break

                if matched_key:
                    try:
                        content = zf.read(entry).decode('utf-8')
                    except Exception:
                        content = zf.read(entry)
                    packages[matched_key][file_name] = content
                else:
                    # No matching xml-based key found: create a generic key
                    generic_key = path_obj.stem
                    if generic_key not in packages:
                        packages[generic_key] = {}
                    try:
                        content = zf.read(entry).decode('utf-8')
                    except Exception:
                        content = zf.read(entry)
                    packages[generic_key][file_name] = content

        return packages
    finally:
        zf.close()
<|return|>

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping of basename to a dict containing the XML content (if any)
        and a list of other file contents.
    """
    import os
    import zipfile

    result = {}

    if not zip_path:
        return result

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            for info in zf.infolist():
                # skip directories
                if info.is_dir():
                    continue

                name = info.filename
                base = os.path.splitext(os.path.basename(name))[0]
                # Initialize entry if needed
                if base not in result:
                    result[base] = {"xml": None, "files": []}

                try:
                    data = zf.read(name)
                except Exception:
                    # If we cannot read this file, skip it
                    continue

                if name.lower().endswith(".xml"):
                    result[base]["xml"] = data
                else:
                    result[base]["files"].append({"name": name, "content": data})
    except zipfile.BadZipFile as exc:
        raise ValueError(f"Invalid ZIP file: {zip_path}") from exc

    return result<|return|>

