            suppl = 1
    else:
        # Handle cases like "s2" or "spe2" where number follows directly
        direct_match = re.search(r'(?:suppl|sup|spe|s|supp|supl)[0-9]+', text, flags=re.IGNORECASE)
        if direct_match:
            num_in_word = re.search(r'([0-9]+)', direct_match.group(0))
            if num_in_word:
