def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0

    seen = set()

    def _format(obj, level):
        # prefix for current level
        prefix = ' ' * (indent + level * 4)

        # Avoid endless recursion
        obj_id = id(obj)
        if obj_id in seen:
            return f"{prefix}<recursion detected>"
        # Base types
        if isinstance(obj, (str, int, float, bool, type(None))):
            return f"{prefix}{repr(obj)}"
        # Containers
        if isinstance(obj, (list, tuple, set, frozenset)):
            seen.add(obj_id)
            open_sym, close_sym = None, None
            if isinstance(obj, list):
                open_sym, close_sym = '[', ']'
            elif isinstance(obj, tuple):
                open_sym, close_sym = '(', ')'
            elif isinstance(obj, (set, frozenset)):
                open_sym, close_sym = '{', '}'
            try:
                items = [_format(item, level + 1) for item in obj]
            except Exception as exc:
                seen.remove(obj_id)
                return f"{prefix}<error formatting {type(obj).__name__}: {exc}>"
            seen.remove(obj_id)
            if debug:
                type_info = f" (type: {type(obj).__name__})"
            else:
                type_info = ''
            if len(items) == 0:
                return f"{prefix}{open_sym}{close_sym}{type_info}"
            # multiline formatting
            inner = ",\n".join(items)
            return f"{prefix}{open_sym}\n{inner}\n{prefix}{close_sym}{type_info}"
        if isinstance(obj, dict):
            seen.add(obj_id)
            items = []
            try:
                for k, v in obj.items():
                    key_str = _format(k, level + 1)
                    val_str = _format(v, level + 1)
                    items.append(f"{key_str}: {val_str}")
            except Exception as exc:
                seen.remove(obj_id)
                return f"{prefix}<error formatting dict: {exc}>"
            seen.remove(obj_id)
            if debug:
                type_info = f" (type: {type(obj).__name__})"
            else:
                type_info = ''
            if not items:
                return f"{prefix}{{}}{type_info}"
            inner = ",\n".join(items)
            return f"{prefix}{{\n{inner}\n{prefix}}}{type_info}"
        # Fallback: use repr safely
        try:
            return f"{prefix}{repr(obj)}"
        except Exception:
            return f"{prefix}<unreprable object>"

    try:
        result = _format(self, 0)
    except Exception:
        result = "<error generating pretty representation>"
    return result<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # keep track of visited objects to avoid infinite recursion
    visited = set()

    def _format(obj, level):
        # indentation prefix
        prefix = ' ' * (level * indent) if indent > 0 else ''
        # handle simple built-ins
        if isinstance(obj, (str, int, float, bool, type(None))):
            return prefix + repr(obj)
        # detect recursion
        obj_id = id(obj)
        if obj_id in visited:
            return prefix + '<recursion>'
        visited.add(obj_id)
        # handle collections
        if isinstance(obj, (list, tuple, set, frozenset)):
            if isinstance(obj, list):
                items = [_format(item, level + 1).strip() for item in obj]
                return prefix + '[' + ', '.join(items) + ']'
            if isinstance(obj, tuple):
                items = [_format(item, level + 1).strip() for item in obj]
                return prefix + '(' + ', '.join(items) + (',' if len(obj) == 1 else '') + ')'
            if isinstance(obj, (set, frozenset)):
                items = [_format(item, level + 1).strip() for item in obj]
                open_br = 'set([' if isinstance(obj, set) else 'frozenset(['
                return prefix + open_br + ', '.join(items) + '])'
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                key = _format(k, level + 1).strip()
                val = _format(v, level + 1).strip()
                items.append(f'{key}: {val}')
            return prefix + '{' + ', '.join(items) + '}'
        # handle objects with __dict__
        if hasattr(obj, '__dict__'):
            attrs = {}
            for key, value in vars(obj).items():
                attrs[key] = _format(value, level + 1).strip()
            attr_str = ', '.join(f'{k}={v}' for k, v in attrs.items())
            return prefix + f'{obj.__class__.__name__}({attr_str})'
        # fallback
        return prefix + repr(obj)

    representation = _format(self, 0)

    if debug:
        header = f'{self.__class__.__module__}.{self.__class__.__name__} object at {hex(id(self))}'
        return header + '\n' + representation
    return representation<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to use for each indentation level (default 0).
    debug : bool, optional
        If True, include type information in the output (default False).

    Returns
    -------
    str
        Human‑readable string representation of ``self``.
    """
    # Validation of parameters
    try:
        indent = int(indent)
    except Exception:
        raise ValueError("indent must be an integer")
    if indent < 0:
        raise ValueError("indent must be non‑negative")

    def _pretty(obj, level):
        """Recursively format ``obj`` starting at indentation ``level``."""
        try:
            prefix = " " * (level * indent)
            if obj is None:
                return f"{prefix}None"
            if isinstance(obj, (int, float, complex, bool, str)):
                return f"{prefix}{repr(obj)}"
            if isinstance(obj, (list, tuple, set, frozenset)):
                opening = "[" if isinstance(obj, list) else ("(" if isinstance(obj, tuple) else "{")
                closing = "]" if isinstance(obj, list) else (")" if isinstance(obj, tuple) else "}")
                if not obj:
                    return f"{prefix}{opening}{closing}"
                parts = []
                for item in obj:
                    parts.append(_pretty(item, level + 1))
                joined = ",\n".join(parts)
                return f"{prefix}{opening}\n{joined}\n{prefix}{closing}"
            if isinstance(obj, dict):
                if not obj:
                    return f"{prefix}{{}}"
                parts = []
                for k, v in obj.items():
                    parts.append(f"{' ' * ((level + 1) * indent)}{repr(k)}: {_pretty(v, level + 1).lstrip()}")
                joined = ",\n".join(parts)
                return f"{prefix}{{\n{joined}\n{prefix}}}"
            # For user objects, dump __dict__ if available
            if hasattr(obj, "__dict__"):
                return _pretty(vars(obj), level)
            # Fallback: use repr
            return f"{prefix}{repr(obj)}"
        except Exception as exc:
            # In case of circular refs or other issues, fall back to repr
            return f"{prefix}{{<repr_error: {exc}>}}"

    # Start pretty printing from level 0
    result = _pretty(self, 0)

    # Add debug information if requested
    if debug:
        try:
            type_info = type(self).__name__
            result = f"Type: {type_info}\n{result}"
        except Exception:
            pass  # ignore any errors while fetching type

    return result
<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper function to check if an expression is a NOT of some subexpr
    def is_not(expr):
        return isinstance(expr, tuple) and expr[0] == 'NOT'

    # Helper function to check if two expressions are structurally equal
    def expr_equal(a, b):
        return a == b

    # Simplify a single expression recursively
    def simplify(expr):
        if not isinstance(expr, tuple):
            # Base case: leaf node (variable or literal)
            return expr

        op = expr[0]
        if op in ('AND', 'OR'):
            left = simplify(expr[1])
            right = simplify(expr[2])

            # Apply absorption rules
            if op == 'AND':
                # A & (A | B) -> A
                if isinstance(right, tuple) and right[0] == 'OR':
                    if expr_equal(left, right[1]):
                        # A & (A | B)
                        return left
                    if expr_equal(left, right[2]):
                        # (A | B) & A (commutative)
                        return left
                # Negative absorption: A & (~A | B) -> A & B
                if isinstance(right, tuple) and right[0] == 'OR':
                    if is_not(right[1]) and expr_equal(left, right[1][1]):
                        return ('AND', left, right[2])
                    if is_not(right[2]) and expr_equal(left, right[2][1]):
                        return ('AND', left, right[1])

            elif op == 'OR':
                # A | (A & B) -> A
                if isinstance(right, tuple) and right[0] == 'AND':
                    if expr_equal(left, right[1]):
                        return left
                    if expr_equal(left, right[2]):
                        return left
                # Negative absorption: A | (~A & B) -> A | B
                if isinstance(right, tuple) and right[0] == 'AND':
                    if is_not(right[1]) and expr_equal(left, right[1][1]):
                        return ('OR', left, right[2])
                    if is_not(right[2]) and expr_equal(left, right[2][1]):
                        return ('OR', left, right[1])

            # No simplification matched; return simplified subexpr
            return (op, left, right)

        elif op == 'NOT':
            # Simplify the operand
            operand = simplify(expr[1])
            return ('NOT', operand)

        # Unknown operator; return as is
        return expr

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of expressions")

    simplified = []
    for expr in args:
        try:
            simplified_expr = simplify(expr)
            simplified.append(simplified_expr)
        except Exception:
            # If simplification fails for an expression, keep it unchanged
            simplified.append(expr)

    return simplified<|return|>

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("Hook must not be None")
    def decorator(fn):
        if not callable(fn):
            raise TypeError("Registered handler must be callable")
        try:
            self.register_hook(hook, fn)
        except AttributeError:
            raise AttributeError(f"{self.__class__.__name__} has no register_hook method")
        return fn
    return decorator<|return|>

