    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("hook must not be None")
    if not isinstance(hook, str):
        raise TypeError(f"hook must be a string or HookType, got {type(hook).__name__}")

    def decorator(fn):
        if not callable(fn):
            raise TypeError(f"decorated object must be callable, got {type(fn).__name__}")

        # Try to use a registered method if present
        try:
            self.register_hook(hook, fn)
        except AttributeError:
            # Fall back to a dictionary-based registry
            registry = getattr(self, "_registry", None)
            if registry is None:
                raise AttributeError(
                    "Object does not support hook registration: "
                    "no 'register_hook' method and no '_registry' attribute."
                ) from None
            registry.setdefault(hook, []).append(fn)

        return fn

    return decorator<|return|>

