def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    import re

    # Attempt to read a VERSION variable from a local version.py file
    version_file = os.path.join(os.getcwd(), "version.py")
    if not os.path.exists(version_file):
        return "unknown"

    try:
        with open(version_file, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception:
        return "unknown"

    # Look for a line like: VERSION = "1.2.3"
    match = re.search(r"^\s*VERSION\s*=\s*[\"']([^\"']+)[\"']", content, flags=re.MULTILINE)
    if match:
        return match.group(1).strip()

    # Fallback: try to get distribution info via importlib.metadata
    try:
        import importlib.metadata as metadata
        # Use the name of the current package if it exists
        pkg_name = os.path.basename(os.path.dirname(version_file))
        if pkg_name:
            return metadata.version(pkg_name)
    except Exception:
        pass

    return "unknown"<|return|>

