    # Convert each component to a string (or handle None)
    def as_string(p):
        if p is None:
            return None
        return str(p)

    formatted = []

    if style == "full":
        # Join all non-None components with dots
        formatted = [as_string(p) for p in pieces if as_string(p) is not None]
        return ".".join(formatted)

    elif style == "short":
        # Return the prefix of numeric components until a non-numeric part
        for p in pieces:
            s = as_string(p)
            if s is None:
                break
            if s.isdigit():
                formatted.append(s)
            else:
                break
        return ".".join(formatted)

    elif style == "numeric":
        # Convert every component to an int; use 0 for missing/invalid parts
        for p in pieces:
            try:
                formatted.append(str(int(as_string(p))))
            except Exception:
                formatted.append("0")
        return ".".join(formatted)

    else:
        # Unknown style: provide informative error
        raise ValueError(f"Unsupported style '{style}'. "
                         f"Expected 'full', 'short', or 'numeric'.")<|return|>

def render(pieces, style):
    """
    Render the given version pieces into the requested style.
    Supported styles:
        - 'semantic' or 'dot' : join pieces with '.' (e.g., [1, 2, 3] -> '1.2.3')
        - 'numeric' or 'none' : concatenate pieces without separators (e.g., [1, 2, 3] -> '123')
        - 'comma' : join with ', ' (e.g., [1, 2, 3] -> '1, 2, 3')
        - 'pad<N>' : pad each piece to width N (leading zeros) and join with '.' (e.g., 'pad02', [1, 3] -> '01.03')
        - 'human' : produce human‑readable string of the form 'Piece 1: 1; Piece 2: 2; ...'
    """
    # Input validation
    try:
        p_list = list(pieces)
    except TypeError:
        raise ValueError("`pieces` must be an iterable of numbers or strings")

    # Using default style if None or empty
    if not style:
        style = 'semantic'

    style = style.lower()

    # Semantic or dot style
    if style in ('semantic', 'dot'):
        try:
            formatted = '.'.join(str(p) for p in p_list)
        except Exception as exc:
            raise ValueError(f"Failed to format pieces as semantic: {exc}") from exc
        return formatted

    # Numeric style: no separator
    if style in ('numeric', 'none', ''):
        try:
            formatted = ''.join(str(p) for p in p_list)
        except Exception as exc:
            raise ValueError(f"Failed to format pieces as numeric: {exc}") from exc
        return formatted

    # Comma style
    if style == 'comma':
        try:
            formatted = ', '.join(str(p) for p in p_list)
        except Exception as exc:
            raise ValueError(f"Failed to format pieces as comma-separated: {exc}") from exc
        return formatted

    # Pad style e.g., pad02, pad3
    if style.startswith('pad'):
        width_part = style[3:]  # take part after 'pad'
        try:
            width = int(width_part)
            if width <= 0:
                raise ValueError
        except ValueError:
            raise ValueError(f"Invalid pad width in style '{style}'. Expected 'pad<N>' where N is a positive integer.")
        try:
            formatted = '.'.join(f"{int(p):0{width}d}" if isinstance(p, (int, float)) else f"{p:0{width}}" for p in p_list)
        except Exception as exc:
            raise ValueError(f"Failed to format pieces with pad width {width}: {exc}") from exc
        return formatted

    # Human readable
    if style == 'human':
        parts = [f"Piece {i+1}: {p}" for i, p in enumerate(p_list)]
        return '; '.join(parts)

    # If we reach here, style is unknown
    raise ValueError(f"Unsupported style '{style}'. Supported styles: semantic, numeric, comma, pad<N>, human.")<|return|>

