def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).
    """
    import subprocess, os, shlex
    if commands is None:
        raise ValueError("commands cannot be None")
    # Build the base command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    elif isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    # Append arguments
    if args is None:
        args = []
    if isinstance(args, (list, tuple)):
        cmd.extend(args)
    elif isinstance(args, str):
        cmd.extend(shlex.split(args))
    else:
        raise TypeError("args must be a string or a list/tuple of strings")
    # Optional verbosity
    if verbose:
        print("Executing:", ' '.join(shlex.quote(part) for part in cmd))
    # Environment handling
    env_combined = os.environ.copy() if env is not None else None
    if env is not None:
        env_combined.update(env)
    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_combined,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else None,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit status {e.returncode}") from e
    except OSError as e:
        raise RuntimeError(f"Command execution failed: {e}") from e<|return|>

