                msg_lines.append(f"Output:\n{exc.output.decode('utf-8')}")
            except Exception:
                msg_lines.append(f"Output (raw): {exc.output}")
        raise RuntimeError("\n".join(msg_lines)) from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute command '{command}': {exc}") from exc<|return|>

