    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError("commands must be a string or list/tuple of strings")

    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        cmd += list(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        if cwd:
            print(f"  Working directory: {cwd}")

    # Setup environment
    env_dict = None
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict of environment variables")
        env_dict = os.environ.copy()
        env_dict.update(env)

    # Prepare stderr handling
    stderr_target = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL

    try:
        process = subprocess.Popen(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            env=env_dict
        )
        stdout, stderr = process.communicate()
    except OSError as exc:
        raise RuntimeError(f"Execution failed for '{' '.join(cmd)}': {exc}") from exc

    if process.returncode != 0:
        err_msg = stderr.decode('utf-8', errors='replace') if stderr else ''
        raise RuntimeError(
            f"Command '{' '.join(cmd)}' exited with {process.returncode}"
            + (f": {err_msg}" if err_msg else "")
        )

    output_text = stdout.decode('utf-8', errors='replace')
    if verbose:
        print(output_text)

    return output_text

