    # Helper to walk the hierarchy recursively
    def _walk(obj, counts):
        """
        Recursively walk through the hierarchy counting and validating objects.

        :param obj: current object node
        :param counts: dict with 'total' and 'good' counters
        """
        counts['total'] += 1
        is_valid = True

        # Validate object structure if requested
        if validate_objects:
            try:
                # Attempt to call a generic validation method if present
                if hasattr(obj, 'validate') and callable(getattr(obj, 'validate')):
                    is_valid = bool(obj.validate())
                elif hasattr(obj, 'is_valid') and callable(getattr(obj, 'is_valid')):
                    is_valid = bool(obj.is_valid())
                else:
                    # Default: assume the object is structurally valid
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    name = getattr(obj, 'name', str(obj))
                    print(f'Validation error for object "{name}": {exc}')

        # Check digest if requested
        if is_valid and check_digests:
            try:
                if hasattr(obj, 'checksum') and hasattr(obj, 'compute_checksum'):
                    expected = obj.checksum
                    actual = obj.compute_checksum()
                    if expected != actual:
                        is_valid = False
                        if show_warnings:
                            name = getattr(obj, 'name', str(obj))
                            print(f'Digest mismatch for object "{name}": expected {expected}, got {actual}')
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    name = getattr(obj, 'name', str(obj))
                    print(f'Digest computation error for object "{name}": {exc}')

        if is_valid:
            counts['good'] += 1

        # Recurse into children if any
        children = getattr(obj, 'children', [])
        if isinstance(children, list):
            for child in children:
                _walk(child, counts)

    # Initialize counters
    counters = {'total': 0, 'good': 0}

    # Ensure the root of the hierarchy exists
    if not hasattr(self, 'root'):
        raise AttributeError('The instance has no ``root`` attribute representing the hierarchy.')

    try:
        _walk(self.root, counters)
    except Exception as exc:
        if show_warnings:
            print(f'Hierarchy validation aborted due to error: {exc}')
