                        ident = str(obj)
                    print(f"Error checking digest for object {ident}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json
    from pathlib import Path

    # Resolve root path; the instance must provide a `root_path` attribute.
    try:
        root = Path(self.root_path).expanduser()
    except AttributeError as exc:
        raise AttributeError("Instance must have a 'root_path' attribute.") from exc

    # If the root directory already exists, we consider this an error to
    # prevent accidental data loss.
    if root.exists():
        raise FileExistsError(f"OCFL root already exists: {root}")

    try:
        # Create the root and required subdirectories.
        root.mkdir(parents=True, exist_ok=False)
        ocfl_dir = root / ".ocfl"
        ocfl_dir.mkdir()
        (ocfl_dir / "objects").mkdir()
        (ocfl_dir / "metadata").mkdir()

        # Write a minimal configuration file.  The actual configuration
        # might be more elaborate – this is a sensible default.
        config = {"ocflVersion": "1.0", "objectDirectory": "objects"}
        (ocfl_dir / "config.json").write_text(json.dumps(config, indent=2))

    except Exception as err:
        # If anything goes wrong while creating the structure, remove
        # any partially-created files/directories to avoid leaving a corrupt
        # root.
        try:
            if root.exists():
                for p in sorted(root.rglob("*"), key=lambda p: -len(p.parts)):
                    try:
                        if p.is_file():
                            p.unlink()
                        else:
                            p.rmdir()
                    except Exception:
                        pass
                try:
                    root.rmdir()
                except Exception:
                    pass
        except Exception:
            pass
        raise RuntimeError(f"Failed to initialize OCFL root at {root}: {err}") from err

    # Store the resolved root on the instance for later use.
    self.root = root
    return root<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Determine the path attribute that holds the root location
    root_attr = None
    for attr in ("root_path", "storage_root", "path"):
        if hasattr(self, attr):
            root_attr = attr
            break
    if root_attr is None:
        raise ValueError("No root path attribute defined on the instance.")

    root_path = getattr(self, root_attr)

    if not isinstance(root_path, (str, pathlib.Path)):
        raise TypeError(f"The {root_attr!r} attribute must be a string or pathlib.Path, "
                        f"got {type(root_path)!r}.")

    # Ensure the path is absolute for clarity
    try:
        root_path = os.path.abspath(root_path)
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Could not resolve absolute path for '{root_path}': {exc}") from exc

    # Check if the root already exists; an OCFL root must be created fresh
    if os.path.exists(root_path):
        raise ValueError(f"OCFL root directory '{root_path}' already exists; cannot reinitialize.")

    # Create the root directory and standard OCFL subdirectories
    required_dirs = (
        "objects",
        "versions",
        "metadata",
        "manifests",
        "temp",
    )
    try:
        os.makedirs(root_path, exist_ok=False)
        for sub in required_dirs:
            sub_path = os.path.join(root_path, sub)
            os.makedirs(sub_path, exist_ok=False)
        # Create a minimal ROOT file to mark the folder as an OCFL root.
        # According to OCFL spec, the ROOT file contains the format version.
        root_file = os.path.join(root_path, "ROOT")
        with open(root_file, "w", encoding="utf-8") as f:
            f.write("ocfl:0\n")  # placeholder for ontology version
    except OSError as exc:
        # Cleanup partially created directories if any
        try:
            # Try to remove any subdirectories that were created
            for sub in required_dirs:
                sub_path = os.path.join(root_path, sub)
                if os.path.isdir(sub_path):
                    try:
                        os.rmdir(sub_path)
                    except Exception:
                        pass
            if os.path.isdir(root_path):
                try:
                    os.rmdir(root_path)
                except Exception:
                    pass
        except Exception:  # pragma: no cover
            pass
        raise RuntimeError(f"Failed to initialize OCFL root at '{root_path}': {exc}") from exc

    # Store the root path back on the instance for later use
    setattr(self, root_attr, root_path)  # idempotent
    return True  # indicate success, caller may ignore result
<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""

    parts = version.split(".")
    if not parts:
        return version

    try:
        last = parts[-1]
        # Determine whether the last part is numeric and its width (for zero padding)
        if last.isdigit():
            width = len(last)
            new_last_int = int(last) + 1
            new_last = str(new_last_int).zfill(width) if width > 0 else str(new_last_int)
        else:
            # If the last part is not numeric, simply append a '1' suffix
            new_last = last + "1"
        parts[-1] = new_last
        return ".".join(parts)
    except Exception:
        # In case of any unexpected error, return the original version unchanged
        return version<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return None
    v = version.strip()
    if not v.isdigit():
        raise ValueError("Version must be a numeric string")
    try:
        num = int(v)
    except ValueError:
        raise ValueError("Invalid numeric version")
    new_num = num + 1
    orig_len = len(v)
    # Preserve leading zeros only if the increment does not change length
    if v.startswith("0") and new_num < 10 ** orig_len:
        return str(new_num).zfill(orig_len)
    return str(new_num)<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    stripped = version.strip()
    if not stripped.isdigit():
        # If not purely numeric, return the original string unchanged
        return version
    try:
        num = int(stripped)
        next_num = num + 1
    except Exception:
        # In case of unforeseen conversion issues, return original
        return version
    next_str = str(next_num)
    if len(next_str) < len(stripped):
        next_str = next_str.rjust(len(stripped), '0')
    return next_str<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import json, os

    base_dir = getattr(self, 'base_dir', os.getcwd())

    # Attempt to load the root inventory if it exists; otherwise start with an empty dict
    root_inv_path = os.path.join(base_dir, 'root_inventory.json')
    if os.path.isfile(root_inv_path):
        try:
            with open(root_inv_path, 'r', encoding='utf-8') as fh:
                root_inventory = json.load(fh)
                if not isinstance(root_inventory, dict):
                    raise ValueError('root_inventory.json must contain a JSON object')
        except (OSError, json.JSONDecodeError) as exc:
            raise ValueError(f'Could not load root inventory from {root_inv_path!r}: {exc}') from exc
    else:
        root_inventory = {}

    # Storage for any digest differences encountered
    self.different_digests = {}

    seen_files = set()
    for vdir in version_dirs:
        inv_path = os.path.join(base_dir, vdir, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory.json in version directory '{vdir}'")

        try:
            with open(inv_path, 'r', encoding='utf-8') as fh:
                inventory = json.load(fh)
                if not isinstance(inventory, dict):
                    raise ValueError(f"Inventory in '{vdir}' must be a JSON object")
        except (OSError, json.JSONDecodeError) as exc:
            raise ValueError(f"Could not load inventory from {inv_path!r}: {exc}") from exc

        current_keys = set(inventory.keys())

        # Verify that this inventory contains all files seen up to now
        missing_in_current = seen_files - current_keys
        if missing_in_current:
            raise ValueError(f"In version {vdir}, inventory is missing entries for {sorted(missing_in_current)}")

        # Record any digest differences relative to the root inventory
        for file_path, digest in inventory.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is not None and root_digest != digest:
                self.different_digests.setdefault(file_path, []).append((vdir, digest))

        # Update the set of seen files for the next iteration
        seen_files.update(current_keys)

    return True<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        # Nothing to validate
        return

    # Ensure we have a root inventory to compare against
    root_inventory = getattr(self, "root_inventory", None)
    if root_inventory is None:
        raise ValueError("self.root_inventory must be set before validating version inventories")

    differences = {}  # Holds discrepancies per version directory

    import os
    import json

    for idx, dir_name in enumerate(version_dirs, start=1):
        if not isinstance(dir_name, str):
            raise TypeError(f"Directory name at position {idx-1} is not a string: {dir_name!r}")

        inv_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing for version directory '{dir_name}': expected at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv_data = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for '{dir_name}': {exc}")

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory for '{dir_name}' must be a JSON object mapping content to digests")

        dir_diffs = {}
        for content, digest in inv_data.items():
            # Ensure digest is a string
            if not isinstance(digest, str):
                raise ValueError(f"Digest for content {content!r} in '{dir_name}' is not a string")

            root_digest = root_inventory.get(content)
            if root_digest is None:
                raise ValueError(f"Content {content!r} in inventory '{dir_name}' is not present in the root inventory")

            if digest != root_digest:
                dir_diffs[content] = (digest, root_digest)

        if dir_diffs:
            differences[dir_name] = dir_diffs

    # Store differences for later verification steps
    self.version_inventory_differences = differences
    return self <|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Load the root (latest) inventory if it exists
    root_inventory = {}
    root_path = os.path.join(self.root_dir, "inventory.json")
    if os.path.exists(root_path):
        try:
            with open(root_path, "r", encoding="utf-8") as fh:
                root_inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to read root inventory at {root_path!r}: {exc}") from exc

    prev_inventory = {}
    differing_digests = {}

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(self.root_dir, vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory in version directory {vdir!r} (expected at {inv_path!r})")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to read inventory at {inv_path!r}: {exc}") from exc

        # Ensure that this inventory contains all keys seen in previous versions
        for key in prev_inventory:
            if key not in inv:
                raise ValueError(
                    f"Inventory in {vdir!r} is missing key {key!r} that existed in an earlier version"
                )

        # Compare digests to the root inventory to record differences
        for key, digest in inv.items():
            root_digest = root_inventory.get(key)
            if root_digest is None:
                # New entry that has no counterpart in the root; ignore
                continue
            if digest != root_digest:
                differing_digests.setdefault(key, []).append(
                    (vdir, digest, root_digest)
                )

        prev_inventory = inv

    # Store differing digests for later validation steps
    self.differing_digests = differing_digests

    return self
<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Verify version ordering and gather inventories
    root_inventory = None
    # store differences: list of tuples (ver_path, differing_entries)
    self.inventory_differences = []

    for idx, ver_dir in enumerate(version_dirs, start=1):
        # Check that the version directory name is numeric and matches expected sequence
        try:
            ver_num = int(ver_dir)
        except ValueError:
            raise ValueError(f"version directory name '{ver_dir}' is not a numeric version")

        if ver_num != idx:
            raise ValueError(
                f"version_dirs are not in strict sequential order: "
                f"expected {idx} but found '{ver_dir}'"
            )

        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.exists(inv_path):
            # Inventory missing
            raise FileNotFoundError(f"Missing inventory in version directory '{ver_dir}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except (json.JSONDecodeError, OSError) as exc:
            raise ValueError(f"Failed to read inventory from '{inv_path}': {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in '{inv_path}' must be a JSON object")

        if idx == 1:
            # This is the root inventory
            root_inventory = inventory
            continue

        # Compare current inventory against root inventory up to this version
        diffs = {}
        for path, digest in inventory.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                diffs[path] = (digest, root_digest)

        if diffs:
            self.inventory_differences.append((ver_dir, diffs))

        # Merge current inventory into root inventory to represent cumulative state
        root_inventory.update(inventory)

    # If all inventories validated, call any further consistency checks if needed
    return self
<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Verify the path exists
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
    except Exception as exc:
        return f"Error accessing path: {exc}"

    # File cases
    if os.path.isfile(path):
        return 'file'

    # Directory cases
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except Exception as exc:
            return f"Error reading directory: {exc}"

        # Find any Namaste file starting with '0='
        namaste = [e for e in entries if e.startswith('0=')]
        if namaste:
            return 'object'
        else:
            return 'root'

    # Fallback if path is neither file nor directory
    return f"Unknown path type: {path}"<|return|>

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"path '{path}' does not exist"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except (OSError, PermissionError) as exc:
            return f"cannot list directory '{path}': {exc}"

        # Directly under the directory look for a file starting with '0='
        for entry in entries:
            if entry.startswith('0=') and os.path.isfile(os.path.join(path, entry)):
                return 'object'

        # If not found, check immediate subdirectories for a '0=' file
        for entry in entries:
            subpath = os.path.join(path, entry)
            if os.path.isdir(subpath):
                try:
                    sub_entries = os.listdir(subpath)
                except (OSError, PermissionError):
                    continue
                if any(e.startswith('0=') and os.path.isfile(os.path.join(subpath, e)) for e in sub_entries):
                    return 'root'

        return f"directory at '{path}' does not look like a known OCFL location"

    return f"path '{path}' is neither a file nor a directory"<|return|>

def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params by adding a list or single bug id(s) to the
    dictionary that will be used to perform a Bugzilla API request.
    """
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params

    # Determine whether we have a single id or a collection of ids
    if isinstance(bug_ids, (list, tuple, set)):
        values = []
        for b in bug_ids:
            if isinstance(b, (int,)):
                values.append(b)
            elif isinstance(b, str) and b.isdigit():
                values.append(int(b))
            else:
                raise ValueError(f"Bug id must be an int or a digit string, got {b!r}")
        if values:
            params['ids'] = values if len(values) > 1 else values[0]
    else:
        # Assume single id
        if isinstance(bug_ids, str) and bug_ids.isdigit():
            params['ids'] = int(bug_ids)
        else:
            try:
                params['ids'] = int(bug_ids)
            except Exception:
                raise ValueError(f"Bug id must be an int or digit string, got {bug_ids!r}")

    return params<|return|>

def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params by adding a list of bug identifiers.
    """
    # Validate input types
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple of identifiers")

    # Convert all bug IDs to integers if possible; collect valid ids
    cleaned_ids = []
    for bid in bug_ids:
        try:
            cleaned_ids.append(int(bid))
        except Exception as exc:
            raise ValueError(f"Invalid bug ID '{bid}': {exc}") from exc

    if not cleaned_ids:
        # No valid IDs to add; return the original params unchanged
        return params

    # Merge with existing 'ids' entry if present
    existing = params.get('ids')
    if existing is not None:
        # Assume existing ids are comma-separated string
        try:
            existing_ids = {int(i) for i in str(existing).split(',')}
        except Exception:
            existing_ids = set()
    else:
        existing_ids = set()

    merged_ids = sorted(existing_ids.union(cleaned_ids))
    params['ids'] = ','.join(map(str, merged_ids))
    return params<|return|>

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        # Validate input types
        if not isinstance(params, dict):
            raise TypeError("params must be a dictionary")

        # Nothing to amend if no bug_ids supplied
        if bug_ids is None:
            return

        # Standardize bug_ids into a list
        if isinstance(bug_ids, (int, str)):
            ids_iterable = [bug_ids]
        else:
            try:
                ids_iterable = list(bug_ids)
            except Exception as exc:
                raise TypeError("bug_ids must be an int, str, or iterable of ids") from exc

        # Remove any None values
        ids = [str(i) for i in ids_iterable if i is not None]

        # If we have valid ids, set them as a comma‑separated string
        if ids:
            params['ids'] = ",".join(ids)
        else:
            # If the list ended up empty, ensure 'ids' is removed
            params.pop('ids', None)<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to merge two MappingNodes recursively
    def _merge_mapping_nodes(m1, m2):
        """Return a new MappingNode that merges m2 into m1."""
        # Preserve the original tag from the first mapping
        merged_value = list(m1.value)
        # Map key string to its index in merged_value for quick lookup
        idx_map = {entry[0].value: i for i, entry in enumerate(merged_value)}
        for key_node, val_node in m2.value:
            key = key_node.value
            if key in idx_map:
                i = idx_map[key]
                existing_key, existing_val = merged_value[i]
                # Both values are MappingNodes -> deep merge
                if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                    merged_val = _merge_mapping_nodes(existing_val, val_node)
                    merged_value[i] = (existing_key, merged_val)
                else:
                    # Last value wins for non-mapping nodes
                    merged_value[i] = (existing_key, val_node)
            else:
                # Append new key/value pair
                merged_value.append((key_node, val_node))
                idx_map[key] = len(merged_value) - 1
        return ruamel.yaml.nodes.MappingNode(m1.tag, merged_value)

    merged = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_val_node = merged[key]
            if isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = _merge_mapping_nodes(existing_val_node, val_node)
                merged[key] = (existing_key_node, merged_val)
            else:
                # Keep the original key node but replace the value with the last one
                merged[key] = (existing_key_node, val_node)
        else:
            merged[key] = (key_node, val_node)

    # Return the merged list preserving the order of first occurrences
    return [merged[key] for key in merged]<|return|>

def deep_merge_nodes(nodes):
    '''Deep merge a list of node tuples, merging MappingNode values
    on duplicate ScalarNode keys.

    Parameters
    ----------
    nodes : list[tuple[ScalarNode, Node]]
        Each tuple contains a ScalarNode key and an arbitrary Node as
        the value.  MappingNode values are merged recursively.

    Returns
    -------
    list[tuple[ScalarNode, Node]]
        The merged list.  Duplicate keys are merged; for non-mapping
        conflicts the last encountered value wins.
    '''
    def _is_mapping(node):
        # Rough test: mapping nodes have a 'value' list of tuples
        return hasattr(node, 'value') and isinstance(node.value, list)

    def _merge_two(target, source):
        """Return merged node of target with source."""
        if _is_mapping(target) and _is_mapping(source):
            # Build dict of target key -> node for quick lookup
            target_map = {}
            target_order = []
            for k, v in target.value:
                key_str = getattr(k, 'value', None)
                if key_str is None:
                    key_str = str(k)
                target_map[key_str] = (k, v)
                target_order.append(key_str)

            # Merge source into target_map
            for sk, sv in source.value:
                key_str = getattr(sk, 'value', None)
                if key_str is None:
                    key_str = str(sk)
                if key_str in target_map:
                    _, tv = target_map[key_str]
                    merged = _merge_two(tv, sv)
                    target_map[key_str] = (k, merged)
                else:
