    subparser = subparser_action.choices.get(subcommand_name)
    if subparser is None:
        # Subparser definition not found – cannot parse subcommand-specific args
        return result

    # Parse subcommand-specific arguments
    try:
        sub_ns = subparser.parse_args(remaining)
    except Exception as exc:
        # If parsing fails, fall back to an empty namespace for this subcommand
        sub_ns = argparse.Namespace()

