def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("response cannot be None")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Convert response to a list to allow slicing
    try:
        items = list(response)
    except Exception as exc:
        raise TypeError(f"response must be an iterable sequence: {exc}") from exc

    # Generator that yields paginated slices
    def _generator():
        try:
            for start in range(0, len(items), max_results):
                yield items[start:start + max_results]
        except Exception as inner_exc:
            raise RuntimeError(f"Error generating pages: {inner_exc}") from inner_exc

    return _generator()<|return|>

