def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("dicts must be an iterable of dictionaries") from exc

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element at position {idx} is not a dictionary: {d!r}")
        for key, val in d.items():
            if key in result:
                try:
                    result[key] += val
                except Exception as exc:
                    raise TypeError(
                        f"cannot add values for key {key!r}: "
                        f"{result[key]!r} + {val!r}"
                    ) from exc
            else:
                result[key] = val
    return result<|return|>

