    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import defaultdict

    if dicts is None:
        raise ValueError("Input iterable 'dicts' cannot be None")

    result = defaultdict(float)

    try:
        for d in dicts:
            if not isinstance(d, dict):
                continue  # skip non-dict items
            for k, v in d.items():
                if isinstance(v, (int, float)):
                    result[k] += v
                else:
                    # keep the first non-numeric value encountered
                    if k not in result:
                        result[k] = v
    except TypeError:
        raise TypeError("Input must be an iterable of dictionaries")

    # Convert defaultdict back to regular dict, casting sums to int if they are integral
    final = {}
    for k, v in result.items():
        final[k] = int(v) if isinstance(v, float) and v.is_integer() else v
    return final<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    This function looks for placeholders in the format `{key}` or `:key` within
    ``url`` and substitutes them with the corresponding value from the
    ``url_args`` mapping.  Values are URL‑encoded to ensure the resulting URL
    remains valid.  If a key is not present in ``url_args`` the placeholder
    is left unchanged.

    Args:
        url (str): The original URL possibly containing placeholders.
        url_args (Mapping): Mapping of placeholder keys to replacement
            values.  An arbitrary mapping type (e.g., ``dict``, ``OrderedDict``,
            or a list of 2‑tuples) is accepted.

    Returns:
        str: The URL with placeholders replaced by their corresponding
            values.

    Raises:
        TypeError: If ``url_args`` cannot be coerced into a mapping.
    """
    if not url:
        return ''

    # Normalise url_args to a mapping; allow any mapping‑like object
    if not isinstance(url_args, (dict,)):
        try:
            url_args = dict(url_args)
        except Exception:
            raise TypeError('url_args must be a mapping') from None

    # Pattern matches {key} or :key
    placeholder_re = re.compile(r'\{(\w+)\}|:(\w+)')

    def _replacer(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            # Quote the value; empty string is permissible
            try:
                value = url_args[key]
            except Exception:
                value = ''
            return urllib.parse.quote(str(value) if value is not None else '', safe='')
        # No replacement found; keep original placeholder
        return match.group(0)

    try:
        return placeholder_re.sub(_replacer, url)
    except Exception:
        # Graceful fallback: return the original url if replacement fails
        return url<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    # Pattern matches {key} or <key>
    pattern = r'\{(\w+)\}|\<(\w+)\>'

    def _repl(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            try:
                # Encode the value for use in URLs
                value = urllib.parse.quote_plus(str(url_args[key]))
            except Exception:
                # Fallback to string representation if encoding fails
                value = str(url_args[key])
            return value
        # If key not present, leave placeholder unchanged
        return match.group(0)

    return re.sub(pattern, _repl, url)<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url or ''
    try:
        for key, val in url_args.items():
            placeholder = f'{{{key}}}'
            url = url.replace(placeholder, str(val))
    except Exception as exception:
        # In case of any unexpected errors, return the original URL
        return url
    return url<|return|>

