    """
    # Validate processed is a set-like object
    if not isinstance(processed, (set, frozenset)):
        try:
            processed = set(processed)
        except Exception as e:
            if verbose:
                print(f'[was_processed] failed to convert processed to set: {e}')
            return True
    # Validate path_name
    if not isinstance(path_name, str):
        if verbose:
            print(f'[was_processed] path_name is not a string: {type(path_name).__name__}')
        return True
    # Resolve absolute path
    try:
        abs_path = os.path.abspath(path_name)
    except Exception as e:
        if verbose:
            print(f'[was_processed] error resolving absolute path for {path_name!r}: {e}')
        return True
    # Check if already processed
    if abs_path in processed:
        if verbose:
            print(f'[was_processed] already processed: {abs_path}')
        return True
    # Add to processed set
    try:
        processed.add(abs_path)
    except Exception as e:
        if verbose:
            print(f'[was_processed] failed to add to processed set: {e}')
        return True
    if verbose:
        print(f'[was_processed] added to processed: {abs_path}')
    return False<|return|>

def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        n = len(vertices)
    except Exception as exc:
        raise ValueError(f"Input must be a sequence with at least 3 elements, got {vertices!r}") from exc
    if n < 3:
        # Not enough vertices to form triplets
        return []
    try:
        result = [(vertices[i - 1], vertices[i], vertices[(i + 1) % n]) for i in range(n)]
        return result
    except Exception as exc:
        raise ValueError(f"Error processing vertices: {exc}") from exc<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list with at least two distinct symbols")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct symbols")

    # Convert number to base representation using alphabet
    if number == 0:
        s_digits = [alphabet[0]]
    else:
        s_digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            s_digits.append(alphabet[rem])

    # Build the final string (most significant digit first)
    s = ''.join(reversed(s_digits))

    # Apply optional padding with the first alphabet character
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if padding > len(s):
            s = alphabet[0] * (padding - len(s)) + s

    return s<|return|>

