def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    try:
        base = len(alphabet)
    except Exception as exc:
        raise TypeError("alphabet must be a sequence of characters") from exc
    if base == 0:
        raise ValueError("alphabet must contain at least one symbol")

    # Build digit mapping (character → integer value)
    digit_map = {char: i for i, char in enumerate(alphabet)}

    # Compute the numeric value iteratively
    result = 0
    for ch in string:
        try:
            digit = digit_map[ch]
        except KeyError:
            raise ValueError(f"Character '{ch}' not present in alphabet") from None
        result = result * base + digit

    return result<|return|>

