def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Import modules locally to keep the top of the file clean
    import os
    import shutil
    import uuid
    from pathlib import Path

    # Validate that the archive exists
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive path '{archive_path}' does not exist.")

    # Resolve the temporary extraction root
    tmp_root = Path(tmp_path).expanduser()
    if not tmp_root.exists():
        try:
            tmp_root.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create temporary directory '{tmp_root}': {exc}") from exc

    # Determine extraction directory name
    if filename:
        extract_dir = tmp_root / filename
    else:
        # Derive a base name; for multi‑dot archives trim the last extension part
        base = Path(archive_path).stem
        # Trim common archive suffixes for names like .tar.gz -> .tar
        for suffix in ('.tar.gz', '.tar.bz2', '.tgz', '.tbz2'):
            if archive_path.endswith(suffix):
                base = Path(archive_path).stem.split('.')[0]
                break
        extract_dir = tmp_root / base

    # Ensure the extraction directory is unique
    if extract_dir.exists():
        extract_dir = tmp_root / f"{extract_dir.name}_{uuid.uuid4().hex[:8]}"

    try:
        extract_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create extraction directory '{extract_dir}': {exc}") from exc

    # Extract the archive
    try:
        shutil.unpack_archive(archive_path, str(extract_dir))
    except Exception as e:
        # Cleanup partially extracted content
        try:
            shutil.rmtree(extract_dir, ignore_errors=True)
        except Exception:
            pass
        raise ValueError(f"Failed to unpack archive '{archive_path}': {e}") from e

    # Return a file‑scheme URL pointing to the extracted repo
    return f"file://{extract_dir.resolve()}"
<|return|>

