def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency)}")
    freq = frequency.strip().lower()
    if freq == "always":
        return None
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")
    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f"Unable to parse number in frequency: '{num_str}'")
    unit_map = {
        "week": "weeks", "weeks": "weeks",
        "day": "days", "days": "days",
        "hour": "hours", "hours": "hours",
        "minute": "minutes", "minutes": "minutes",
        "min": "minutes", "mins": "minutes",
        "second": "seconds", "seconds": "seconds",
        "sec": "seconds", "secs": "seconds",
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit}'")
    kwarg = {unit_map[unit]: num}
    return datetime.timedelta(**kwarg)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip().lower()
    else:
        raise ValueError('frequency must be a string, None, or "always"')
    if freq_str == "always":
        return None
    # Regular expression to capture an integer followed by a unit
    import re
    m = re.fullmatch(r'\s*(\d+)\s*([a-zA-Z]+)\s*', freq_str)
    if not m:
        raise ValueError(f'Could not parse frequency "{frequency}"')
    amount = int(m.group(1))
    unit = m.group(2).lower()
    # Map unit words (including plurals and common abbreviations) to datetime kwargs
    unit_map = {
        'second': 'seconds', 'seconds': 'seconds', 's': 'seconds',
        'minute': 'minutes', 'minutes': 'minutes', 'm': 'minutes',
        'hour': 'hours',     'hours': 'hours',     'h': 'hours',
        'day': 'days',       'days': 'days',       'd': 'days',
        'week': 'weeks',     'weeks': 'weeks',     'w': 'weeks',
        'month': 'days',     'months': 'days',     'mo': 'days',
        'year': 'days',      'years': 'days',      'y': 'days',
    }
    if unit not in unit_map:
        raise ValueError(f'Unknown time unit "{unit}" in frequency "{frequency}"')
    kwarg = unit_map[unit]
    if kwarg == 'days':
        # Determine days count based on unit: months ≈ 30, years ≈ 365
        if unit in ('month', 'months', 'mo'):
            days = amount * 30
        elif unit in ('year', 'years', 'y'):
            days = amount * 365
        else:
            days = amount
        return datetime.timedelta(days=days)
    else:
        return datetime.timedelta(**{kwarg: amount})<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        host_str = str(host).strip()
        # Quick string check for common forms
        if host_str.lower() in ("localhost", "127.0.0.1", "::1"):
            return True

        # Resolve the hostname or IP and examine the results
        for result in socket.getaddrinfo(host_str, None):
            family, _, _, _, sockaddr = result
            ip = sockaddr[0]
            if family == socket.AF_INET and ip == "127.0.0.1":
                return True
            if family == socket.AF_INET6 and ip in ("::1", "::"):
                return True
    except socket.gaierror:
        # hostname could not be resolved
        pass
    return False<|return|>

