        if family == socket.AF_INET6 and '%' in addr:
            addr = addr.split('%')[0]
        if family == socket.AF_INET and addr == "127.0.0.1":
            return True
        if family == socket.AF_INET6 and addr == "::1":
            return True

    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    try:
        import ipaddress
    except ImportError:
        ipaddress = None
    for res in addrinfo:
        af, socktype, proto, canonname, sa = res
        ip = sa[0]
        if ipaddress:
            try:
                if ipaddress.ip_address(ip).is_loopback:
                    return True
            except ValueError:
                # Not a valid IP address, skip to next
                continue
        else:
            if af == socket.AF_INET and ip.startswith("127."):
                return True
            if af == socket.AF_INET6 and ip.lower() == "::1":
                return True
    return False<|return|>

