    if os.path.isfile(config_path):
        if not overwrite:
            raise FileExistsError(f"File '{config_path}' already exists and overwrite is False")
    else:
        # Ensure parent directories exist
        parent_dir = os.path.dirname(config_path)
        if parent_dir:
            try:
                os.makedirs(parent_dir, exist_ok=True)
            except OSError as exc:
                # If directory creation failed and the directory still doesn't exist, re-raise
                if not os.path.isdir(parent_dir):
                    raise
    # Write the content
    try:
        with open(config_path, 'w') as f:
            f.write(rendered_config)
        os.chmod(config_path, mode)
    except OSError as exc:
        # Clean up partially written file if an error occurs
        if os.path.exists(config_path):
            try:
                os.remove(config_path)
