    # Expand user and normalize path
    config_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite is False
    if not overwrite and os.path.isfile(config_path):
        return

    directory = os.path.dirname(config_path)
    if directory:
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError as e:
            # If the directory still does not exist after attempt, re-raise
            if not os.path.isdir(directory):
