def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract name and default value from the matcher.  The matcher may be a dict, a
    # regex match object, a tuple/list, an object with attributes, or simply a string.
    name = None
    default = None

    # Dict-like matcher
    if isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")

    # Regex match object or any object with groupdict()
    elif hasattr(matcher, "groupdict"):
        gd = matcher.groupdict()
        name = gd.get("name")
        default = gd.get("default")

    # Tuple or list of (name, default?)
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) > 0:
            name = matcher[0]
        if len(matcher) > 1:
            default = matcher[1]

    # Generic object with attributes
    elif hasattr(matcher, "__dict__"):
        if hasattr(matcher, "name"):
            name = matcher.name
        if hasattr(matcher, "default"):
            default = matcher.default

    # Fallback: the matcher itself is a string indicating the variable name
    elif isinstance(matcher, str):
        name = matcher

    # If we still don't have a name, the caller provided an unsupported matcher.
    if name is None:
        raise TypeError("matcher must contain a 'name' field or be a string")

    # Convert the name to a string if it isn't already.
    if not isinstance(name, str):
        try:
            name = str(name)
        except Exception as exc:  # pragma: no cover
            raise TypeError("Variable name could not be converted to string") from exc

    # Retrieve the environment variable.
    if name not in os.environ:
        if default is None:
            raise EnvironmentError(f"Environment variable '{name}' not found and no default provided.")
        return default
    return os.environ[name]<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern
    """
    # Determine the type used for compiled regex objects
    try:
        _pattern_type = type(re.compile(''))
    except AttributeError:
        _pattern_type = getattr(re, '_pattern_type', None)

    if pattern is None:
        raise ValueError("The pattern argument cannot be None")

    if isinstance(pattern, _pattern_type):
        return pattern

    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regular expression: {exc}") from None

    raise TypeError(
        f"Unsupported pattern type: {type(pattern).__name__}. "
        "Expected a string or a compiled regular expression."
    )<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # If no pattern is provided, return None
    if pattern is None:
        return None

    # If the pattern is already a compiled regex, return it unchanged
    # In Python 3.7+, re.Pattern represents the compiled regex type
    # For other versions, check for the presence of a 'pattern' attribute
    if hasattr(pattern, "pattern") and isinstance(pattern.pattern, str):
        return pattern

    # If the pattern is a string, optionally strip whitespace and compile it
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as exc:
            # Provide a clear error message for invalid regex strings
            raise ValueError(f"Invalid regex pattern: {pattern}") from exc

    # For all other types, raise a descriptive TypeError
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")<|return|>

