        for s, p, o in graph.triples((None, prop, None)):
            subjects.add(s)
            objects.add(o)
    except Exception as exc:
        raise RuntimeError(
            f"Error while iterating over graph for property {prop}: {exc}"
        ) from exc

    all_nodes = subjects | objects
    root_nodes = {node for node in all_nodes if node not in objects}

    if roots is not None:
        try:
            roots_intersect = set(roots)
        except TypeError as exc:
            raise TypeError("roots parameter must be a set-like object of Nodes") from exc
        root_nodes &= roots_intersect

    return root_nodes
