def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    try:
        # Accept a list by converting it to a tuple
        shape_tuple = tuple(shape)
        if not isinstance(shape_tuple, (tuple, list)):
            raise TypeError
        for idx, dim in enumerate(shape_tuple):
            if not isinstance(dim, (int, np.integer)):
                raise TypeError(f"Dimension {idx} of shape is not an integer: {dim!r}")
            if dim < 0:
                raise ValueError(f"Dimension {idx} of shape cannot be negative: {dim!r}")
    except Exception as exc:
        raise ValueError("Invalid shape argument; must be a tuple of non‑negative integers.") from exc

    # Convert dtype if needed
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype argument: {dtype!r}") from exc

    # Create and return the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc<|return|>

