            raise TypeError("shape must be an iterable of integers")
        if any(not isinstance(dim, int) or dim < 0 for dim in shape):
            raise ValueError("all dimensions in shape must be non‑negative integers")
    except Exception as exc:
        raise ValueError(f"Invalid shape {shape!r}: {exc}") from exc

    # Ensure dtype is a numpy dtype object
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype {dtype!r}: {exc}") from exc

    try:
