def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml

    configs = {}
    error_records = []

    if not isinstance(config_filenames, (list, tuple)):
        raise TypeError('config_filenames must be a list or tuple of filenames')

    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError('overrides must be a dict or None')

    def _expand_env(value):
        """Recursively expand environment variables in strings."""
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    for fname in config_filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"Configuration file not found: {fname}")

            with open(fname, 'r', encoding='utf-8') as fp:
                raw = fp.read()

            # Determine parser based on file extension
            ext = os.path.splitext(fname)[1].lower()
            if ext in ('.yaml', '.yml'):
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                parsed = toml.loads(raw)
            elif ext == '.json':
                parsed = json.loads(raw)
            else:
                # Unsupported format: treat as raw string
                parsed = raw

            if isinstance(parsed, dict) and overrides:
                # Shallow merge overrides into parsed config
                parsed.update(overrides)

            if resolve_env and isinstance(parsed, dict):
                parsed = _expand_env(parsed)

            configs[fname] = parsed

        except Exception as e:
            # Create a LogRecord summarizing the error
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                fn=fname,
                lno=0,
                msg=f"Error parsing configuration '{fname}': {e}",
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return (configs, error_records)<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple containing:
        * dict mapping configuration filename to the parsed configuration (as a dict)
        * sequence of logging.LogRecord instances for any parse errors encountered.
    """
    import os
