    try:
        import yaml
    except Exception:
        yaml = None

    try:
        import toml
    except Exception:
        toml = None

    configs = {}
    error_records = []

    def make_error_record(filename, message, exc_type=None, exc_value=None):
        """Helper to create a LogRecord with ERROR level."""
        return logging.makeRecord(
            name="config_loader",
            level=logging.ERROR,
            fn=filename,
            lno=0,
            msg=message,
            args=(),
            exc_info=(exc_type, exc_value, exc_value.__traceback__) if exc_type else None
        )

    def _expand_env(obj):
        """Recursively expand environment variables in strings."""
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        if isinstance(obj, dict):
            return {k: _expand_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env(v) for v in obj]
        return obj

    for fname in config_filenames:
        if not isinstance(fname, str):
            error_records.append(make_error_record(str(fname), f"Invalid filename type: {type(fname).__name__}"))
            continue
        if not os.path.exists(fname):
            error_records.append(make_error_record(fname, "Configuration file does not exist"))
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                content = fd.read()
        except Exception as exc:
            error_records.append(make_error_record(fname, f"Failed to read file: {exc}", type(exc), exc))
            continue

        parsed = None
        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext in {'.yaml', '.yml'}:
                if yaml is None:
                    raise ImportError("yaml module not available")
                parsed = yaml.safe_load(content)
            elif ext == '.toml':
                if toml is None:
                    raise ImportError("toml module not available")
                parsed = toml.loads(content)
            elif ext == '.json':
                parsed = json.loads(content)
            else:
                # Try generic YAML loader as fallback
                if yaml is not None:
                    parsed = yaml.safe_load(content)
                else:
                    raise ValueError(f"Unsupported file extension: {ext}")
        except Exception as exc:
            error_records.append(make_error_record(fname, f"Parse error: {exc}", type(exc), exc))
            parsed = None

        if parsed is None:
            error_records.append(make_error_record(fname, "Parsed configuration is None"))
            continue

        if not isinstance(parsed, dict):
            error_records.append(make_error_record(fname, f"Configuration must be a dict, got {type(parsed).__name__}"))
            continue

        # Apply overrides if provided
        if overrides:
            if not isinstance(overrides, dict):
                error_records.append(make_error_record(fname, f"Overrides is not a dict: {type(overrides).__name__}"))
            else:
                parsed.update(overrides)

        # Resolve environment variables if requested
        if resolve_env:
            parsed = _expand_env(parsed)

        configs[fname] = parsed

    return configs, error_records<|return|>

