def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import re
    import logging

    parsed_configs = {}
    error_records = []
    logger_name = 'config_loader'
    logger = logging.getLogger(logger_name)

    def _create_error_record(msg, exc_info=None):
        """Create a LogRecord with level ERROR containing the given message."""
        return logging.LogRecord(logger_name, logging.ERROR,
                                 pathname=os.path.abspath(__file__),
                                 lineno=0, msg=msg, args=(), exc_info=exc_info)

    def _resolve_env_in_string(value):
        """Recursively replace ${VAR} patterns with environment variable values."""
        pattern = re.compile(r'\$\{([^}]+)\}')
        # Limit recursion depth to avoid infinite loops
        def replacer(match):
            var_name = match.group(1)
            return os.getenv(var_name, '')
        if isinstance(value, str):
            return pattern.sub(replacer, value)
        return value

    def _recursively_resolve(obj):
        """Walk through dict/list/tuple and resolve env placeholders in all string leaves."""
        if isinstance(obj, dict):
            return {k: _recursively_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, (list, tuple)):
            return type(obj)(_recursively_resolve(v) for v in obj)
        elif isinstance(obj, str) and resolve_env:
            return _resolve_env_in_string(obj)
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
        except Exception as exc:
            rec = _create_error_record(f"Failed to open configuration file '{filename}': {exc}",
                                       exc_info=(type(exc), exc, exc.__traceback__))
            error_records.append(rec)
            continue

        # Attempt json first, then yaml
        config = None
        try:
            config = json.loads(raw)
        except json.JSONDecodeError:
            try:
                config = yaml.safe_load(raw)
            except Exception as exc:
                rec = _create_error_record(f"Failed to parse file '{filename}' as JSON or YAML: {exc}",
                                           exc_info=(type(exc), exc, exc.__traceback__))
                error_records.append(rec)
                continue

        if not isinstance(config, dict):
            rec = _create_error_record(f"Configuration file '{filename}' did not contain a dictionary.")
            error_records.append(rec)
            continue

        if resolve_env:
            config = _recursively_resolve(config)

        if overrides and isinstance(overrides, dict):
            config.update(overrides)

        parsed_configs[filename] = config

    return parsed_configs, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os, logging, yaml, toml, re, copy

    parsed_configs = {}
    error_records = []

    def _make_error_record(file_path, msg):
        return logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=file_path,
            lineno=0,
            msg=msg,
            args=None,
            exc_info=None
        )

    def _resolve_env(var, original):
        if isinstance(original, str):
            pattern = re.compile(r'\${([^}]+)}')
            def repl(match):
                env_var = match.group(1)
                return os.getenv(env_var, match.group(0))
            return pattern.sub(repl, original)
        return original

    def _recursive_resolve_env(obj):
        if isinstance(obj, dict):
            return {k: _recursive_resolve_env(_resolve_env(k, v)) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_recursive_resolve_env(_resolve_env('', item)) for item in obj]
        if isinstance(obj, str):
            return _resolve_env('', obj)
        return obj

    for fname in config_filenames:
        try:
            if not os.path.exists(fname):
                error_records.append(_make_error_record(fname, f'Configuration file not found: {fname}'))
                continue

            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()

            if fname.lower().endswith('.toml'):
                try:
                    cfg = toml.loads(content)
                except Exception as exc:
                    error_records.append(_make_error_record(fname, f'Error parsing TOML: {exc}'))
                    continue
            elif fname.lower().endswith(('.yaml', '.yml')):
                try:
                    cfg = yaml.safe_load(content)
                except Exception as exc:
                    error_records.append(_make_error_record(fname, f'Error parsing YAML: {exc}'))
                    continue
            else:
                # Unsupported file format
                error_records.append(_make_error_record(fname, f'Unsupported configuration format for file: {fname}'))
                continue

            if cfg is None:
                cfg = {}

            if resolve_env:
                try:
                    cfg = _recursive_resolve_env(cfg)
                except Exception as exc:
                    error_records.append(_make_error_record(fname, f'Error resolving environment variables: {exc}'))
                    continue

            if not isinstance(cfg, dict):
                error_records.append(_make_error_record(fname, f'Configuration root is not a dictionary: {fname}'))
                continue

            if overrides:
                cfg = copy.deepcopy(cfg)
                cfg.update(overrides)

            parsed_configs[fname] = cfg

        except Exception as exc:
            error_records.append(_make_error_record(fname, f'Unexpected error: {exc}'))

    return parsed_configs, error_records<|return|>

