    if protocol_version is not None:
        # Return a dict containing the handler if supported, else empty
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
    return handlers<|return|>

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # The class is expected to maintain a mapping from version tuple
        # to handler class in a class attribute called `PROTOCOL_HANDLERS`.
        # This is a conventional name; if it is missing or not a dict we
        # simply treat as no handlers.
        handlers = getattr(cls, 'PROTOCOL_HANDLERS', {})
        if not isinstance(handlers, dict):
            handlers = {}

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            # Return a mapping that contains the exact key if present,
            # otherwise an empty dict.
            return {protocol_version: handlers[protocol_version]}
            # If not found, a KeyError is raised; we catch it and return
            # an empty mapping instead of propagating.
        try:
            return dict(handlers)
        except Exception:
            # If handlers is not directly convertible to dict (unlikely),
            # fall back to an empty mapping.
            return {}<|return|>

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        try:
            values_list = list(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable") from exc

        for v in values_list:
            if not isinstance(v, str):
                raise TypeError(f"bookmark value must be a string, got {type(v).__name__}")

        return cls(values_list)<|return|>

def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    # Ensure the input is iterable
    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}") from exc

    cleaned = []
    for index, item in enumerate(iterator):
        if not isinstance(item, str):
            raise TypeError(f"bookmark at position {index} is not a string: {type(item).__name__}")
        stripped = item.strip()
        if stripped == '':
            continue  # ignore empty values
        try:
            stripped.encode('ascii')
        except UnicodeEncodeError:
            raise ValueError(f"bookmark string at position {index} contains non-ASCII characters: {item!r}")
        cleaned.append(stripped)

    if not cleaned:
        # Return an empty Bookmarks instance
        return cls(())

    return cls(tuple(cleaned))<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # Detect whether seq behaves like a sequence (excluding strings and bytes)
    def _is_sequence(x):
        return hasattr(x, "__iter__") and not isinstance(x, (str, bytes))
    if seq is None:
        raise TypeError("Provided sequence is None")
    if _is_sequence(seq):
        return seq, type(seq).__name__
    # Convert non‑sequence inputs to a list (or limited size list if bufsize given)
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            seq_list = []
            for i, item in enumerate(seq):
                if i >= bufsize:
                    break
                seq_list.append(item)
        return seq_list, type(seq_list).__name__
    except TypeError as exc:
        raise TypeError(f"Input {seq!r} cannot be converted to a sequence") from exc
    except Exception as exc:
        raise RuntimeError(f"Error converting {seq!r} to sequence") from exc<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Quick paths for common sequence types
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # seq is not a simple built‑in sequence – try to build a list
    try:
        if bufsize is None:
            derived = list(seq)
        else:
            derived = []
            it = iter(seq)
            for _ in range(bufsize):
                try:
                    derived.append(next(it))
                except StopIteration:
                    break
        return derived, list
    except TypeError as exc:
        # seq is not iterable
        raise Exception("Input is not iterable") from exc<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Import Sequence from collections.abc for type checking
    try:
        from collections.abc import Sequence as _Sequence
    except Exception:
        # Fallback for older Python versions
        _Sequence = (list, tuple, str, bytes, bytearray)

    # If seq is already a sequence type (including strings and bytes)
    if isinstance(seq, _Sequence):
        return seq, type(seq)

    # seq is not a sequence type; attempt to convert to a list
    try:
        seq_list = list(seq)
    except Exception as exc:
        raise TypeError("Provided seq is not iterable or cannot be converted to a list") from exc

    # Optionally buffer the sequence into sublists of size 'bufsize'
    if bufsize is not None:
        if not isinstance(bufsize, int) or bufsize <= 0:
            raise ValueError("bufsize must be a positive integer if provided")
        # Chunk the list into smaller lists of length bufsize
        seq_list = [
            seq_list[i : i + bufsize] for i in range(0, len(seq_list), bufsize)
        ]

    return seq_list, type(seq_list)<|return|>

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral
    def _compute_scale():
        if hasattr(self, "histogram"):
            try:
                return np.nansum(self.histogram)
            except Exception:
                # fallback for Python list or similar
                return sum(self.histogram)
        raise AttributeError("Histogram data not found")

    # Return current scale
    if other is None:
        if not hasattr(self, "_scale") or self._scale is None or recompute:
            self._scale = _compute_scale()
        return self._scale

    # Rescale histogram to a new target scale
    try:
        target_scale = float(other)
    except Exception:
        raise TypeError("'other' must be a numeric value")

    # Ensure current scale is available
    if not hasattr(self, "_scale") or self._scale is None:
        self._scale = _compute_scale()

    current_scale = self._scale
    if current_scale == 0:
        # Raise the documented error type if available
        err_cls = globals().get("LenaValueError", ValueError)
        raise err_cls("Cannot rescale histogram with zero scale")

    factor = target_scale / current_scale
    if hasattr(self, "histogram"):
        self.histogram *= factor
    else:
        raise AttributeError("Histogram data not found")

    self._scale = target_scale
    # No explicit return value for rescaling

<|return|>

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Helper to get the unit scale of the graph
    def _get_current_scale():
        # Expect a numeric ``_scale`` attribute or compute from data
        if hasattr(self, "_scale") and self._scale is not None:
            return float(self._scale)
        # Attempt to infer from last coordinate range
        if hasattr(self, "fields") and isinstance(self.fields, (dict, list)):
            if isinstance(self.fields, dict):
                # Get the last inserted coordinate array
                last_key = next(reversed(self.fields))
                coord = self.fields[last_key]
            else:
                coord = self.fields[-1]
            try:
                arr = coord if isinstance(coord, (list, tuple, np.ndarray)) else np.array(coord)
                lim = np.max(arr) - np.min(arr)
                return float(lim) if lim > 0 else None
            except Exception:
                return None
        return None

    try:
        # Getting the current scale
        if other is None:
            current = _get_current_scale()
            if current is None:
                raise LenaValueError("Graph scale is unknown")
            return current

        # Setting a new scale
        new_scale = float(other)
    except Exception as err:
        raise TypeError("Scale must be a numerical value") from err

    current_scale = _get_current_scale()
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero current scale")

    # Compute factor for rescaling
    factor = new_scale / current_scale

    # Rescale only the last coordinate (and its associated error if present)
    if hasattr(self, "fields") and isinstance(self.fields, (dict, list)):
        if isinstance(self.fields, dict):
            last_key = next(reversed(self.fields))
            arr = self.fields[last_key]
            # Ensure numpy array for easy scaling
            try:
                np_arr = np.array(arr, dtype=float)
                np_arr *= factor
                self.fields[last_key] = np_arr
            except Exception:
                pass
            # Rescale associated errors if any
            if hasattr(self, "errors") and isinstance(self.errors, dict):
                if last_key in self.errors:
                    try:
                        err_arr = np.array(self.errors[last_key], dtype=float)
                        err_arr *= abs(factor)
                        self.errors[last_key] = err_arr
                    except Exception:
                        pass
        else:
            # Assume list-based coordinates
            last_idx = -1
            try:
                arr = self.fields[last_idx]
                np_arr = np.array(arr, dtype=float)
                np_arr *= factor
                self.fields[last_idx] = np_arr
            except Exception:
                pass
            if hasattr(self, "errors") and isinstance(self.errors, list):
                if len(self.errors) > abs(last_idx):
                    try:
                        err_arr = np.array(self.errors[last_idx], dtype=float)
                        err_arr *= abs(factor)
                        self.errors[last_idx] = err_arr
                    except Exception:
                        pass

    # Update internal scale representation
    if hasattr(self, "_scale"):
        self._scale = new_scale

    return self
<|return|>

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale is requested.
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that *other* is numeric.
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("The requested scale value must be numeric.") from exc

    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError(
            "Cannot rescale: the current scale is unknown or zero."
        )

    # Compute rescaling ratio and update the internal scale value.
    ratio = new_scale / current_scale
    self._scale = new_scale

    # Attempt to find coordinate fields dynamically.
    # Common convention: coordinates are stored on the instance as attributes
    # whose names do not end with "_error" and are numeric arrays or lists.
    # We also consider an explicit list of coordinate names if present.
    coord_names = getattr(self, "_coords", None)
    if coord_names is None:
        # Infer coordinate names by checking attributes.
        coord_names = [
            name
            for name, val in vars(self).items()
            if not name.endswith("_error") and isinstance(val, (list, tuple, np.ndarray))
        ]

    for name in coord_names:
        val = getattr(self, name)
        if isinstance(val, (list, tuple, np.ndarray)):
            # Multiply each coordinate value by the rescaling ratio.
            try:
                setattr(self, name, np.array(val) * ratio)
            except Exception:
                # If the value cannot be NumPy-ified, attempt plain multiplication.
                setattr(self, name, type(val)(v * ratio for v in val))

    # Rescale error fields if they exist.
    for name, val in vars(self).items():
        if name.endswith("_error") and isinstance(val, (list, tuple, np.ndarray)):
            try:
                setattr(self, name, np.array(val) * ratio)
            except Exception:
                setattr(self, name, type(val)(v * ratio for v in val))

    return self
<|return|>

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import Invalid
    import inspect

    errors = []

    # 1. Provided check (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise Invalid(f"{candidate} does not provide interface {iface}")
        except Exception as exc:
            errors.append(Invalid(f"ProvidedBy check failed for {candidate}: {exc}"))

    # 2. Collect interface names (methods and attributes)
    try:
        iface_names = set(iface.names())
    except AttributeError:
        # Fallback if names() not available
        iface_names = set()
        for attr in dir(iface):
            if not attr.startswith('_'):
                iface_names.add(attr)

    for name in iface_names:
        # Skip private names
        if name.startswith('_'):
            continue
        try:
            interface_attr = getattr(iface, name)
        except Exception:
            interface_attr = None
        # Candidate attribute
        if not hasattr(candidate, name):
            errors.append(
                Invalid(f"Candidate {candidate} missing required attribute {name}")
            )
            continue
        candidate_attr = getattr(candidate, name)

        # If interface expects a method
        if callable(interface_attr) and inspect.isfunction(inspect.getattr_static(iface, name, None)):
            # Compare signatures if both are callables
            try:
                sig_iface = inspect.signature(interface_attr)
                sig_candidate = inspect.signature(candidate_attr)
                # Compare parameters ignoring the first 'self' param if present
                def normalize(sig):
                    params = list(sig.parameters.values())
                    if params and params[0].name == 'self':
                        params = params[1:]
                    return [p.kind for p in params], [p.default for p in params]
                iface_params, iface_defaults = normalize(sig_iface)
                cand_params, cand_defaults = normalize(sig_candidate)
                if len(iface_params) != len(cand_params) or any(
                    a != b for a, b in zip(iface_params, cand_params)
                ):
                    errors.append(
                        Invalid(
                            f"Signature mismatch for method {name}: "
                            f"interface expects {sig_iface}, candidate provides {sig_candidate}"
                        )
                    )
            except Exception as exc:
                errors.append(
                    Invalid(f"Could not inspect signatures for {name}: {exc}")
                )
        # If interface expects an attribute (non-callable)
        else:
            # no further checks needed for attributes
            pass

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid(errors)

    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        # Determine if candidate is a class or an instance
        if isinstance(candidate, type):
            # Candidate is a class: verify subclass relationship
            if not issubclass(candidate, iface):
                raise TypeError(
                    f"Candidate class '{candidate.__name__}' does not subclass the interface '{iface.__name__}'."
                )
        else:
            # Candidate is an instance: verify isinstance
            if not isinstance(candidate, iface):
                raise TypeError(
                    f"Candidate instance of type '{type(candidate).__name__}' does not satisfy the interface '{iface.__name__}'."
                )

        # If the interface declares abstract methods, ensure they are implemented
        abstract_methods = getattr(iface, "__abstractmethods__", None)
        if abstract_methods:
            for name in abstract_methods:
                if not hasattr(candidate, name):
                    raise AttributeError(
                        f"Candidate is missing abstract method '{name}' required by the interface."
                    )
                attr = getattr(candidate, name)
                if not callable(attr):
                    raise TypeError(
                        f"Attribute '{name}' of candidate is not callable as required by the interface."
                    )

        return True
    except Exception as exc:
        if tentative:
            return False
        raise
<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if candidate is None:
        raise TypeError("candidate cannot be None")

    # Resolve class to check (support for class objects or instances)
    clazz = candidate if isinstance(candidate, type) else type(candidate)

    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class/type, got {type(iface).__name__}")

    # For tentative checks we only verify subclass relationship
    if tentative:
        return issubclass(clazz, iface)

    # Ensure direct subclassing
    if not issubclass(clazz, iface):
        raise TypeError(f"{clazz.__name__} does not inherit from {iface.__name__}")

    # Gather any abstract methods that need concrete implementation
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    missing = []

    for name in abstract_methods:
        # Skip dunder/special methods
        if name.startswith("_") and name.endswith("_"):
            continue
        if not hasattr(clazz, name):
            missing.append(name)
            continue
        # Ensure the candidate's attribute is callable
        attr = getattr(clazz, name)
        if not callable(attr):
            missing.append(name)

    if missing:
        raise TypeError(
            f"{clazz.__name__} is missing implementations for abstract methods: "
            f"{', '.join(sorted(missing))}"
        )

    # All checks passed
    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Gather metaclasses from bases
    try:
        base_mcs = [type(b) for b in bases]
    except Exception:
        base_mcs = []

    # If an explicit metaclass is provided, prepend it to the list
    candidate_mcs = [explicit_mc] if explicit_mc is not None else []
    candidate_mcs.extend(base_mcs)

    # If no candidates, default to the built‑in type
    if not candidate_mcs:
        return type

    # Resolve the most derived metaclass
    resolved = candidate_mcs[0]
    for mc in candidate_mcs[1:]:
        try:
            if issubclass(resolved, mc):
                # resolved is already a subclass of mc; keep resolved
                continue
            if issubclass(mc, resolved):
                # mc is more derived; adopt mc
                resolved = mc
                continue
        except Exception:
            # In case issubclass fails (e.g., not a class), fallback
            pass
        # Conflict: no metaclass is a subclass of all others
        raise TypeError(
            f"metaclass conflict: {resolved!r} vs {mc!r} are not compatible"
        )
    return resolved<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was specified, it takes precedence.
    if explicit_mc is not None:
        return explicit_mc

    # No bases specified – fall back to the default metaclass.
    if not bases:
        return type

    # Gather the metaclasses of each provided base.
    try:
        metaclasses = [type(b) for b in bases]
    except Exception as exc:
        raise TypeError(f"Error obtaining metaclasses from bases {bases!r}: {exc}") from exc

    # Identify the most derived metaclass that is a subclass of all others.
    chosen = None
    for cls in metaclasses:
        if all(issubclass(cls, other) for other in metaclasses):
            chosen = cls
            break

    if chosen is None:
        # No compatible metaclass found – report a conflict.
        base1, base2 = metaclasses[0], metaclasses[1] if len(metaclasses) > 1 else (type, type)
        raise TypeError(
            f"metaclass conflict: {base1} and {base2} are incompatible"
        )

    return chosen
<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate that all bases are types
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a type")
    # If an explicit metaclass is provided, use it after validation
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        mcls = explicit_mc
        # Ensure the explicit metaclass is compatible with all bases
        for base in bases:
            base_meta = type(base)
            if not issubclass(mcls, base_meta):
                # Try to find a common ancestor metaclass
                for cls in mcls.__mro__:
                    if issubclass(base_meta, cls):
                        mcls = cls
                        break
                else:
                    raise TypeError(
                        f"metaclass conflict between {mcls!r} and {base_meta!r}"
                    )
        return mcls
    # No explicit metaclass; derive from given bases
    if not bases:
        return type
    # Start with the metaclass of the first base
    mcls = type(bases[0])
    # Ensure compatibility with all other bases
    for base in bases[1:]:
        base_meta = type(base)
        if not issubclass(mcls, base_meta):
            # Find the nearest common ancestor
            for cls in mcls.__mro__:
                if issubclass(base_meta, cls):
                    mcls = cls
                    break
            else:
                raise TypeError(
                    f"metaclass conflict between {mcls!r} and {base_meta!r}"
                )
    return mcls<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Gather the metaclasses of the provided bases
    metaclasses = []
    for base in bases:
        try:
            metaclasses.append(type(base))
        except Exception as exc:
            raise TypeError(f"Base {base!r} is not a class (type: {type(base)!r})") from exc

    # If an explicit metaclass is supplied, validate its compatibility
    if explicit_mc is not None:
        # The explicit metaclass must be a subclass of type
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit __metaclass__ must be a class, got {type(explicit_mc)!r}")
        for m in metaclasses:
            if not issubclass(explicit_mc, m):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc!r} is not compatible "
                    f"with the metaclass of base {m!r}"
                )
        metaclasses.append(explicit_mc)

    # If no bases and no explicit metaclass, default to the built-in type
    if not metaclasses:
        return type

    # Determine the most derived metaclass (the one that is a subclass of all others)
    candidate = metaclasses[0]
    for m in metaclasses[1:]:
        try:
            if issubclass(candidate, m):
                # candidate is already the more derived one
                continue
            if issubclass(m, candidate):
                # m is more derived, replace candidate
                candidate = m
                continue
            # Neither is subclass of the other -> incompatible
            raise TypeError(
