def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    try:
        # Regex to find URLs while avoiding trailing punctuation and quotes
        url_re = re.compile(r'(https?://[^\s"\'<>\)\(]+)')
        def replace_match(m):
            url = m.group(0)
            # Add default target and rel attributes
            attrs = ' target="_blank" rel="noopener noreferrer"'
            return f'<a href="{url}"{attrs}>{url}</a>'
        return url_re.sub(replace_match, text)
    except Exception:
        # On failure fall back to original text
        return text<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("process_text_links expects a string")
    import re, os
    # cache for repeated URLs
    _memo = {}
    # Matches http/https URLs and also plain relative paths
    _RE = re.compile(r'\b((?:https?://|[^\s/]+(?:/[^ /\s]+)*))\b')
    def _replace(m):
        raw = m.group(1)
        # Try cache first
        if raw in _memo:
            return _memo[raw]
        # Decide if it's a URL or a file path
        if raw.startswith(('http://', 'https://')):
            result = f'<a href="{raw}" target="_blank" rel="noopener noreferrer">{raw}</a>'
        else:
            # treat as relative file path; use /browse/ prefix if file exists
            if os.path.exists(raw):
                result = f'<a href="/browse/{raw}" target="_blank" rel="noopener noreferrer">{raw}</a>'
            else:
                result = raw
        _memo[raw] = result
        return result
    try:
        return _RE.sub(_replace, text)
    except Exception:
        # In case of any error, fall back to original text
        return text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    from urllib.parse import urlsplit
    from urllib.request import Request, urlopen
    try:
        parsed = urlsplit(url)
        if parsed.scheme not in ("http", "https"):
            return None
        req = Request(url, method="HEAD")
        with urlopen(req, timeout=10) as resp:
            return resp.getheader("content-type")
    except Exception:
        return None<|return|>

