    try:
        children_iterable = iter(node)
    except TypeError:
        raise TypeError(f"Expected an element-like node, got {type(node).__name__}")
    result = {}
    for child in children_iterable:
        if not hasattr(child, "tag"):
            continue  # skip non-element items
        key = child.tag
        # If child has no sub-elements, use its text (stripped if not None)
        if len(child) == 0:
