def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    try:
        # Get children in a way that works with both Python 2 and 3 ElementTree.
        if hasattr(node, 'getchildren'):  # ElementTree in Python <= 2
            children = node.getchildren()
        else:
            children = list(node)

        result = {}
        for child in children:
            # Normalize tag name by stripping namespace if present.
            tag = child.tag
            if isinstance(tag, str):
                if '}' in tag:
                    tag = tag.split('}', 1)[1]
            else:
                # For safety, convert non-string tags to string.
                tag = str(tag)

            # Determine if the child has nested children.
            if hasattr(child, 'getchildren'):
                has_children = bool(child.getchildren())
            else:
                has_children = bool(list(child))

            # Value is the text if leaf, otherwise keep the element itself.
            value = child.text if not has_children else child

            # Handle duplicate tags by storing a list.
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(value)
                else:
                    result[tag] = [existing, value]
            else:
                result[tag] = value

        return result
    except Exception as exc:
        # If anything unexpected happens, re-raise with a more helpful message.
        raise ValueError(f"Error converting XML children to dict for node {node!r}") from exc<|return|>

