def verify_relayable_signature(public_key, doc, signature):
    """ Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message. """
    try:
        # Load the public key. If a path is given, read the PEM file,
        # otherwise treat the input directly as key data.
        if isinstance(public_key, (bytes, bytearray)):
            key_data = public_key
        else:
            with open(public_key, "rb") as f:
                key_data = f.read()
        from cryptography.hazmat.primitives.serialization import load_pem_public_key
        pub_key_obj = load_pem_public_key(key_data)
    except Exception:
        return False  # unable to load public key

    try:
        # Normalize inputs
        if isinstance(signature, str):
            sig_bytes = base64.b64decode(signature)
        else:
            sig_bytes = signature
        if isinstance(doc, str):
            doc_bytes = doc.encode("utf-8")
        else:
            doc_bytes = doc

        # Verify the signature using SHA‑256 and PKCS#1 v1.5 padding.
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.hazmat.primitives import hashes
        pub_key_obj.verify(
            sig_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256(),
        )
        return True
    except Exception:
        return False  # signature verification failed or invalid signature format
