def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # First try JSON
    try:
        obj = json.loads(document)
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
    except ImportError:
        return None

    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return None

    # Helper to remove namespace
    def _strip_ns(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    # Extract subject
    subject_elem = None
    for elem in root.iter():
        if _strip_ns(elem.tag).lower() == "subject":
            subject_elem = elem
            break
    subject = subject_elem.text if subject_elem is not None else None

    # Extract aliases (Href or Alias elements)
    aliases: List[str] = []
    for elem in root.iter():
        tag = _strip_ns(elem.tag).lower()
        if tag == "link":
            href = elem.attrib.get("href") or elem.attrib.get("href")
            if href:
                aliases.append(href)
        elif tag == "alias" and elem.text:
            aliases.append(elem.text)

    # Extract links (all <Link> attributes)
    links: List[Dict[str, str]] = []
    for elem in root.iter():
        if _strip_ns(elem.tag).lower() == "link":
            link_dict = {k: v for k, v in elem.attrib.items()}
            links.append(link_dict)

    result: Dict[str, object] = {}
    if subject:
        result["subject"] = subject
    if aliases:
        result["aliases"] = aliases
    if links:
        result["links"] = links

    return result or None
