                continue
            # Normalise common rels to keys
            if rel in ("hcard", "http://webfinger.net/rel/hcard", "http://purl.org/webfinger/rel/hcard"):
                result["hcard_url"] = href
            elif rel in ("public_key", "identity", "http://diasporaforge.org/rel/identity"):
                result["publickey_url"] = href
            else:
                result[rel] = href
        return result
    except Exception:
        # Fall through to XRD parsing
        pass

    # XRD (Atom or XML) parsing
    try:
        root = ElementTree.fromstring(document)
        # XRD may contain namespaces; ignore them by using wildcard
        for link in root.findall(".//{*}Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if not rel or not href:
                continue
            if rel.endswith("hcard") or "hcard" in rel.lower():
                result["hcard_url"] = href
            elif rel.endswith("public_key") or "public_key" in rel.lower() or "identity" in rel.lower():
                result["publickey_url"] = href
            else:
                result[rel] = href
        return result
    except Exception:
        # If parsing fails, return what we have (likely empty)
        return result<|return|>

