            links = data.get("links", [])
            for link in links:
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    # allow multiple links with same rel
                    if rel in result:
                        # store as list if duplicate
                        if isinstance(result[rel], list):
                            result[rel].append(href)
                        else:
                            result[rel] = [result[rel], href]
                    else:
                        result[rel] = href
