        root = ET.fromstring(doc)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        # Aliases
        aliases = []
        for alias in root.findall(".//xrd:Alias", ns):
            if alias.text:
                aliases.append(alias.text)
        if aliases:
            result["aliases"] = aliases
        # Links
        for link in root.findall(".//xrd:Link", ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel and href:
                for r in rel.split():
                    if r in result:
                        if isinstance(result[r], list):
                            result[r].append(href)
                        else:
                            result[r] = [result[r], href]
                    else:
                        result[r] = href
        # Graceful fallback if namespace not present
        if not result:
