    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        # Invalid handle format, return None indicating failure
        return None
    # Encode the handle for URL transmission
    try:
        encoded_handle = urllib.parse.quote(handle, safe='')
    except Exception:
        return None

    # Attempt HTTPS first, then fallback to HTTP
    for scheme in ("https", "http"):
        url = f"{scheme}://{host}/.well-known/webfinger?resource={encoded_handle}"
        try:
            with urllib.request.urlopen(url) as response:
                # Limit size to prevent overly large downloads
                data = response.read(100 * 1024)  # 100 KB max
                return data.decode('utf-8', errors='replace')
        except Exception:
            # If we can't retrieve via this scheme, try the next one
            continue
    # If all attempts fail, return None
    return None<|return|>

