def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers
    })
    # Determine the request method
    method_name = method.lower()
    try:
        request_func = getattr(requests, method_name)
    except AttributeError:
        raise ValueError(f"Unsupported HTTP method: {method}")
    try:
        response = request_func(url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except requests.RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError('The first argument must be a dictionary')
    if key is None:
        raise ValueError('The key cannot be None')
    keys_chain = list(keys)
    all_keys = [key] + keys_chain
    if not all_keys:
        raise ValueError('At least one key must be provided')
    current = dic
    for k in all_keys[:-1]:
        if k in current:
            if not isinstance(current[k], dict):
                raise ValueError(f"Cannot nest into non-dict at key '{k}'")
        else:
            current[k] = {}
        current = current[k]
    current[all_keys[-1]] = val
    return dic<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        import os
        # Normalize the directory list
        if isinstance(settings_dirs, str):
            directories = [settings_dirs]
        else:
            directories = list(settings_dirs)
        file_paths = []
        for directory in directories:
            if not directory or not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option is None or fname.endswith(spec_option):
                    file_paths.append(os.path.join(directory, fname))
        return sorted(file_paths)
    except Exception:
        return []<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os, fnmatch
    # Ensure settings_dirs is iterable
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs) if settings_dirs is not None else []

    file_paths = []
    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                full_path = os.path.join(directory, fname)
                if not os.path.isfile(full_path):
                    continue
                if spec_option is None:
                    file_paths.append(full_path)
                else:
                    # If spec_option is a glob pattern
                    if isinstance(spec_option, str):
                        if fnmatch.fnmatch(fname, spec_option):
                            file_paths.append(full_path)
                    # If spec_option is a compiled regex object
                    elif hasattr(spec_option, "search"):
                        try:
                            if spec_option.search(fname):
                                file_paths.append(full_path)
                        except Exception:
                            continue
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(file_paths)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Returns:
        List[str]: Sorted list of fully‑qualified file paths that match ``spec_option``.
    """
    # Normalize the directory input to a list
    if isinstance(settings_dirs, (str, os.PathLike)):
        dir_list = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dir_list = settings_dirs
    else:
        raise TypeError(
            f"settings_dirs must be a string, PathLike or a list/tuple of them, got {type(settings_dirs)!r}"
        )

    # Ensure spec_option is a string pattern (e.g., '*.ini')
    if not isinstance(spec_option, str):
        raise TypeError(
            f"spec_option must be a string pattern, got {type(spec_option)!r}"
        )

    collected = set()
    for directory in dir_list:
        try:
            # Convert to absolute path for consistency
            abs_dir = os.path.abspath(directory)
            for fname in os.listdir(abs_dir):
                if fnmatch.fnmatch(fname, spec_option):
                    collected.add(os.path.join(abs_dir, fname))
        except (OSError, FileNotFoundError) as exc:
            # Log the error and continue with next directory
            # If desired, replace with logging.warn(... ) in a real project
            continue

    return sorted(collected)<|return|>

