    """
    try:
        # Normalize to iterable of paths
        dirs = [settings_dirs] if isinstance(settings_dirs, (str, bytes)) else list(settings_dirs)
        result = []
        for d in dirs:
            try:
                for fname in os.listdir(d):
                    if spec_option:
                        if not fnmatch.fnmatch(fname, spec_option):
                            continue
                    result.append(os.path.join(d, fname))
            except OSError:
                # Skip directories that cannot be accessed
                continue
        return sorted(result)
    except Exception:
        # In case of unexpected failure, return an empty list
        return []<|return|>

