def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The method looks for a key named ``include`` in *parser_dict*.  The
    value may be a single path or a list of paths pointing to additional
    spec files that should be merged into the current dictionary.  Each
    included file is interpreted according to its extension (``.yaml``,
    ``.yml`` or ``.json``); if the extension is unrecognized the file
    is parsed as YAML by default.  The contents of the included file are
    merged into the caller dictionary recursively.  Keys in the caller
    take precedence over those that come from the included file.

    Parameters
    ----------
    parser_dict : dict
        A dictionary that potentially contains an ``include`` key.

    Returns
    -------
    dict
        The dictionary after all includes have been resolved and merged.

    Raises
    ------
    RuntimeError
        If an included file cannot be read or parsed, or if a cycle is
        detected in the include graph.
    """
    include_key = 'include'
    # If there is no include directive, nothing to do
    if include_key not in parser_dict:
        return parser_dict

    # We want to keep the original dict untouched unless merges are required
    result = dict(parser_dict)  # shallow copy
    include_value = result.pop(include_key)

    # Normalize to a list of includes
    if isinstance(include_value, (str, tuple)):
        includes = [include_value]
    else:
        includes = list(include_value)

    # A simple visited set to avoid infinite recursion
    visited = set()

    def _merge_from_path(path):
        """Load a file and merge its contents into *result*."""
        if path in visited:
            raise RuntimeError(f'Circular include detected: {path}')
        visited.add(path)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                if path.endswith(('.yaml', '.yml')):
                    import yaml
                    inc_dict = yaml.safe_load(f) or {}
                elif path.endswith('.json'):
                    import json
                    inc_dict = json.load(f) or {}
                else:
                    # Default to YAML for unknown extensions
                    import yaml
                    inc_dict = yaml.safe_load(f) or {}
        except Exception as e:
            raise RuntimeError(f'Error reading include file {path}: {e}') from e

        # Resolve any nested includes in the loaded dictionary
        nested = self._include_groups(inc_dict)

        # Merge, giving precedence to keys already present in *result*
        for k, v in nested.items():
            if k not in result:
                result[k] = v

    # If include_value is a mapping (dict or list of dicts) instead of file paths
    if isinstance(include_value, dict):
        nested = self._include_groups(include_value)
        for k, v in nested.items():
            if k not in result:
                result[k] = v
    else:
        for inc in includes:
            if isinstance(inc, str):
                _merge_from_path(inc)
            elif isinstance(inc, dict):
                nested = self._include_groups(inc)
                for k, v in nested.items():
                    if k not in result:
                        result[k] = v
            else:
                raise RuntimeError(f'Unsupported include type: {type(inc)}')

