def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Helper to resolve a single include entry.
    def _resolve_include(include_path):
        import os
        try:
            # Resolve relative to the directory of the current spec file if available.
            base_dir = getattr(self, 'spec_dir', os.getcwd())
            abs_path = os.path.abspath(os.path.join(base_dir, include_path))
            with open(abs_path, 'r', encoding='utf-8') as fh:
                content = fh.read()
            # Try JSON first, then YAML, finally plain python eval as a fallback.
            data = None
            try:
                import json
                data = json.loads(content)
            except Exception:
                try:
                    import yaml
                    data = yaml.safe_load(content)
                except Exception:
                    try:
                        data = eval(content, {}, {})
                    except Exception as exc:
                        raise ValueError(f"Unsupported file format for included spec '{include_path}': {exc}") from exc
            if not isinstance(data, dict):
                raise ValueError(f"Included spec '{include_path}' does not resolve to a dict.")
            return data
        except Exception as exc:
            raise RuntimeError(f"Failed to include spec file '{include_path}': {exc}") from exc

    # Main processing loop: handle all include directives until none remain.
    while True:
        include_key = None
        # Find an include entry; assume all include directives are under the key 'include'.
        for key, value in list(parser_dict.items()):
            if key == 'include':
                include_key = key
                include_value = value
                break
        if not include_key:
            break  # Nothing left to include

        # Remove the include directive from the dict so recursion doesn't reprocess it.
        parser_dict.pop(include_key)

        # The include value may be a string path or an iterable of paths.
        include_paths = [include_value] if isinstance(include_value, (str, bytes)) else list(include_value)

        for inc_path in include_paths:
            inc_data = _resolve_include(inc_path)
            # Merge new data into parser_dict; nested includes will be processed next iteration.
            parser_dict.update(inc_data)

    return parser_dict<|return|>

