    arg_spec = cmd_spec.get(argument_name)
    if arg_spec is None:
        raise KeyError(
            f"Argument '{argument_name}' is not defined for command '{command_name}'."
        )

    return arg_spec<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Attempt to retrieve the command-specific option dictionary.
    try:
        command_options = getattr(self, "_option_specs", {})
    except AttributeError:
        command_options = {}

    if not isinstance(command_options, dict):
        raise ValueError("Option specifications should be stored in a dictionary (_option_specs)")

    command_dict = command_options.get(command_name)
    if command_dict is None:
        raise KeyError(f"No option specifications found for command '{command_name}'")

    if not isinstance(command_dict, dict):
        raise ValueError(f"Specification for command '{command_name}' should be a dictionary")

    arg_spec = command_dict.get(argument_name)
    if arg_spec is None:
        raise KeyError(f"No specification for argument '{argument_name}' under command '{command_name}'")

    return arg_spec<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    try:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        silent_set = set()
        silent = []
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg.startswith("--"):
                name = arg[2:]
            elif arg.startswith("-") and len(arg) > 1:
                name = arg[1:]
            else:
                continue
            if name and name not in silent_set:
                silent_set.add(name)
                silent.append(name)
        return silent
    except Exception as e:
        raise ValueError(f"Error processing silent arguments: {e}")<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_options = {"-q", "--quiet", "-d", "--debug"}
    silent_args = []
    try:
        for arg in args:
            if arg in silent_options:
                silent_args.append(arg)
    except Exception:
        # If args is not iterable or any error occurs, return empty list
        return []
    return silent_args<|return|>

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Determine which arguments are required. Prefer a 'required' attribute, otherwise use 'args' attribute
    required = getattr(self, 'required', None)
    if required is None:
        required = getattr(self, 'args', None)
    if not required:
        return True  # Nothing to check

    if isinstance(args, dict):
        missing = [name for name in required if name not in args or args[name] is None]
    elif isinstance(args, (list, tuple)):
        missing = [required[i] for i, name in enumerate(required) if i >= len(args) or args[i] is None]
    else:
        raise TypeError("args must be a dict or a sequence")

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
    return True<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # The caller is expected to pass a mapping of argument names to values.
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Determine the set of arguments that this object requires.
    required = getattr(self, "required", None)
    if required is None:
        # If no explicit list of required arguments is defined, assume nothing is required.
        return
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("self.required must be a sequence of argument names")
    # Collect any required keys that are missing or have None values.
    missing = []
    for name in required:
        if name not in args or args[name] is None:
            missing.append(name)
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        name = opt.get('name')
        if not name:
            continue
        cond = opt.get('required_when')
        if cond is None:
            continue
        matched = False
        try:
            # Callable condition
            if callable(cond):
                matched = bool(cond(command_name, args))
            # Boolean literal
            elif isinstance(cond, bool):
                matched = cond
            # Tuple of (key, expected_value)
            elif isinstance(cond, tuple) and len(cond) == 2:
                key, expected = cond
                matched = args.get(key) == expected
            # Dict mapping keys to expected values
            elif isinstance(cond, dict):
                matched = all(args.get(k) == v for k, v in cond.items())
            # String key: require presence of that key (truthy)
            elif isinstance(cond, str):
                matched = args.get(cond) is not None
            # Iterable of keys: require any key present
            elif isinstance(cond, (list, set, tuple)):
                matched = any(args.get(k) is not None for k in cond)
            else:
                # Unsupported condition type: ignore
                matched = False
        except Exception:
            # In case of any error interpreting the condition, do not assert requirement
            matched = False
        if matched:
            required.append(name)
    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Ensure args is mapping-like – if not, try to convert to dict, otherwise treat as empty.
    try:
        args_dict = dict(args)
    except Exception:
        args_dict = {}

    required_when_args = []

    # Iterate through the options specification.  Each option is expected to be
    # a mapping with at least a 'name' key.  If the mapping holds a
    # ``required_when`` key the condition is evaluated (callable or string).
    for option in options_spec:
        if not isinstance(option, dict):
            # Skip invalid option specifications.
            continue
        opt_name = option.get("name")
        if not opt_name:
            # Options without names can be ignored for this purpose.
            continue

        cond = option.get("required_when")
        if cond is None:
            # No condition – nothing to do.
            continue

        # Helper to test a single condition.
        def cond_true(c):
            if callable(c):
                try:
                    return c(args_dict, command_name)
                except Exception:
                    return False
            if isinstance(c, str):
                # Evaluate string in a controlled namespace.
                try:
                    return bool(eval(c, {}, {"command_name": command_name, "args": args_dict}))
                except Exception:
                    return False
            # Unsupported condition type.
            return False

        # ``required_when`` may be a single condition, or an iterable of
        # conditions (any of which being True suffices).  Handle both cases
        # gracefully.
        if isinstance(cond, (list, tuple)):
            if any(cond_true(sub) for sub in cond):
                required_when_args.append(opt_name)
        else:
            if cond_true(cond):
                required_when_args.append(opt_name)

    return required_when_args<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for option in options_spec:
            cond = option.get('required_when')
            if cond is None:
                continue
            name = option.get('name')
            if name is None:
                continue
            matched = False
            # If the condition is a callable, use it directly
            if callable(cond):
                try:
                    matched = bool(cond(command_name, args))
                except Exception:
                    # Treat any exception as a failure to match
                    matched = False
            else:
                # Treat the condition as a string expression
                try:
                    # Provide a minimal, safe evaluation environment
                    matched = bool(eval(cond, {}, {'command_name': command_name, 'args': args}))
                except Exception:
                    # Any error means the condition does not match
                    matched = False
            if matched:
                required.append(name)
        return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """

    # Prepare a list to collect matching argument names
    required_when_names = []

    # Normalise command name to a string
    if not isinstance(command_name, str):
        try:
            command_name = str(command_name)
        except Exception:
            command_name = ""

    # Normalise args to a dict; if it is iterable of pairs, convert; otherwise use empty dict
    try:
        args_dict = dict(args)
    except Exception:
        args_dict = {}

    # Iterate over the option specifications
    try:
        iterable_options = iter(options_spec)
    except Exception:
        iterable_options = []

    for spec in iterable_options:
        # Each spec is expected to be a mapping/dictionary
        if not isinstance(spec, dict):
            continue

        # Retrieve the option name; fall back to various common keys
        opt_name = spec.get("name")
        if opt_name is None:
            opt_name = spec.get("arg")
        if opt_name is None:
            opt_name = spec.get("alias")
        if opt_name is None:
            # Can't proceed without a name
            continue

        # Get the condition definition
        condition = spec.get("required_when")
        if condition is None:
            continue

        # Determine if the condition is met
        condition_met = False
        try:
            if callable(condition):
                # Call the condition with command_name and args_dict
                condition_met = bool(condition(command_name, args_dict))
            elif isinstance(condition, bool):
                # Direct boolean value
                condition_met = condition
            elif isinstance(condition, (list, tuple)):
                # Interpret as a list of (option, expected_value) pairs
                condition_met = all(
                    args_dict.get(opt) == expected for opt, expected in condition
                )
            elif isinstance(condition, dict):
                # Interpret as a mapping of option names to expected values
                condition_met = all(
                    args_dict.get(k) == v for k, v in condition.items()
                )
            else:
                # Unsupported type, treat as not met
                condition_met = False
        except Exception:
            # If the evaluation raises, default to not met
            condition_met = False

        if condition_met:
            required_when_names.append(opt_name)

    return required_when_names<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict (got {type(args).__name__})")

    # Ensure required keys are present
    for key in ("value", "length"):
        if key not in args:
            raise KeyError(f"args missing required key '{key}'")

    value = args["value"]
    max_len = args["length"]

    if not isinstance(max_len, int):
        raise TypeError(f"length must be an integer (got {type(max_len).__name__})")
    if max_len < 0:
        raise ValueError(f"length must be non-negative (got {max_len})")

    try:
        actual_len = len(value)
    except TypeError:
        raise TypeError(f"value of type {type(value).__name__} has no length")

    if actual_len > max_len:
        raise ValueError(
            f"value length {actual_len} exceeds maximum allowed length {max_len}"
        )
    # No return value needed; validation passed classic by no exception.<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument specifications")

    for arg_name, spec in args.items():
        if not isinstance(spec, dict):
            continue  # skip non-dict specs

        # Retrieve the value passed for this argument
        if 'value' not in spec:
            continue  # nothing to validate if no value is supplied
        value = spec['value']

        # Determine any maximum length constraint (supported keys)
        max_len = spec.get('max_length')
        if max_len is None:
            max_len = spec.get('maxlength')
        if max_len is None:
            max_len = spec.get('length')

        if max_len is None:
            continue  # no length constraint for this argument

        if not isinstance(max_len, int):
            raise TypeError(
                f"Maximum length for argument '{arg_name}' must be an integer, got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"Maximum length for argument '{arg_name}' must be non-negative, got {max_len}"
            )

        # Only sequences (strings, bytes, list, tuple, dict, set) can have length
        if isinstance(value, (str, bytes, list, tuple, dict, set)):
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' exceeds maximum allowed length of {max_len} (actual: {len(value)})"
                )
        else:
            # If value is not a sequence we cannot measured its length;
            # we treat this as a potential misuse but do not raise an error,
            # unless the specification explicitly requires a sequence.
            continue
<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure `args` is a dict or a list of dicts (each with a single key)
    if not isinstance(args, (dict, list)):
        raise TypeError(f"args must be dict or list, got {type(args).__name__}")

    # Build an iterable of (arg_name, arg_attrs) tuples
    if isinstance(args, dict):
        arg_iter = args.items()
    else:
        # Assuming each list item is a dict with a single key
        arg_iter = []
        for d in args:
            if not isinstance(d, dict):
                raise TypeError(f"List item must be dict, got {type(d).__name__}")
            if len(d) != 1:
                raise ValueError(f"List item dict must have a single key, got {len(d)} keys")
            arg_iter.append(list(d.items())[0])

    for arg_name, arg_attrs in arg_iter:
        # Normalise value and attributes
        if isinstance(arg_attrs, dict) and "value" in arg_attrs:
            value = arg_attrs["value"]
            attrs = arg_attrs
        else:
            value = arg_attrs
            attrs = {}

        # Skip missing or None values
        if value is None:
            continue

        # Get expected maximum length if defined
        max_len = attrs.get("max_length") or attrs.get("length")
        if max_len is None:
            continue  # nothing to validate

        if not isinstance(max_len, int):
            raise TypeError(
                f"Maximum length for argument '{arg_name}' must be an integer, "
                f"got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"Maximum length for argument '{arg_name}' must be non‑negative, "
                f"got {max_len}"
            )

        # Attempt to obtain the length of the provided value
        try:
            val_len = len(value)
        except Exception:
            # Value is not a lengthable object; we skip validation for it
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds the "
                f"maximum allowed {max_len}"
            )<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the argument specification from the parsed YAML.
    spec = self.parsed_yaml.get('args', {})
    if not isinstance(spec, (dict, list)):
        return

    # Build a mapping of argument names to their maximum allowed length.
    max_lengths = {}
    if isinstance(spec, dict):
        for argname, attrs in spec.items():
            if isinstance(attrs, dict):
                for key in ('length', 'max_length'):
                    if key in attrs:
                        max_lengths[argname] = attrs[key]
                        break
    else:  # list of dicts
        for item in spec:
            if not isinstance(item, dict):
                continue
            for argname, attrs in item.items():
                if isinstance(attrs, dict):
                    for key in ('length', 'max_length'):
                        if key in attrs:
                            max_lengths[argname] = attrs[key]
                            break

    # Iterate over the provided arguments and validate their lengths.
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = args
    else:
        raise TypeError("args must be a dict or a list/tuple of (name, value)")

    for name, value in items:
        if name not in max_lengths:
            continue
        limit = max_lengths[name]
        if limit is None:
            continue
        try:
            value_len = len(value)
        except Exception as exc:
            raise TypeError(f"Argument '{name}' has no length() method") from exc
        if value_len > limit:
            raise ValueError(
                f"Argument '{name}' exceeds maximum length {limit} (actual: {value_len})"
            )
<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Build a mapping of argument names to their maximum allowed length.
    spec = self.parsed_yaml.get('args', {})
    max_lengths = {}
    if isinstance(spec, dict):
        for name, attrs in spec.items():
            max_lengths[name] = attrs.get('length')
    elif isinstance(spec, list):
        for item in spec:
            if isinstance(item, dict) and len(item) == 1:
                name, attrs = next(iter(item.items()))
                max_lengths[name] = attrs.get('length')

    for name, value in args.items():
        # Skip if no length constraint is defined for this argument.
        max_len = max_lengths.get(name)
        if max_len is None:
            continue

        # Validate the declared maximum length itself.
        if not isinstance(max_len, int):
            raise TypeError(
                f"Maximum length for argument '{name}' must be an integer, got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"Maximum length for argument '{name}' must be non‑negative, got {max_len}"
            )

        # Skip validation if the value is None (missing or optional).
        if value is None:
            continue

        # Ensure the value has a length; otherwise, raise an error.
        try:
            current_len = len(value)
        except Exception:
            raise TypeError(
                f"Argument '{name}' has no length (value: {value!r})"
            )

        if current_len > max_len:
            raise ValueError(
                f"Argument '{name}' length {current_len} exceeds the maximum allowed {max_len}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.

    Raises:
        TypeError: If ``args`` is not a mapping.
        ValueError: If a supplied argument value is not within its allowed
        choices.
    """
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args)!r}")

    arg_definitions = self.parsed_yaml.get("args", {})
    for arg_name, value in args.items():
        definition = arg_definitions.get(arg_name)
        if not definition or not isinstance(definition, dict):
            continue  # skip arguments that are not defined or not dicts

        if "choices" not in definition:
            continue  # nothing to validate for this arg

        # Normalize the allowed choices to a list
        allowed = definition["choices"]
        if isinstance(allowed, str):
            # allow comma‑separated string
            allowed = [c.strip() for c in allowed.split(",")]
        if not isinstance(allowed, (list, tuple, set)):
            allowed = [allowed]

        # If the supplied value is a list/tuple/set (and not a string), check each element
        if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid choice for argument `{arg_name}`: {v}. "
                        f"Allowed choices are: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument `{arg_name}`: {value}. "
                    f"Allowed choices are: {allowed}"
                )<|return|>

def validate_choices_args(self, args):
