    def _check_value(name, value, choices):
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {v!r}. "
                        f"Expected one of {choices!r}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Expected one of {choices!r}"
                )

    try:
        if not args:
            return
        arg_defs = self.parsed_yaml.get('args', {})
        if isinstance(args, list):
            for item in args:
                if not isinstance(item, dict):
                    continue
                for name, value in item.items():
                    attrs = arg_defs.get(name)
                    if attrs and 'choices' in attrs:
                        _check_value(name, value, attrs['choices'])
        elif isinstance(args, dict):
            for name, value in args.items():
                attrs = arg_defs.get(name)
                if attrs and 'choices' in attrs:
                    _check_value(name, value, attrs['choices'])
    except Exception as exc:
        raise ValueError(f"Error validating choice arguments: {exc}") from exc<|return|>

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Ensure args is a dictionary; raise an error otherwise.
        if not isinstance(args, dict):
            raise TypeError("`args` must be a dictionary, got %r" % type(args).__name__)
        # If the instance has no choice definitions, nothing to validate.
        if not getattr(self, "choices", None):
            return
        # For each argument that has a choice definition, verify the supplied value is allowed.
        for arg_name, value in args.items():
            if arg_name in self.choices:
                allowed = self.choices[arg_name]
                if value not in allowed:
                    allowed_str = ", ".join(repr(v) for v in allowed)
