def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values.")

    # Retrieve mapping of argument names to their allowed choices.
    # It is expected that the class defines an attribute `valid_choices`
    # as a dict: {arg_name: [choice1, choice2, ...]}.
    valid_choices = getattr(self, "valid_choices", {})
    if not isinstance(valid_choices, dict):
        raise TypeError("valid_choices must be a dictionary of allowed choices.")

    for arg_name, allowed in valid_choices.items():
        if arg_name not in args:
            # Argument not supplied; skip validation.
            continue

        value = args[arg_name]

        # Allow allowed to be an iterable of choices (list, tuple, set).
        # If allowed is a callable, treat it as a predicate that returns True for a valid value.
        if isinstance(allowed, (list, tuple, set)):
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Allowed values are: {allowed!r}."
                )
        elif callable(allowed):
            try:
                if not allowed(value):
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {value!r}. "
                        f"Validation predicate returned False."
                    )
            except Exception as exc:
                raise ValueError(
                    f"Error validating argument '{arg_name}' with value {value!r}: {exc}"
                )
        else:
            raise TypeError(
                f"Allowed choices for argument '{arg_name}' must be an iterable or a callable, "
                f"got {type(allowed).__name__}."
            )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    Supports two common patterns for ``args``:

    * a mapping with keys ``'min'``, ``'max'`` and optionally ``'value'``.
    * an iterable ``(value, min, max)``.

    Raises a :class:`ValueError` if the constraints are violated or a
    :class:`TypeError` when the argument structure is unsupported.
    """
    # Handle ``None`` or empty input gracefully
    if not args:
        return

    # Pattern 1: mapping with explicit ``min``/``max``/``value`` keys.
    if isinstance(args, dict):
        min_val = args.get("min")
        max_val = args.get("max")
        value = args.get("value")

        # If both bounds are present, check that they are valid
        if min_val is not None and max_val is not None:
            if min_val > max_val:
                raise ValueError(
                    f"Minimum value {min_val} cannot be greater than maximum value {max_val}"
                )

        # If a value is provided, validate it against the bounds
        if value is not None:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Value {value} is less than minimum {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Value {value} is greater than maximum {max_val}"
                )
        return

    # Pattern 2: iterable containing ``(value, min, max)``.
    if isinstance(args, (list, tuple)):
        try:
            value, min_val, max_val = args
        except Exception as exc:
            raise TypeError(
                "Iterable ``args`` must contain exactly three elements: "
                "(value, min, max)"
            ) from exc

        if min_val is not None and max_val is not None and min_val > max_val:
            raise ValueError(
                f"Minimum value {min_val} cannot be greater than maximum {max_val}"
            )
        if value < min_val or value > max_val:
            raise ValueError(
                f"Value {value} not between {min_val} and {max_val}"
            )
        return

    # Unsupported structure
    raise TypeError(
        "Arguments must be a mapping with 'min', 'max', 'value' keys "
        "or an iterable of the form (value, min, max)"
    )
<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # args must be an iterable
    if args is None:
        raise TypeError("args cannot be None")
    if not hasattr(args, '__iter__'):
        raise TypeError("args must be an iterable of argument specifications")

    for idx, arg in enumerate(args):
        # Support dict or object with value, min, max attributes
        if isinstance(arg, dict):
            value = arg.get('value')
            min_val = arg.get('min')
            max_val = arg.get('max')
            name = arg.get('name', f"arg[{idx}]")
        else:
            # Try attribute access
            try:
                value = getattr(arg, 'value')
                min_val = getattr(arg, 'min')
                max_val = getattr(arg, 'max')
                name = getattr(arg, 'name', f"arg[{idx}]")
            except AttributeError:
                raise ValueError(
                    f"Argument {idx} is neither a dict nor has required attributes 'value', 'min', 'max'"
                )

        # verify that the three required components are present
        if value is None or min_val is None or max_val is None:
            raise ValueError(
                f"Argument {name} is missing a value, min, or max key/attribute"
            )

        # perform comparison; handle type errors
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument {name} value {value} not within allowed range "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument {name} contains non-comparable types "
                f"(value: {type(value)}, min: {type(min_val)}, max: {type(max_val)})"
            )

    # All arguments validated
    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values."""
    # Expects args to contain exactly two values: (min_value, max_value)
    try:
        min_val, max_val = args
    except Exception:
        raise ValueError("Two positional arguments required: min and max")
    # Ensure both values are numeric (int or float)
    if not all(isinstance(v, (int, float)) for v in (min_val, max_val)):
        raise TypeError("Both minimum and maximum must be numeric")
    # Ensure min is not greater than max
    if min_val > max_val:
        raise ValueError(f"Minimum value {min_val} cannot be greater than maximum {max_val}")
    # All checks passed
    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    Each element of *args* must specify the value together with a
    minimum and a maximum.  The element can be either:

    * A 3‑tuple ``(value, min_, max_)``    or
    * A mapping ``{'value': value, 'min': min_, 'max': max_}``

    Raises
    ------
    TypeError
        If *args* is not iterable, if an element has an unsupported
        structure or if the numeric values are of the wrong type.
    ValueError
        If *min_* is greater than *max_*, or if the value is outside
        the allowed range.

    Returns
    -------
    bool
        ``True`` if all arguments passed validation.
    """
    # Ensure we have an iterable of arguments
    try:
        iterator = iter(args)
    except TypeError as exc:
        raise TypeError("`args` must be an iterable") from exc

    for index, item in enumerate(iterator):
        # Extract value, min_, max_
        try:
            if isinstance(item, dict):
                value = item["value"]
                min_ = item["min"]
                max_ = item["max"]
            else:
                value, min_, max_ = item
        except Exception as exc:
            raise ValueError(
                f"Argument #{index + 1} must be a dict with keys 'value','min','max' "
                "or a 3‑tuple (value, min_, max_)"
            ) from exc

        # Validate numeric types
        if not isinstance(value, (int, float)):
            raise TypeError(
                f"Value at argument #{index + 1} must be numeric, got {type(value).__name__}"
            )
        if not isinstance(min_, (int, float)):
            raise TypeError(
                f"Minimum at argument #{index + 1} must be numeric, got {type(min_).__name__}"
            )
        if not isinstance(max_, (int, float)):
            raise TypeError(
                f"Maximum at argument #{index + 1} must be numeric, got {type(max_).__name__}"
            )

        # Logical consistency of min/max
        if min_ > max_:
            raise ValueError(
                f"Minimum ({min_}) is greater than maximum ({max_}) at argument #{index + 1}"
            )

        # Range check
        if not (min_ <= value <= max_):
            raise ValueError(
                f"Value {value} out of range [{min_}, {max_}] at argument #{index + 1}"
            )

    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises ValueError: If args is not iterable, or min/max not defined,
        or any value is outside the defined range.
    :raises TypeError: If an argument cannot be compared with the min/max.
    """
    # Resolve the minimum and maximum limits from the instance.
    min_val = getattr(self, "min", None) or getattr(self, "minimum", None)
    max_val = getattr(self, "max", None) or getattr(self, "maximum", None)

    # Basic validation of limits.
    if min_val is None or max_val is None:
        raise ValueError("Both minimum and maximum limits must be defined on the instance.")
    if min_val > max_val:
        raise ValueError(f"Maximum limit ({max_val}) must be greater than or equal to minimum limit ({min_val}).")

    # Ensure args is an iterable.
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable, got {!r}".format(args))

    # Check each value against the limits.
    for idx, value in enumerate(iterator):
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument at position {idx} ({value!r}) is outside the allowed range "
                    f"({min_val!r} <= value <= {max_val!r})."
                )
        except TypeError as exc:
            raise TypeError(
                f"Argument at position {idx} ({value!r}) could not be compared "
                f"to the limits ({min_val!r}, {max_val!r}): {exc}"
            ) from exc

    # If all values are within range, return the original args.
    return args
<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of spec_option
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    required = spec_option.get("required", False)
    choices = spec_option.get("choices")
    converter = spec_option.get("converter")
    validator = spec_option.get("validator")

    def _complex_type(value):
        """
        Convert and validate the raw value according to spec_option.
        """
        # Required check
        if required and (value is None or value == ""):
            raise ValueError(
                f"Option '{option_name}' is required for subcommand '{subcommand}'."
            )

        # Choices check
        if choices is not None and value not in choices:
            raise ValueError(
                f"Option '{option_name}' for subcommand '{subcommand}' must be one of {choices}."
            )

        # Converter
        if converter is not None:
            if not callable(converter):
                raise TypeError(f"Converter for '{option_name}' must be callable.")
            try:
                value = converter(value)
            except Exception as exc:
                raise ValueError(
                    f"Error converting value for option '{option_name}': {exc}"
                ) from exc

        # Validator
        if validator is not None:
            if not callable(validator):
                raise TypeError(f"Validator for '{option_name}' must be callable.")
            try:
                if not validator(value):
                    raise ValueError(
                        f"Validation failed for option '{option_name}' on subcommand '{subcommand}'."
                    )
            except Exception as exc:
                raise ValueError(
                    f"Validation error for option '{option_name}': {exc}"
                ) from exc

        return value

    # Attach metadata for debugging / introspection
    _complex_type.__name__ = type_name
    _complex_type.__doc__ = (
        f"{type_name} type for subcommand '{subcommand}' option '{option_name}'."
    )
    return _complex_type<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Resolve the target type, allowing a string name that refers to an attribute
    # of the current instance or a global symbol.
    if isinstance(type_name, str):
        try:
            target_type = getattr(self, type_name)
        except AttributeError:
            try:
                target_type = globals()[type_name]
            except KeyError:
                raise TypeError(
                    f"Complex type '{type_name}' could not be found for option '{option_name}'."
                )
    else:
        target_type = type_name

    # Prepare constructor arguments.  The spec_option may contain a mapping
    # with `__type__`, `__args__`, and `__kwargs__` or just the keyword
    # arguments directly.
    args = ()
    kwargs = {}
    if isinstance(spec_option, dict):
        # Pull out special keys if present
        args = tuple(spec_option.pop("__args__", ()))
        # Load a nested type if specified
        if "__type__" in spec_option:
            nested_type_name = spec_option.pop("__type__")
            try:
                nested_type = getattr(self, nested_type_name)
            except AttributeError:
                try:
                    nested_type = globals()[nested_type_name]
                except KeyError:
                    raise TypeError(
                        f"Nested type '{nested_type_name}' could not be found for option '{option_name}'."
                    )
            # Use nested type for the keyword argument named after the original key
            # if it exists in kwargs.
        kwargs = spec_option
    else:
        # If not a dict, treat it as positional arguments
        args = tuple(spec_option)

    # Attempt to instantiate the target type and handle any errors gracefully.
    try:
        return target_type(*args, **kwargs)
    except Exception as exc:
        msg = (
            f"Failed to create complex argument '{option_name}' for subcommand "
            f"'{subcommand}' using type '{type_name}'."
        )
        raise RuntimeError(msg) from exc<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Ensure spec_option is a dictionary
    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Resolve the factory/callable that will create the complex type instance
    factory = None
    # First try to get it as an attribute of this instance
    try:
        factory = getattr(self, type_name)
    except AttributeError:
        pass

    # If not found, try to import it by dotted notation
    if factory is None:
        try:
            import importlib
            module_name, _, cls_name = type_name.rpartition('.')
            if module_name:
                module = importlib.import_module(module_name)
                factory = getattr(module, cls_name)
            else:
                # Look up in builtins or raise error
                factory = getattr(__import__('builtins'), cls_name)
        except Exception as exc:
            raise ImportError(f"Unable to load complex type '{type_name}': {exc}") from exc

    if not callable(factory):
        raise TypeError(f"The resolved factory for '{type_name}' is not callable")

    # Construct the complex argument type instance
    try:
        instance = factory(subcommand=subcommand, option_name=option_name, **spec_option)
    except Exception as exc:
        raise TypeError(f"Error constructing instance of '{type_name}': {exc}") from exc

    return instance<|return|>

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalise input to a dictionary
    if args is None:
        return {}, {}
    if isinstance(args, dict):
        arg_dict = args
    elif isinstance(args, (list, tuple)):
        # Convert list of tuples or objects with 'name' and 'value' attributes
        arg_dict = {}
        for item in args:
            if isinstance(item, dict):
                arg_dict.update(item)
            elif isinstance(item, tuple) and len(item) == 2:
                arg_dict[item[0]] = item[1]
            elif hasattr(item, 'name') and hasattr(item, 'value'):
                arg_dict[item.name] = item.value
            else:
                raise ValueError("Unsupported argument format in list/tuple")
    else:
        raise TypeError("args must be a dict, list, or tuple of key/value pairs")

    control_args = {}
    nested_args = {}

    # Define a minimal set of known control argument keys. This list can be
    # expanded as needed by the calling code.
    known_control_keys = {
        "_destroy",
        "_verbose",
        "_debug",
        "_config",
        "destroy",
        "verify",
        "ssh_user",
        "ssh_port",
        "dry_run",
        "noop",
        "profile",
        "profile_action",
        "version",
        "help",
    }

    for key, value in arg_dict.items():
        # Skip keys that are explicitly marked as control arguments
        if key in known_control_keys or key.startswith("_"):
            control_args[key] = value
        # Custom arguments are identified by a "custom." prefix.
        elif isinstance(key, str) and key.startswith("custom."):
            custom_key = key.split(".", 1)[1]
            nested_args[custom_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args
<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Initialise containers
    control_args = {}
    nested_args = {}

    # Accept a mapping, an iterable of 2‑tuples, or a list/tuple of pairs
    iterable = None
    if isinstance(args, dict):
        iterable = args.items()
    elif hasattr(args, "__iter__"):
        # Try to get pairs; if item is a tuple/list of length 2, use it directly
        try:
            # For standard argparse.Namespace, convert to dict
            if hasattr(args, "__dict__"):
                iterable = args.__dict__.items()
            else:
                # items that are tuples of two elements
                for item in args:
                    if not (isinstance(item, (tuple, list)) and len(item) == 2):
                        raise ValueError("Unsupported arg format")
                iterable = args
        except Exception:
            raise ValueError("Unsupported args format")
    else:
        raise ValueError("`args` must be a mapping or iterable of pairs")

    for key, value in iterable:
        # Ensure key is a string
        if not isinstance(key, str):
            continue

        # Control arguments start with 'control_' prefix
        if key.startswith("control_"):
            control_args[key[8:]] = value
            continue

        # Custom arguments start with 'custom_' prefix
        if key.startswith("custom_"):
            nested_key = key[7:]  # strip 'custom_'
            nested_args[nested_key] = value
            continue

        # Default nested arguments
        nested_args[key] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalize input: accept a dict or a list of (key, value) tuples
    if args is None:
        args = {}
    elif isinstance(args, list):
        try:
            args = dict(args)
        except Exception:
            raise TypeError("args list must contain two-element tuples")
    elif not isinstance(args, dict):
        raise TypeError("args must be a dict, list of tuples, or None")

    control_args = {}
    nested_args = {}

    CONTROL_PREFIX = "control_"
    CUSTOM_PREFIX = "custom_"

    for key, value in args.items():
        if key is None:
            continue  # skip invalid keys
        if isinstance(key, str) and key.startswith(CONTROL_PREFIX):
            # Remove the prefix when storing, but keep original key
            # as spec may use the prefixed name
            control_args[key] = value
        elif isinstance(key, str) and key.startswith(CUSTOM_PREFIX):
            # Treat custom args as nested vars but strip the prefix
            nested_key = key[len(CUSTOM_PREFIX):]
            nested_args[nested_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary, got %s" % type(vars_dict).__name__)
    merged = dict(vars_dict)

    if not extra_vars:
        return merged

    if isinstance(extra_vars, dict):
        merged.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                merged.update(item)
            elif isinstance(item, str):
                if '=' not in item:
                    raise ValueError(f"Cannot parse extra var from string '{item}'. Expected format key=value")
                key, value = item.split('=', 1)
                merged[key.strip()] = value.strip()
            else:
                raise TypeError(f"Unsupported type in extra_vars list: {type(item).__name__}")
    else:
        raise TypeError("extra_vars must be a dict or list, got %s" % type(extra_vars).__name__)

    return merged<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Validate input dictionary
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # No extra variables to merge
    if extra_vars is None:
        return vars_dict

    # Convert extra_vars into a mapping
    if isinstance(extra_vars, dict):
        mapping = extra_vars
    elif isinstance(extra_vars, (list, tuple)):
        try:
            mapping = dict(extra_vars)
        except Exception as exc:
            raise ValueError("extra_vars must be a mapping or a list/tuple of key-value pairs") from exc
    else:
        raise TypeError(f"extra_vars must be a dict, list or tuple, got {type(extra_vars).__name__}")

    # Merge, overriding existing keys
    try:
        vars_dict.update(mapping)
    except Exception as exc:
        raise ValueError(f"Failed to merge dictionaries: {exc}") from exc

    return vars_dict<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Initialize vars_dict if None
    if vars_dict is None:
        vars_dict = {}
    # Return immediately if no extra_vars provided
    if not extra_vars:
        return vars_dict

    # Ensure vars_dict is a dictionary; raise informative error if not
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Handle the case where a single dictionary is provided instead of a list
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    # Must be an iterable of dictionaries
    elif not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a dict or a list/tuple of dicts")

    # Merge each dictionary into vars_dict (overriding existing keys)
    for extra in extra_vars:
        if not isinstance(extra, dict):
            raise TypeError("Each item in extra_vars must be a dictionary")
        vars_dict.update(extra)

    return vars_dict<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            raise ValueError("vars_dict must be a dict")
        if not isinstance(vars_dict, dict):
            try:
                vars_dict = dict(vars_dict)
            except Exception as exc:
                raise ValueError("vars_dict cannot be converted to dict") from exc

        if not extra_vars:
            return vars_dict

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple of dictionaries")

        for item in extra_vars:
            if not isinstance(item, dict):
                raise TypeError("each item in extra_vars must be a dict")
            try:
                vars_dict.update(item)
            except Exception as exc:
                raise ValueError(f"Failed to merge item {item}") from exc

        return vars_dict<|return|>

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")

    command = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0 or verbose > 5:
                raise ValueError("verbose must be between 0 and 5")
            command.append('-' + 'v' * verbose)
        elif isinstance(verbose, str):
            command.append(verbose)
        else:
            raise TypeError("verbose must be an int or str")

    # Add additional ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
                # If value is False we skip the flag
            else:
                command.append(f"--{key}={value}")

    # Add extra-vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        import json
        vars_str = json.dumps(extra_vars)
        command.extend(["--extra-vars", vars_str])

    # Debug log
    if logger.isEnabledFor(logging.DEBUG):
        logger.debug("Executing ansible-playbook: %s", " ".join(command))

    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except OSError as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook failed with return code {result.returncode}:\n"
            f"{result.stderr}"
        )

    return result.stdout<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Try to obtain the parser definition from the instance.  The
    # definition is expected to be a collection (list/dict) of option
    # descriptors that provide a ``name`` attribute and a ``convert``
    # callable.
    parser_def = getattr(self, "parsers", {}).get(parser_name)

    # If we have a definition, use it to convert the values.
    if parser_def is not None:
        # The definition may be a list of option objects, or a dict
        # mapping option names to option objects.
        if hasattr(parser_def, "items"):
            iterator = parser_def.items()
        else:
            iterator = parser_def

        for opt_name, opt in iterator:
            # Skip if the option doesn't have the required attributes
            if not hasattr(opt, "convert") or not callable(opt.convert):
                continue

            if opt_name in values_dict:
                try:
                    values_dict[opt_name] = opt.convert(values_dict[opt_name])
                except Exception as exc:
                    raise ValueError(
                        f"Error converting option '{opt_name}' to its "
                        f"expected type: {exc}"
                    ) from exc

        return

    # Fallback: if the instance contains an ArgumentParser instance
    # for this command, use its actions for conversion.
    try:
        import argparse
    except Exception:
        return  # argparse not available, cannot convert

    # We look for an attribute named "<parser_name>_parser"
    parser_attr = f"{parser_name}_parser"
    parser_obj = getattr(self, parser_attr, None)
    if (
        parser_obj
        and isinstance(parser_obj, argparse.ArgumentParser)
        and isinstance(parser_obj._actions, list)
    ):
        for action in parser_obj._actions:
            # Skip actions that don't represent a real option
            if action.dest is argparse.SUPPRESS or action.dest not in values_dict:
                continue

            # Use the action's type (if defined) for conversion, else
            # leave the value unchanged.
            try:
                conv = action.type
                if conv is not None:
                    values_dict[action.dest] = conv(values_dict[action.dest])
            except Exception:
                # If conversion fails, leave the value unchanged
                pass
    # If no known parser definition is found, the values remain as strings.<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    # Retrieve the expected type mapping for the given parser.
    # Subclasses may provide a ``parser_types`` dict mapping parser name
    # to a dict of argument names and expected Python types.
    # Example: {'main': {'timeout': int, 'debug': bool}}
    parser_types = getattr(self, "parser_types", {}).get(parser_name, {})
    for key, val in values_dict.items():
        expected_type = parser_types.get(key)
        if expected_type is None:
            # No explicit type information – leave the string as is.
            continue
        try:
            if expected_type is bool:
                if isinstance(val, str):
                    values_dict[key] = val.lower() in ("true", "1", "yes", "on")
                else:
                    values_dict[key] = bool(val)
            elif expected_type is int:
                values_dict[key] = int(val)
            elif expected_type is float:
                values_dict[key] = float(val)
            elif expected_type is list:
                if isinstance(val, str):
                    # Split on commas, remove surrounding whitespace
                    values_dict[key] = [item.strip() for item in val.split(",") if item.strip()]
                elif isinstance(val, (list, tuple)):
                    values_dict[key] = list(val)
                else:
                    values_dict[key] = [val]
            elif expected_type is dict:
                import json
                if isinstance(val, str):
                    values_dict[key] = json.loads(val)
                elif isinstance(val, dict):
                    values_dict[key] = dict(val)
                else:
                    raise ValueError(f"Cannot cast {val!r} to dict")
            else:
                # For any other explicitly expected type, try to cast directly.
                values_dict[key] = expected_type(val)
        except Exception as exc:
            raise ValueError(
                f"Error converting argument '{key}' (value={val!r}) to {expected_type.__name__} "
                f"for parser '{parser_name}': {exc}"
            ) from exc
    # No return value; the dictionary is modified in place.<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

