        result = values_dict.copy()
        # Retrieve parser's option definitions if available
        parser_options = getattr(self, "parsers", {}).get(parser_name, {})
        for key, val in values_dict.items():
            opt_def = parser_options.get(key)
            try:
                # If the option has a custom convert method use it
                if opt_def and hasattr(opt_def, "convert"):
                    result[key] = opt_def.convert(val)
                    continue
                # Only try to cast strings
                if not isinstance(val, str):
                    continue
                lowered = val.strip().lower()
                # Boolean conversion
                if lowered in ("true", "1", "yes", "y"):
                    result[key] = True
                elif lowered in ("false", "0", "no", "n"):
                    result[key] = False
                else:
                    # Numeric conversion
                    try:
                        result[key] = int(val)
                    except ValueError:
                        try:
                            result[key] = float(val)
                        except ValueError:
                            # List conversion by comma
                            if "," in val:
                                result[key] = [v.strip() for v in val.split(",")]
                            else:
                                # leave as string
                                result[key] = val
            except Exception:
                # Preserve the original value if conversion fails
                result[key] = val
        return result<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    All input values are assumed to be strings unless the parser definition
    specifies otherwise.  Conversions are performed based on the option
    type information stored in ``self._parsers[parser_name]``.  Supported
    types include ``int``, ``float``, ``bool`` and any callable that
    accepts a single string argument.

    :param parser_name: The command name, e.g. ``main``, ``virsh``, ``ospd``.
    :param values_dict: A dictionary of option names to string values.
    :returns: The modified ``values_dict`` with converted values.
    """
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Retrieve option type mapping for the specified parser.  If the parser
    # is unknown, leave the values untouched.
    parser_options = getattr(self, "_parsers", {}).get(parser_name, {})

    for key, raw_value in list(values_dict.items()):
        expected_type = parser_options.get(key)
        if expected_type is None:
            continue  # No conversion information; leave as-is

        try:
            if expected_type is bool:
                # Accept common textual and numeric representations of booleans.
                if isinstance(raw_value, str):
                    lowered = raw_value.lower()
                    if lowered in ("true", "1", "yes", "y"):
                        cast_value = True
                    elif lowered in ("false", "0", "no", "n"):
                        cast_value = False
                    else:
                        raise ValueError(
                            f"invalid boolean value '{raw_value}' for option '{key}'")
                else:
                    cast_value = bool(raw_value)
            else:
                # For other types, simply call the type constructor.
                cast_value = expected_type(raw_value)
        except Exception as exc:
            raise ValueError(
                f"Failed to convert option '{key}' to {expected_type}: {exc}"
            ) from exc

        values_dict[key] = cast_value

    return values_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")
    # Retrieve the option definitions for the given parser
    parser_options = getattr(self, "parsers", {}).get(parser_name)
    if parser_options is None:
        raise ValueError(f"No parser options found for '{parser_name}'")
    # Iterate over all provided values and attempt to cast them
    for key, val in values_dict.items():
        opt = parser_options.get(key)
        if opt is None:
            continue
        try:
            if hasattr(opt, "convert"):
                values_dict[key] = opt.convert(val)
            elif hasattr(opt, "type"):
                t = getattr(opt, "type")
                if t is bool:
                    if isinstance(val, str):
                        values_dict[key] = val.lower() in ("1", "true", "yes", "on")
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = t(val)
            else:
                # No convertible attribute, leave as is
                pass
        except Exception:
            # Keep the original string value if conversion fails
            pass
    return values_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path to a directory")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory {plugin_dir} does not exist")

    # Possible spec file names and formats
    spec_files = [
        ("plugin.json", "json"),
        ("plugin_spec.json", "json"),
        ("spec.json", "json"),
        ("plugin.yml", "yaml"),
        ("plugin_spec.yml", "yaml"),
        ("spec.yml", "yaml")
    ]

    data = None
    for filename, fmt in spec_files:
        path = os.path.join(plugin_dir, filename)
        if os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    if fmt == "json":
                        data = json.load(f)
                    else:  # yaml
                        try:
                            import yaml
                            data = yaml.safe_load(f)
                        except ImportError:
                            # yaml not available; skip this file
                            continue
                if isinstance(data, dict):
                    break
            except Exception:
                # Bad file, try the next possibility
                continue

    if data is None:
        # No valid spec found; return empty dict rather than raising
        return {}

    # Helper to flatten nested dicts using dot-notation
    def _flatten(d, parent_key="", out=None):
        if out is None:
            out = {}
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key, out)
            else:
                out[new_key] = value
        return out

    return _flatten(data)<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Attempt to import yaml, but fall back to None if not available.
    try:
        import yaml  # type: ignore
    except Exception:
        yaml = None

    if not plugin_dir or not os.path.isdir(plugin_dir):
        raise ValueError(f"Invalid plugin directory: {plugin_dir}")

    # Define possible spec filenames.
    spec_filenames = ["plugin.json", "plugin.yaml", "plugin.yml", "spec.json", "spec.yaml", "spec.yml"]
    spec_path = None
    for filename in spec_filenames:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. Expected one of: {', '.join(spec_filenames)}"
        )

    # Load the spec file.
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
        if spec_path.endswith((".yaml", ".yml")):
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML plugin specs.")
            spec = yaml.safe_load(content)
        else:
            spec = json.loads(content)
    except Exception as exc:
        raise RuntimeError(f"Failed to read or parse plugin spec at {spec_path}: {exc}")

    if not isinstance(spec, dict):
        raise TypeError(f"Plugin spec must be a mapping, got {type(spec).__name__}")

    # Helper: flatten nested dictionaries using dot notation keys.
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)<|return|>

