def extend_cli(self, root_subparsers):
    """Adds the spec cli options to the main entry point.

    :param root_subparsers: The argument parser (or subparsers) to extend.
    """
    # Ensure we have an argparse parser or subparsers that expose add_argument.
    if not hasattr(root_subparsers, "add_argument"):
        raise TypeError(
            "root_subparsers must be an argparse parser or subparsers object"
        )

    # Add the --spec option. If it already exists, we just leave it untouched.
    try:
        # Check if --spec already defined to avoid duplicate definitions
        existing_args = getattr(root_subparsers, "_actions", [])
        if not any(getattr(a, "dest", None) == "spec" for a in existing_args):
            root_subparsers.add_argument(
                "--spec",
                required=True,
                help="Target spec in the form <path>:<target_name>",
            )
    except Exception as e:
        raise RuntimeError(f"Failed to add '--spec' option: {e}") from e

    # Return the parser for convenience (not strictly required).
    return root_subparsers<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os

    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings")

    if not path or not root:
        raise ValueError("Both path and root must be non-empty")

    # Resolve absolute, normalized paths
    norm_path = os.path.abspath(path)
    norm_root = os.path.abspath(root)

    try:
        rel = os.path.relpath(norm_path, norm_root)
    except Exception as exc:
        raise ValueError(f"Failed to compute relative path from root: {exc}") from exc

    # rel would be '.' if path == root, or start with '..' if not under root
    if rel == "." or rel.startswith(".."):
        raise ValueError(f"Path '{path}' is not located under root '{root}'")

    return rel<|return|>
